      keyName = "volume",
      name = "Dialogue Volume",
      description = "Loudness of spoken dialogue, 0 (muted) to 100.",
      position = 3,
      section = generalSection)
  @Range(min = 0, max = 100)
  default int volume() {
    return 20;
  }

