package com.grahambartley.runelite.voiced.dialogue.audio;

public final class CaveEcho {
  private CaveEcho() {}

  static final int DELAY_MS = 260;
  static final float FEEDBACK = 0.35f;
  static final float DAMPING = 0.40f;
  static final int MAX_TAIL_MS = 2000;

  static final double TAIL_FLOOR = 1e-3;

  public static Pcm apply(Pcm dry) {
    float[] in = dry.getSamples();
    int rate = dry.getSampleRate();
    int d = Math.max(1, Math.round(DELAY_MS * rate / 1000f));

    int hops = (int) Math.ceil(Math.log(TAIL_FLOOR) / Math.log(FEEDBACK));
    int tail = Math.min(hops * d, MAX_TAIL_MS * rate / 1000);
    float[] out = new float[in.length + tail];

    float lp = 0f;
    for (int i = 0; i < out.length; i++) {
      float dryS = i < in.length ? in[i] : 0f;
      float delayed = i >= d ? out[i - d] : 0f;
      lp = DAMPING * lp + (1f - DAMPING) * delayed;
      float s = dryS + FEEDBACK * lp;
      out[i] = s < -1f ? -1f : (s > 1f ? 1f : s);
    }
    return new Pcm(out, rate);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public final class CaveEchoPolicy {

  static final Set<Integer> POH_REGION_IDS =
      Set.of(7257, 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);

  private final Client client;
  private final VoicedDialogueConfig config;

  public CaveEchoPolicy(Client client, VoicedDialogueConfig config) {
    this.client = client;
    this.config = config;
  }

  public boolean shouldEcho() {
    return config.cloudCaveEcho() && isUnderground();
  }

  boolean isUnderground() {
    Player local = client.getLocalPlayer();
    if (local == null) {
      return false;
    }
    LocalPoint lp = local.getLocalLocation();
    WorldPoint wp =
        client.isInInstancedRegion() && lp != null
            ? WorldPoint.fromLocalInstance(client, lp)
            : local.getWorldLocation();
    if (wp == null) {
      return false;
    }
    boolean underground = isUndergroundPoint(wp);
    if (config.debugMode()) {
      log.info(
          "[TTS echo] x={} y={} plane={} region={} instanced={} underground={}",
          wp.getX(),
          wp.getY(),
          wp.getPlane(),
          wp.getRegionID(),
          client.isInInstancedRegion(),
          underground);
    }
    return underground;
  }

  static boolean isUndergroundPoint(WorldPoint wp) {
    if (POH_REGION_IDS.contains(wp.getRegionID())) {
      return false;
    }
    return WorldPoint.getMirrorPoint(wp, true).getY() >= Constants.OVERWORLD_MAX_Y;
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class LoudnessLeveller {

  private static final double FULL_VOLUME_SPEECH_DBFS = -18.0;
  private static final double PEAK_CEILING_DBFS = -1.0;
  private static final double MAX_BOOST_DB = 12.0;
  private static final double SILENCE_GATE_DBFS = -50.0;
  private static final int WINDOW_MS = 20;
  private static final int FULL_VOLUME_PERCENT = 100;
  private static final double STREAMED_SLEW_DB_PER_SECOND = 3.0;
  private static final double STREAMED_LOCK_SPEECH_SECONDS = 3.0;

  private static final double FULL_VOLUME_RMS = dbToAmplitude(FULL_VOLUME_SPEECH_DBFS);
  private static final double PEAK_CEILING = dbToAmplitude(PEAK_CEILING_DBFS);
  private static final double MAX_GAIN = dbToAmplitude(MAX_BOOST_DB);
  private static final double GATE_MEAN_SQUARE =
      dbToAmplitude(SILENCE_GATE_DBFS) * dbToAmplitude(SILENCE_GATE_DBFS);

  private final int sampleRate;
  private final SpeechEnergy heard;
  private float fullVolumeGain;
  private float peak;
  private boolean locked;

  private LoudnessLeveller(int sampleRate, SpeechEnergy heard, float peak, boolean locked) {
    this.sampleRate = sampleRate;
    this.heard = heard;
    this.fullVolumeGain = locked ? heard.fullVolumeGain() : 1f;
    this.peak = peak;
    this.locked = locked;
  }

  public static LoudnessLeveller measure(float[] samples, int sampleRate) {
    SpeechEnergy speech = new SpeechEnergy();
    speech.add(samples, sampleRate);
    return new LoudnessLeveller(sampleRate, speech, peakOf(samples), true);
  }

  public static LoudnessLeveller streaming(int sampleRate) {
    return new LoudnessLeveller(sampleRate, new SpeechEnergy(), 0f, false);
  }

  public void include(float[] chunk) {
    peak = Math.max(peak, peakOf(chunk));
    if (locked) {
      return;
    }
    heard.add(chunk, sampleRate);
    double seconds = (double) chunk.length / sampleRate;
    double wantedDb = amplitudeToDb(heard.fullVolumeGain());
    double currentDb = amplitudeToDb(fullVolumeGain);
    double stepDb = STREAMED_SLEW_DB_PER_SECOND * seconds;
    double nextDb = currentDb + Math.max(-stepDb, Math.min(stepDb, wantedDb - currentDb));
    fullVolumeGain = (float) dbToAmplitude(nextDb);
    locked = heard.seconds(sampleRate) >= STREAMED_LOCK_SPEECH_SECONDS;
  }

  public float gainAt(int volumePercent) {
    int volume = Math.max(0, Math.min(FULL_VOLUME_PERCENT, volumePercent));
    float gain = fullVolumeGain * volume / FULL_VOLUME_PERCENT;
    return peak == 0f ? gain : (float) Math.min(gain, PEAK_CEILING / peak);
  }

  private static float peakOf(float[] samples) {
    float peak = 0f;
    for (float s : samples) {
      peak = Math.max(peak, Math.abs(s));
    }
    return peak;
  }

  private static double dbToAmplitude(double db) {
    return Math.pow(10.0, db / 20.0);
  }

  private static double amplitudeToDb(double amplitude) {
    return 20.0 * Math.log10(amplitude);
  }

  private static final class SpeechEnergy {
    private double energy;
    private long samples;

    void add(float[] chunk, int sampleRate) {
      int window = Math.max(1, sampleRate * WINDOW_MS / 1000);
      for (int start = 0; start < chunk.length; start += window) {
        int end = Math.min(chunk.length, start + window);
        double windowEnergy = 0;
        for (int i = start; i < end; i++) {
          windowEnergy += (double) chunk[i] * chunk[i];
        }
        if (windowEnergy / (end - start) > GATE_MEAN_SQUARE) {
          energy += windowEnergy;
          samples += end - start;
        }
      }
    }

    double seconds(int sampleRate) {
      return (double) samples / sampleRate;
    }

    float fullVolumeGain() {
      if (samples == 0) {
        return 1f;
      }
      return (float) Math.min(FULL_VOLUME_RMS / Math.sqrt(energy / samples), MAX_GAIN);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class Pcm {
  private final float[] samples;
  private final int sampleRate;

  public Pcm(float[] samples, int sampleRate) {
    this.samples = samples;
    this.sampleRate = sampleRate;
  }

  public float[] getSamples() {
    return samples;
  }

  public int getSampleRate() {
    return sampleRate;
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import javax.sound.sampled.AudioFormat;

public final class PcmAudio {

  private PcmAudio() {}

  public static byte[] toPcm16LE(float[] samples, int from, int to, float gain) {
    byte[] pcm = new byte[(to - from) * 2];
    for (int i = from; i < to; i++) {
      float clamped = Math.max(-1f, Math.min(1f, samples[i] * gain));
      int s = Math.round(clamped * 32767f);
      pcm[2 * (i - from)] = (byte) (s & 0xff);
      pcm[2 * (i - from) + 1] = (byte) ((s >> 8) & 0xff);
    }
    return pcm;
  }

  public static AudioFormat format(int sampleRate) {
    return new AudioFormat(sampleRate, 16, 1, true, false);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class PcmCompleteness {

  private static final float SILENCE_FLOOR = 0.02f;

  private static final int MIN_TRAILING_SILENCE_MS = 120;

  private static final int MIN_JUDGED_MS = 500;

  private PcmCompleteness() {}

  public static boolean isTruncated(Pcm pcm, double speedRatio) {
    int rate = pcm.getSampleRate();
    if (rate <= 0) {
      return false;
    }
    float[] samples = pcm.getSamples();
    if (samples.length < msToSamples(MIN_JUDGED_MS, rate)) {
      return false;
    }
    double ratio = speedRatio > 0 ? speedRatio : 1.0;
    int needed = Math.max(1, (int) Math.round(msToSamples(MIN_TRAILING_SILENCE_MS, rate) / ratio));
    int quiet = 0;
    for (int i = samples.length - 1; i >= 0; i--) {
      if (Math.abs(samples[i]) >= SILENCE_FLOOR) {
        break;
      }
      if (++quiet >= needed) {
        return false;
      }
    }
    return true;
  }

  private static int msToSamples(int ms, int rate) {
    return Math.round(ms / 1000f * rate);
  }
}

