public interface PcmSink {

  void accept(float[] samples, int sampleRate);
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class RawPcmDecoder {

  private RawPcmDecoder() {}

  public static Pcm decode(byte[] pcm, int sampleRate) {
    if (pcm == null || pcm.length < 2 || sampleRate <= 0) {
      return null;
    }
    if ((pcm.length & 1) != 0) {
      return null;
    }
    int sampleCount = pcm.length / 2;
    float[] samples = new float[sampleCount];
    for (int i = 0; i < sampleCount; i++) {
      int lo = pcm[2 * i] & 0xff;
      int hi = pcm[2 * i + 1];
      short s = (short) ((hi << 8) | lo);
      samples[i] = s / 32768f;
    }
    return new Pcm(samples, sampleRate);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.SourceDataLine;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class StreamingAudioPlayer implements AudioOutput {

  public interface LineFactory {
    SourceDataLine getLine(AudioFormat format) throws LineUnavailableException;
  }

  private static final int WRITE_BLOCK_SAMPLES = 2048;

  private static final int QUEUE_POLL_MS = 20;

  private final LineFactory lineFactory;
  private final AtomicLong generation = new AtomicLong();
  private volatile SourceDataLine line;
  private volatile int volumePercent;

  public StreamingAudioPlayer() {
    this(AudioSystem::getSourceDataLine);
  }

  StreamingAudioPlayer(LineFactory lineFactory) {
    this.lineFactory = lineFactory;
  }

  @Override
  public void stream(float[] samples, int sampleRate, int volumePercent) {
    if (samples == null || samples.length == 0) {
      return;
    }
    long gen = generation.incrementAndGet();
    this.volumePercent = volumePercent;
    LoudnessLeveller leveller = LoudnessLeveller.measure(samples, sampleRate);
    SourceDataLine sdl = null;
    try {
      sdl = openLine(PcmAudio.format(sampleRate));
      writeLevelled(sdl, samples, leveller, gen);
      if (generation.get() == gen) {
        sdl.drain();
      }
    } catch (Exception e) {
      log.warn("Audio playback failed: {}", e.getMessage());
    } finally {
      if (sdl != null) {
        releaseLine(sdl);
      }
    }
  }

  @Override
  public AudioStream beginStream(int volumePercent) {
    long gen = generation.incrementAndGet();
    this.volumePercent = volumePercent;
    return new BufferedLineStream(gen);
  }

  @Override
  public void setVolume(int volumePercent) {
    this.volumePercent = volumePercent;
  }

  @Override
  public void stop() {
    generation.incrementAndGet();
    SourceDataLine current = this.line;
    if (current != null) {
      try {
        current.stop();
        current.flush();
      } catch (Exception ignored) {
      }
    }
  }

  @Override
  public void close() {
    stop();
  }

  private final class BufferedLineStream implements AudioStream {
    private final long gen;
    private final BlockingQueue<float[]> queue = new LinkedBlockingQueue<>();
    private volatile int sampleRate = -1;
    private volatile boolean ended;
    private boolean playerStarted;

    private BufferedLineStream(long gen) {
      this.gen = gen;
    }

    @Override
    public void write(float[] samples, int sampleRate) {
      if (samples == null || samples.length == 0 || generation.get() != gen) {
        return;
      }
      if (this.sampleRate < 0) {
        this.sampleRate = sampleRate;
      }
      queue.offer(samples);
      startPlayer();
    }

    @Override
    public void end() {
      ended = true;
      startPlayer();
    }

    private synchronized void startPlayer() {
      if (playerStarted || sampleRate < 0) {
        return;
      }
      playerStarted = true;
      Thread player = new Thread(this::playLoop, "dialogue-audio-play");
      player.setDaemon(true);
      player.start();
    }

    private void playLoop() {
      SourceDataLine sdl = null;
      try {
        sdl = openLine(PcmAudio.format(sampleRate));
        LoudnessLeveller leveller = LoudnessLeveller.streaming(sampleRate);
        float[] chunk;
        while ((chunk = nextChunk()) != null) {
          leveller.include(chunk);
          writeLevelled(sdl, chunk, leveller, gen);
        }
        if (generation.get() == gen) {
          sdl.drain();
        }
      } catch (Exception e) {
        log.warn("Audio streaming failed: {}", e.getMessage());
      } finally {
        if (sdl != null) {
          releaseLine(sdl);
        }
      }
    }

    private float[] nextChunk() throws InterruptedException {
      while (generation.get() == gen) {
        float[] chunk = queue.poll(QUEUE_POLL_MS, TimeUnit.MILLISECONDS);
        if (chunk != null) {
          return chunk;
        }
        if (ended && queue.isEmpty()) {
          return null;
        }
      }
      return null;
    }
  }

  private SourceDataLine openLine(AudioFormat format) throws LineUnavailableException {
    SourceDataLine sdl = lineFactory.getLine(format);
    boolean opened = false;
    try {
      sdl.open(format);
      sdl.start();
      this.line = sdl;
      opened = true;
      return sdl;
    } finally {
      if (!opened) {
        releaseLine(sdl);
      }
    }
  }

  private void writeLevelled(
      SourceDataLine sdl, float[] samples, LoudnessLeveller leveller, long gen) {
    for (int from = 0;
        from < samples.length && generation.get() == gen;
        from += WRITE_BLOCK_SAMPLES) {
      int to = Math.min(samples.length, from + WRITE_BLOCK_SAMPLES);
      byte[] pcm = PcmAudio.toPcm16LE(samples, from, to, leveller.gainAt(volumePercent));
      int offset = 0;
      while (offset < pcm.length && generation.get() == gen) {
        offset += sdl.write(pcm, offset, pcm.length - offset);
      }
    }
  }

  private void releaseLine(SourceDataLine sdl) {
    try {
      sdl.stop();
      sdl.close();
    } catch (Exception ignored) {
    }
    if (this.line == sdl) {
      this.line = null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

public final class StreamingPcmDecoder {

  private static final float[] EMPTY = new float[0];

  private int pendingLowByte = -1;

  public float[] decode(byte[] chunk, int len) {
    if (chunk == null || len <= 0) {
      return EMPTY;
    }
    int totalBytes = len + (pendingLowByte >= 0 ? 1 : 0);
    int sampleCount = totalBytes / 2;
    if (sampleCount == 0) {
      if (pendingLowByte < 0) {
        pendingLowByte = chunk[0] & 0xff;
      }
      return EMPTY;
    }
    float[] out = new float[sampleCount];
    int bi = 0;
    int oi = 0;
    if (pendingLowByte >= 0) {
      out[oi++] = sampleToFloat(pendingLowByte, chunk[bi++]);
      pendingLowByte = -1;
    }
    while (len - bi >= 2) {
      out[oi++] = sampleToFloat(chunk[bi] & 0xff, chunk[bi + 1]);
      bi += 2;
    }
    if (len - bi == 1) {
      pendingLowByte = chunk[bi] & 0xff;
    }
    return out;
  }

  public boolean hasPendingByte() {
    return pendingLowByte >= 0;
  }

  private static float sampleToFloat(int lo, int hi) {
    short s = (short) ((hi << 8) | (lo & 0xff));
    return s / 32768f;
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class DiskAudioCache {

  private static final int MAGIC = 0x54_44_43_31;

  private static final int HEADER_BYTES = 16;

  public static final long DEFAULT_MAX_BYTES = 256L * 1024 * 1024;

  public static final long UNLIMITED = 0;

  private final Path dir;
  private final LongSupplier maxBytes;

  private volatile boolean disabled;

  public DiskAudioCache(Path dir) {
    this(dir, DEFAULT_MAX_BYTES);
  }

  public DiskAudioCache(Path dir, long maxBytes) {
    this(dir, () -> maxBytes);
  }

  public DiskAudioCache(Path dir, LongSupplier maxBytes) {
    this.dir = dir;
    this.maxBytes = maxBytes;
  }

  public Pcm get(String namespace, String voiceKey, Emotion emotion, String text) {
    if (disabled) {
      return null;
    }
    Path file;
    try {
      file = fileFor(namespace, voiceKey, emotion, text);
    } catch (RuntimeException e) {
      return null;
    }
    if (!Files.isRegularFile(file)) {
      return null;
    }
    try {
      Pcm pcm = decode(Files.readAllBytes(file));
      if (pcm == null) {
        deleteQuietly(file);
        return null;
      }
      return pcm;
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache read failed for {}; treating as miss", file.getFileName(), e);
      deleteQuietly(file);
      return null;
    }
  }

  public void put(String namespace, String voiceKey, Emotion emotion, String text, Pcm pcm) {
    if (disabled || pcm == null || pcm.getSamples() == null) {
      return;
    }
    Path file;
    try {
      ensureDir();
      file = fileFor(namespace, voiceKey, emotion, text);
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache unavailable; disabling on-disk caching", e);
      disabled = true;
      return;
    }
    Path tmp = null;
    try {
      tmp = Files.createTempFile(dir, file.getFileName().toString(), ".tmp");
      Files.write(tmp, encode(pcm));
      try {
        Files.move(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
      } catch (IOException atomicUnsupported) {
        Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);
      }
      tmp = null;
      enforceSizeCap();
    } catch (IOException | RuntimeException e) {
      log.debug("Disk cache write failed for {}; skipping", file.getFileName(), e);
    } finally {
      if (tmp != null) {
        deleteQuietly(tmp);
      }
    }
  }

  private Path fileFor(String namespace, String voiceKey, Emotion emotion, String text) {
    return dir.resolve(hashKey(namespace, voiceKey, emotion, text) + ".tdc");
  }

  private static String hashKey(String namespace, String voiceKey, Emotion emotion, String text) {
    try {
      MessageDigest md = MessageDigest.getInstance("SHA-256");
      feed(md, namespace);
      feed(md, voiceKey);
      feed(md, emotion == null ? "null" : emotion.name());
      feed(md, text);
      byte[] digest = md.digest();
      StringBuilder sb = new StringBuilder(digest.length * 2);
      for (byte b : digest) {
        sb.append(Character.forDigit((b >> 4) & 0xF, 16));
        sb.append(Character.forDigit(b & 0xF, 16));
      }
      return sb.toString();
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException("SHA-256 unavailable", e);
    }
  }

  private static void feed(MessageDigest md, String field) {
    byte[] bytes = field == null ? new byte[0] : field.getBytes(StandardCharsets.UTF_8);
    ByteBuffer len = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(bytes.length);
    md.update(len.array());
    md.update(bytes);
  }

  private static byte[] encode(Pcm pcm) {
    float[] samples = pcm.getSamples();
    ByteBuffer buf =
        ByteBuffer.allocate(HEADER_BYTES + samples.length * 4).order(ByteOrder.LITTLE_ENDIAN);
    buf.putInt(MAGIC);
    buf.putInt(pcm.getSampleRate());
    buf.putInt(samples.length);
    buf.putInt(0);
    buf.asFloatBuffer().put(samples);
    return buf.array();
  }

  private static Pcm decode(byte[] bytes) {
    if (bytes.length < HEADER_BYTES) {
      return null;
    }
    ByteBuffer buf = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
    if (buf.getInt() != MAGIC) {
      return null;
    }
    int sampleRate = buf.getInt();
    int sampleCount = buf.getInt();
    buf.getInt();
    if (sampleRate <= 0 || sampleCount < 0) {
      return null;
    }
    if (bytes.length != HEADER_BYTES + (long) sampleCount * 4) {
      return null;
    }
    float[] samples = new float[sampleCount];
    buf.asFloatBuffer().get(samples);
    return new Pcm(samples, sampleRate);
  }

  private void ensureDir() throws IOException {
    if (!Files.isDirectory(dir)) {
      Files.createDirectories(dir);
    }
  }

  private static void deleteQuietly(Path file) {
    try {
      Files.deleteIfExists(file);
    } catch (IOException ignored) {
    }
  }

  private void enforceSizeCap() {
    long cap = maxBytes.getAsLong();
    if (cap <= UNLIMITED) {
      return;
    }
    List<Entry> entries = new ArrayList<>();
    long total = 0;
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        try {
          BasicFileAttributes attrs = Files.readAttributes(p, BasicFileAttributes.class);
          if (attrs.isRegularFile()) {
            entries.add(new Entry(p, attrs.size(), attrs.lastModifiedTime().toMillis()));
            total += attrs.size();
          }
        } catch (IOException ignored) {
        }
      }
    } catch (IOException e) {
      log.debug("Disk cache size scan failed; skipping eviction this round", e);
      return;
    }
    if (total <= cap) {
      return;
    }
    entries.sort(Comparator.comparingLong(e -> e.mtime));
    for (Entry e : entries) {
      if (total <= cap) {
        break;
      }
      deleteQuietly(e.path);
      total -= e.size;
    }
  }

  private static final class Entry {
    final Path path;
    final long size;
    final long mtime;

    Entry(Path path, long size, long mtime) {
      this.path = path;
      this.size = size;
      this.mtime = mtime;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import java.util.LinkedHashMap;
import java.util.Map;

public final class LruCache<K, V> {

  private final int maxSize;
  private final LinkedHashMap<K, V> map;

  public LruCache(int maxSize) {
    if (maxSize < 1) {
      throw new IllegalArgumentException("maxSize must be at least 1");
    }
    this.maxSize = maxSize;
    this.map =
        new LinkedHashMap<K, V>(16, 0.75f, true) {
          @Override
          protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > LruCache.this.maxSize;
          }
        };
  }

  public synchronized V get(K key) {
    return map.get(key);
  }

  public synchronized void put(K key, V value) {
    map.put(key, value);
  }

  public synchronized boolean containsKey(K key) {
    return map.containsKey(key);
  }

  public synchronized int size() {
    return map.size();
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import lombok.Value;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class TieredSynthesisCache {

  private static final int LOG_TEXT_PREVIEW_LENGTH = 40;

  @Value
  @Accessors(fluent = true)
  public static class CacheKey {
    String namespace;
    String voiceKey;
    Emotion emotion;
    String text;

    public String textPreview() {
      return text.length() <= LOG_TEXT_PREVIEW_LENGTH
          ? text
          : text.substring(0, LOG_TEXT_PREVIEW_LENGTH) + "...";
    }
  }

  public final LruCache<CacheKey, Pcm> memory;
  private final DiskAudioCache disk;
  public final ConcurrentHashMap<CacheKey, CompletableFuture<Pcm>> inFlight =
      new ConcurrentHashMap<>();

  public TieredSynthesisCache(int maxEntries, DiskAudioCache disk) {
    this.memory = new LruCache<>(maxEntries);
    this.disk = disk;
  }

  public Pcm memoryHit(CacheKey key) {
    return memory.get(key);
  }

  public Pcm lookup(CacheKey key) {
    long start = System.nanoTime();
    Pcm pcm = memory.get(key);
    if (pcm != null) {
      log.debug(
          "[TTS cache] hit tier=memory lookupMs={} ({}/{}) \"{}\"",
          elapsedMs(start),
          key.namespace(),
          key.voiceKey(),
          key.textPreview());
      return pcm;
    }
    if (disk != null) {
      pcm = disk.get(key.namespace(), key.voiceKey(), key.emotion(), key.text());
      if (pcm != null) {
        memory.put(key, pcm);
        log.debug(
            "[TTS cache] hit tier=disk lookupMs={} ({}/{}) \"{}\"",
            elapsedMs(start),
            key.namespace(),
            key.voiceKey(),
            key.textPreview());
      }
    }
    return pcm;
  }

  public Pcm withInFlight(CacheKey key, Supplier<Pcm> synth, Runnable onDeduped) {
    CompletableFuture<Pcm> own = new CompletableFuture<>();
    CompletableFuture<Pcm> running = inFlight.putIfAbsent(key, own);
    if (running != null) {
      onDeduped.run();
      return await(running);
    }
    Pcm pcm = null;
    try {
      pcm = synth.get();
      if (pcm != null) {
        writeThrough(key, pcm);
      }
    } finally {
      own.complete(pcm);
      inFlight.remove(key, own);
    }
    return pcm;
  }

  private void writeThrough(CacheKey key, Pcm pcm) {
    memory.put(key, pcm);
    if (disk != null) {
      disk.put(key.namespace(), key.voiceKey(), key.emotion(), key.text(), pcm);
    }
  }

  private static Pcm await(CompletableFuture<Pcm> future) {
    try {
      return future.join();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static long elapsedMs(long startNanos) {
    return (System.nanoTime() - startNanos) / 1_000_000L;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.OverheadTextChanged;

public final class AmbientChatterWatcher {

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;
  private final BooleanSupplier enabled;
  private final BooleanSupplier conversationOnScreen;
  private final IntSupplier volume;

  public AmbientChatterWatcher(
      Client client,
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled,
      BooleanSupplier conversationOnScreen,
      IntSupplier volume) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
    this.conversationOnScreen = conversationOnScreen;
    this.volume = volume;
  }

  public void onOverheadTextChanged(OverheadTextChanged event) {
    if (!enabled.getAsBoolean()) {
      return;
    }
    Actor actor = event.getActor();
    if (!(actor instanceof NPC)) {
      return;
    }
    NPC npc = (NPC) actor;
    String overheadText = event.getOverheadText();
    if (overheadText == null
        || !AmbientEarshot.isWithinEarshot(distanceTo(npc))
        || conversationOnScreen.getAsBoolean()) {
      return;
    }
    String cleaned = textCleaner.clean(overheadText);
    if (cleaned.isEmpty() || AnimalNoises.isNothingButNoise(cleaned)) {
      return;
    }
    dispatcher.speakAmbient(cleaned, npc, () -> volumeFor(npc));
  }

  private int volumeFor(NPC npc) {
    int distance = distanceTo(npc);
    if (!AmbientEarshot.isWithinEarshot(distance)) {
      return AmbientEarshot.OUT_OF_EARSHOT;
    }
    return AmbientEarshot.volumeAt(volume.getAsInt(), distance);
  }

  private int distanceTo(NPC npc) {
    Player local = client.getLocalPlayer();
    if (local == null) {
      return Integer.MAX_VALUE;
    }
    WorldPoint listener = local.getWorldLocation();
    WorldPoint speaker = npc.getWorldLocation();
    if (listener == null || speaker == null) {
      return Integer.MAX_VALUE;
    }
    return listener.distanceTo(speaker);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

public final class AmbientEarshot {

  public static final int EARSHOT_TILES = 16;

  public static final int OUT_OF_EARSHOT = -1;

  static final int FAINTEST = 1;

  private AmbientEarshot() {}

  public static boolean isWithinEarshot(int distanceTiles) {
    return distanceTiles >= 0 && distanceTiles <= EARSHOT_TILES;
  }

  public static int volumeAt(int configuredVolume, int distanceTiles) {
    if (configuredVolume <= FAINTEST) {
      return configuredVolume;
    }
    if (distanceTiles >= EARSHOT_TILES) {
      return FAINTEST;
    }
    int travelled = Math.max(0, distanceTiles);
    int span = configuredVolume - FAINTEST;
    return configuredVolume - (span * travelled) / EARSHOT_TILES;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import java.util.regex.Pattern;

public final class AnimalNoises {

  private static final Pattern SEPARATOR = Pattern.compile("[\\s\\p{Punct}&&[^-]]+");

  private static final Pattern NOISE =
      Pattern.compile(
          "ba+|bah+|maa+|meh+|moo+|quack+|cluck+|cock-?a-?doodle-?doo|squeak+|squeal+"
              + "|woof+|bark+|arf+|yap+|howl+|gr+|growl+|snarl+|roar+|meow+|miaow+|mew+"
              + "|purr+|hiss+|ss+|oink+|snort+|neigh+|whinny+|bray+|hee-?haw|tweet+|chirp+|caw+"
              + "|squawk+|screech+|hoot+|ook+|eek+|ook-?ook|ribbit+|croak+|buzz+|chitter+"
              + "|click+|whistle+|bleat+|trumpet+|bellow+|yowl+|whine+|wuff+|rawr+|grunt+",
          Pattern.CASE_INSENSITIVE);

  private AnimalNoises() {}

  public static boolean isNothingButNoise(String line) {
    if (line == null || line.isEmpty()) {
      return false;
    }
    boolean sawWord = false;
    for (String token : SEPARATOR.split(line)) {
      if (token.isEmpty()) {
        continue;
      }
      sawWord = true;
      if (!NOISE.matcher(token).matches()) {
        return false;
      }
    }
    return sawWord;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisBackend;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

@Slf4j
public final class ChatNoticeManager {

  static final String ONBOARDING_SEEN_KEY = "onboardingSeen";

  private static final String CHAT_NOTICE_COLOR = "ff3333";

  private static final String ONBOARDING_MESSAGE =
      "Voiced Dialogue is on. It needs an API key to voice dialogue. Google AI Studio starts lines"
          + " almost instantly but caps fresh lines a day, prefetched options included, and raises"
          + " that cap as your usage tier rises: set Voice Provider to Google AI Studio and"
          + " use a key from aistudio.google.com with billing enabled. OpenRouter is"
          + " simpler to set up and has no daily cap, at the cost of much slower lines: use a key"
          + " from openrouter.ai instead. Your dialogue text is sent to whichever provider you"
          + " pick. Until a key is set, lines stay silent.";

  private final Client client;
  private final ConfigManager configManager;
  private final ClientThread clientThread;
  private final ChatMessageManager chatMessageManager;

  private boolean onboardingChecked;
  private boolean cloudKeyNoticeChecked;

  public ChatNoticeManager(
      Client client,
      ConfigManager configManager,
      ClientThread clientThread,
      ChatMessageManager chatMessageManager) {
    this.client = client;
    this.configManager = configManager;
    this.clientThread = clientThread;
    this.chatMessageManager = chatMessageManager;
  }

  public void notifyFromBackendThread(String message) {
    log.warn(message);
    clientThread.invokeLater(() -> addGameMessage(message));
  }

  public void maybeShowOnboarding() {
    if (onboardingChecked) {
      return;
    }
    onboardingChecked = true;
    Boolean seen =
        configManager.getConfiguration(
            VoicedDialogueConfig.GROUP, ONBOARDING_SEEN_KEY, Boolean.class);
    if (!shouldShowOnboarding(seen)) {
      return;
    }
    addGameMessage(ONBOARDING_MESSAGE);
    configManager.setConfiguration(VoicedDialogueConfig.GROUP, ONBOARDING_SEEN_KEY, true);
  }

  static boolean shouldShowOnboarding(Boolean seenFlag) {
    return !Boolean.TRUE.equals(seenFlag);
  }

  public void maybeWarnMissingCloudKey(SynthesisBackend backend) {
    if (cloudKeyNoticeChecked || !shouldWarnMissingCloudKey(backend.isAvailable())) {
      return;
    }
    cloudKeyNoticeChecked = true;
    addGameMessage(backend.missingKeyNotice());
  }

  static boolean shouldWarnMissingCloudKey(boolean keyAvailable) {
    return !keyAvailable;
  }

  public void postCommandResponse(String message) {
    String formatted =
        new ChatMessageBuilder()
            .append(ChatColorType.HIGHLIGHT)
            .append("[Voiced Dialogue] ")
            .append(ChatColorType.NORMAL)
            .append(message)
            .build();
    chatMessageManager.queue(
        QueuedMessage.builder()
            .type(ChatMessageType.GAMEMESSAGE)
            .runeLiteFormattedMessage(formatted)
            .build());
  }

  private void addGameMessage(String message) {
    String line = "<col=" + CHAT_NOTICE_COLOR + ">[Voiced Dialogue] " + message + "</col>";
    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", line, null);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.ResolvedSpeaker;
import com.grahambartley.runelite.voiced.dialogue.profile.Speaker;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceManager;
import com.grahambartley.runelite.voiced.dialogue.speech.BackendProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.widgets.Widget;

public final class DialoguePrefetchCoordinator {

  private static final String OPTION_HEADER = "Select an Option";

  private final VoiceManager voiceManager;
  private final DialogueTextCleaner textCleaner;
  private final DialoguePrefetcher prefetcher;
  private final BackendProvider backendProvider;
  private final VoicedDialogueConfig config;

  private List<String> lastRawOptions = Collections.emptyList();

  public DialoguePrefetchCoordinator(
      VoiceManager voiceManager,
      DialogueTextCleaner textCleaner,
      DialoguePrefetcher prefetcher,
      BackendProvider backendProvider,
      VoicedDialogueConfig config) {
    this.voiceManager = voiceManager;
    this.textCleaner = textCleaner;
    this.prefetcher = prefetcher;
    this.backendProvider = backendProvider;
    this.config = config;
  }

  void prefetchOptions(Widget options) {
    if (!config.prefetch() || !backendProvider.active().isAvailable()) {
      return;
    }
    Widget[] children = options.getDynamicChildren();
    if (children == null || children.length == 0) {
      return;
    }
    List<String> raw = new ArrayList<>(children.length);
    for (Widget child : children) {
      raw.add(child == null ? null : child.getText());
    }
    if (raw.equals(lastRawOptions)) {
      return;
    }
    lastRawOptions = raw;

    ResolvedSpeaker resolved = voiceManager.resolve(Speaker.PLAYER, null);
    List<SynthesisRequest> candidates = new ArrayList<>(raw.size());
    for (String text : raw) {
      if (text == null) {
        continue;
      }
      String cleaned = textCleaner.clean(text);
      if (cleaned.isEmpty() || OPTION_HEADER.equalsIgnoreCase(cleaned)) {
        continue;
      }
      candidates.add(
          new SynthesisRequest(
                  cleaned, resolved.voice(), Emotion.NEUTRAL, resolved.profile(), false, true)
              .asPrefetch());
    }
    prefetcher.offer(candidates);
  }

  void reset() {
    lastRawOptions = Collections.emptyList();
    prefetcher.reset();
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;

public final class DialoguePrefetcher {

  static final int MAX_PER_SESSION = 10;

  private final Consumer<SynthesisRequest> sink;
  private final Runnable canceller;

  private final Set<SynthesisRequest> submitted = new HashSet<>();

  private int count;

  public DialoguePrefetcher(Consumer<SynthesisRequest> sink, Runnable canceller) {
    this.sink = sink;
    this.canceller = canceller;
  }

  public void offer(List<SynthesisRequest> candidates) {
    if (candidates == null || candidates.isEmpty()) {
      return;
    }
    for (SynthesisRequest request : candidates) {
      if (count >= MAX_PER_SESSION) {
        break;
      }
      if (request == null || request.text() == null || request.text().isEmpty()) {
        continue;
      }
      if (!submitted.add(request)) {
        continue;
      }
      count++;
      sink.accept(request);
    }
  }

  public void reset() {
    submitted.clear();
    count = 0;
    canceller.run();
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import java.util.regex.Pattern;

public final class DialogueTextCleaner {

  private static final Pattern MARKUP = Pattern.compile("<[^>]+>");

  private final ProfanityFilter profanityFilter;

  public DialogueTextCleaner(ProfanityFilter profanityFilter) {
    this.profanityFilter = profanityFilter;
  }

  public String clean(String raw) {
    return profanityFilter.mask(MARKUP.matcher(raw).replaceAll("").trim());
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static com.grahambartley.runelite.voiced.dialogue.capture.DialogueWidgetReader.isVisible;

import com.grahambartley.runelite.voiced.dialogue.profile.Speaker;
import com.grahambartley.runelite.voiced.dialogue.speech.DialogueAudioService;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class DialogueWatcher {

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final DialogueWidgetReader widgetReader;
  private final SynthesisDispatcher dispatcher;
  private final DialoguePrefetchCoordinator prefetchCoordinator;
  private final DialogueAudioService audioService;
  private final NarrationWatcher narrationWatcher;

  private final Map<Speaker, String> lastSpokenBySpeaker = new EnumMap<>(Speaker.class);

  private boolean dialogueOpen;
  private boolean wasFullyClosed;

  public DialogueWatcher(
      Client client,
      DialogueTextCleaner textCleaner,
      DialogueWidgetReader widgetReader,
      SynthesisDispatcher dispatcher,
      DialoguePrefetchCoordinator prefetchCoordinator,
      DialogueAudioService audioService,
      NarrationWatcher narrationWatcher) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.widgetReader = widgetReader;
    this.dispatcher = dispatcher;
    this.prefetchCoordinator = prefetchCoordinator;
    this.audioService = audioService;
    this.narrationWatcher = narrationWatcher;
  }

  public void tick() {
    Widget npcDialogue = client.getWidget(InterfaceID.ChatLeft.TEXT);
    boolean npcVisible = isVisible(npcDialogue);
    Widget playerDialogue = client.getWidget(InterfaceID.ChatRight.TEXT);
    boolean playerVisible = isVisible(playerDialogue);

    if (npcVisible) {
      speakIfNew(npcDialogue, InterfaceID.ChatLeft.HEAD, Speaker.NPC, widgetReader::currentNpcName);
    }
    if (playerVisible) {
      speakIfNew(playerDialogue, InterfaceID.ChatRight.HEAD, Speaker.PLAYER, () -> null);
    }

    boolean narrationVisible = narrationWatcher.tick();

    Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
    boolean optionsVisible = isVisible(options);
    if (optionsVisible) {
      prefetchCoordinator.prefetchOptions(options);
    }

    boolean open = npcVisible || playerVisible || narrationVisible;
    if (shouldCutOnClose(open, dialogueOpen)) {
      audioService.cutPlayback();
      lastSpokenBySpeaker.clear();
      narrationWatcher.reset();
    }
    dialogueOpen = open;

    boolean fullyClosed = !open && !optionsVisible;
    if (fullyClosed && !wasFullyClosed) {
      prefetchCoordinator.reset();
    }
    wasFullyClosed = fullyClosed;
  }

  public boolean isDialogueOpen() {
    return dialogueOpen;
  }

  public boolean isConversationOnScreen() {
    return isVisible(client.getWidget(InterfaceID.ChatLeft.TEXT))
        || isVisible(client.getWidget(InterfaceID.ChatRight.TEXT))
        || isVisible(client.getWidget(InterfaceID.Chatmenu.OPTIONS))
        || narrationWatcher.isOnScreen();
  }

  private void speakIfNew(
      Widget dialogue, int headWidgetId, Speaker speaker, Supplier<String> npcName) {
    String text = dialogue.getText();
    if (text == null || text.isEmpty() || text.equals(lastSpokenBySpeaker.get(speaker))) {
      return;
    }
    lastSpokenBySpeaker.put(speaker, text);
    dispatcher.speakDialogue(
        textCleaner.clean(text),
        speaker,
        npcName.get(),
        widgetReader.headAnimationId(headWidgetId));
  }

  static boolean shouldCutOnClose(boolean dialogueOpen, boolean wasDialogueOpen) {
    return wasDialogueOpen && !dialogueOpen;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class DialogueWidgetReader {

  static final int NO_EXPRESSION = -1;

  private static final String UNKNOWN_NPC = "Unknown NPC";

  private final Client client;

  public DialogueWidgetReader(Client client) {
    this.client = client;
  }

  static boolean isVisible(Widget widget) {
    return widget != null && !widget.isHidden();
  }

  int headAnimationId(int headWidgetId) {
    Widget head = client.getWidget(headWidgetId);
    if (head == null) {
      return NO_EXPRESSION;
    }
    return head.getAnimationId();
  }

  String currentNpcName() {
    Widget npcNameWidget = client.getWidget(InterfaceID.ChatLeft.NAME);
    if (isVisible(npcNameWidget)) {
      String npcName = npcNameWidget.getText();
      if (npcName != null && !npcName.isEmpty()) {
        return npcName.trim();
      }
    }

    Player local = client.getLocalPlayer();
    if (local != null && local.getInteracting() != null) {
      String interactingName = local.getInteracting().getName();
      if (interactingName != null && !interactingName.isEmpty()) {
        return interactingName.trim();
      }
    }

    return UNKNOWN_NPC;
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;

public final class ExamineSpeaker {

  private static final Set<ChatMessageType> EXAMINE_TYPES =
      EnumSet.of(
          ChatMessageType.ITEM_EXAMINE,
          ChatMessageType.NPC_EXAMINE,
          ChatMessageType.OBJECT_EXAMINE);

  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;

  private final BooleanSupplier enabled;

  private final BooleanSupplier dialogueOpen;

  private final Consumer<Runnable> defer;

  public ExamineSpeaker(
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled,
      BooleanSupplier dialogueOpen,
      Consumer<Runnable> defer) {
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
    this.dialogueOpen = dialogueOpen;
    this.defer = defer;
  }

  public void onChatMessage(ChatMessage event) {
    if (!EXAMINE_TYPES.contains(event.getType()) || !enabled.getAsBoolean()) {
      return;
    }
    String message = event.getMessage();
    if (message == null) {
      return;
    }
    MessageNode node = event.getMessageNode();
    defer.accept(() -> speakIfGameAuthored(node, message));
  }

  private void speakIfGameAuthored(MessageNode node, String message) {
    if (node != null && node.getRuneLiteFormatMessage() != null) {
      return;
    }
    if (dialogueOpen.getAsBoolean()) {
      return;
    }
    String cleaned = textCleaner.clean(message);
    if (cleaned.isEmpty()) {
      return;
    }
    dispatcher.speakNarration(cleaned);
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static com.grahambartley.runelite.voiced.dialogue.capture.DialogueWidgetReader.isVisible;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.Arrays;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class NarrationWatcher {

  private static final int[] TEXT_WIDGETS = {
    InterfaceID.Objectbox.TEXT, InterfaceID.ObjectboxDouble.TEXT, InterfaceID.Messagebox.TEXT
  };

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;
  private final BooleanSupplier enabled;

  private final String[] lastSpokenByWidget = new String[TEXT_WIDGETS.length];

  public NarrationWatcher(
      Client client,
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
  }

  public boolean isOnScreen() {
    for (int widgetId : TEXT_WIDGETS) {
      if (isVisible(client.getWidget(widgetId))) {
        return true;
      }
    }
    return false;
  }

  public boolean tick() {
    if (!enabled.getAsBoolean()) {
      return false;
    }
    boolean open = false;
    for (int i = 0; i < TEXT_WIDGETS.length; i++) {
      Widget box = client.getWidget(TEXT_WIDGETS[i]);
      if (!isVisible(box)) {
        continue;
      }
      open = true;
      speakIfNew(i, box);
    }
    return open;
  }

  public void reset() {
    Arrays.fill(lastSpokenByWidget, null);
  }

  private void speakIfNew(int index, Widget box) {
    String text = box.getText();
    if (text == null || text.isEmpty() || text.equals(lastSpokenByWidget[index])) {
      return;
    }
    lastSpokenByWidget[index] = text;
    dispatcher.speakNarration(textCleaner.clean(text));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import net.runelite.client.util.Text;

public final class PublicChatPolicy {

  private PublicChatPolicy() {}

  public static boolean isSelfPublicChat(String eventName, String localName) {
    if (eventName == null || localName == null) {
      return false;
    }
    return Text.sanitize(eventName).equals(Text.sanitize(localName));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.function.BooleanSupplier;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;

public final class PublicChatSpeaker {

  private final Client client;
  private final DialogueTextCleaner textCleaner;
  private final SynthesisDispatcher dispatcher;

  private final BooleanSupplier enabled;

  public PublicChatSpeaker(
      Client client,
      DialogueTextCleaner textCleaner,
      SynthesisDispatcher dispatcher,
      BooleanSupplier enabled) {
    this.client = client;
    this.textCleaner = textCleaner;
    this.dispatcher = dispatcher;
    this.enabled = enabled;
  }

  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.PUBLICCHAT || !enabled.getAsBoolean()) {
