import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

final class NpcScopePicker extends JPanel {

  private final NpcVoiceCatalog catalog;
  private final Runnable onChange;
  private final Map<NpcVoiceScope, JRadioButton> buttons = new EnumMap<>(NpcVoiceScope.class);
  private final Map<NpcVoiceScope, List<Integer>> ids = new EnumMap<>(NpcVoiceScope.class);

  NpcScopePicker(NpcVoiceCatalog catalog, Runnable onChange) {
    super(new GridLayout(0, 1, 0, 2));
    this.catalog = catalog;
    this.onChange = onChange;
    setOpaque(false);
    ButtonGroup group = new ButtonGroup();
    for (NpcVoiceScope scope : NpcVoiceScope.values()) {
      JRadioButton button = new JRadioButton();
      button.setOpaque(false);
      button.setFont(FontManager.getRunescapeSmallFont());
      button.setForeground(ColorScheme.TEXT_COLOR);
      button.addActionListener(e -> this.onChange.run());
      group.add(button);
      buttons.put(scope, button);
      add(button);
    }
    buttons.get(NpcVoiceScope.THIS_NPC).setSelected(true);
  }

  void show(int npcId, String npcName, List<Integer> sameNameIds) {
    for (NpcVoiceScope scope : NpcVoiceScope.values()) {
      List<Integer> scoped =
          scope == NpcVoiceScope.SAME_NAME ? sameNameIds : catalog.scopeIds(npcId, scope);
      ids.put(scope, scoped);
      JRadioButton button = buttons.get(scope);
      button.setText(label(scope, npcName, scoped.size()));
      button.setEnabled(scope == NpcVoiceScope.THIS_NPC || scoped.size() > 1);
    }
    NpcVoiceScope selected = selected();
    if (!buttons.get(selected).isEnabled()) {
      buttons.get(NpcVoiceScope.THIS_NPC).setSelected(true);
    }
  }

  static String label(NpcVoiceScope scope, String npcName, int count) {
    switch (scope) {
      case THIS_CHARACTER:
        return "This character and its variants (" + count + ")";
      case SAME_NAME:
        return "Everyone called \"" + npcName + "\" (" + count + ")";
      case THIS_NPC:
      default:
        return "Only this NPC (1)";
    }
  }

  NpcVoiceScope selected() {
    for (Map.Entry<NpcVoiceScope, JRadioButton> entry : buttons.entrySet()) {
      if (entry.getValue().isSelected()) {
        return entry.getKey();
      }
    }
    return NpcVoiceScope.THIS_NPC;
  }

  void select(NpcVoiceScope scope) {
    buttons.get(scope).setSelected(true);
  }

  List<Integer> selectedIds() {
    return ids.getOrDefault(selected(), Collections.emptyList());
  }

  JRadioButton button(NpcVoiceScope scope) {
    return buttons.get(scope);
  }
}

package com.grahambartley.runelite.voiced.dialogue.panel;

import com.google.gson.Gson;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceCatalog;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceOverrideStore;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceTransferCodec;
import com.grahambartley.runelite.voiced.dialogue.profile.RecentNpcSpeakers;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import okhttp3.OkHttpClient;

public final class NpcVoicePanel extends PluginPanel {

  static final String LIST_CARD = "list";
  static final String DETAIL_CARD = "detail";

  private final NpcVoiceCatalog catalog;
  private final RecentNpcSpeakers recentSpeakers;
  private final NpcVoiceOverrideStore store;
  private final NpcListEntries entries;
  private final NpcNameResolver nameResolver;
  private final Consumer<Runnable> uiThread;
  private final BooleanSupplier showing;
  private final CardLayout cards = new CardLayout();
  private final JPanel content = new JPanel(cards);
  private final NpcVoiceTransferBar transferBar;
  private final NpcListView listView;
  private final NpcDetailView detailView;
  private final Set<Integer> requestedNames = new HashSet<>();
  private final AtomicBoolean refreshQueued = new AtomicBoolean();
  private String shownCard = LIST_CARD;
  private boolean formStale;

  public NpcVoicePanel(
      NpcVoiceCatalog catalog,
      RecentNpcSpeakers recentSpeakers,
      NpcVoiceOverrideStore store,
      NpcNameResolver nameResolver,
      OkHttpClient httpClient,
      ExecutorService chatheadExecutor,
      Gson gson) {
    this(
        catalog,
        recentSpeakers,
        store,
        new NpcVoiceTransferCodec(store::sanitize, gson),
        nameResolver,
        new ChatheadImages(
            httpClient,
            ChatheadImages.WIKI_FILE_PATH,
            chatheadExecutor,
            SwingUtilities::invokeLater),
        SwingUtilities::invokeLater,
        null,
        null);
  }

  NpcVoicePanel(
      NpcVoiceCatalog catalog,
      RecentNpcSpeakers recentSpeakers,
      NpcVoiceOverrideStore store,
      NpcVoiceTransferCodec transferCodec,
      NpcNameResolver nameResolver,
      ChatheadImages chatheads,
      Consumer<Runnable> uiThread,
      BooleanSupplier showing,
      NpcVoiceTransfer.Dialogs dialogs) {
    super(false);
    this.catalog = catalog;
    this.recentSpeakers = recentSpeakers;
    this.store = store;
    this.entries = new NpcListEntries(catalog);
    this.nameResolver = nameResolver;
    this.uiThread = uiThread;
    this.showing = showing == null ? this::isShowing : showing;
    setLayout(new BorderLayout(0, 10));
    setBorder(new EmptyBorder(10, 10, 10, 10));
    setBackground(ColorScheme.DARK_GRAY_COLOR);

    transferBar =
        new NpcVoiceTransferBar(
            new NpcVoiceTransfer(
                store,
                transferCodec,
                dialogs == null ? new SwingTransferDialogs(this) : dialogs,
                this::refresh));
    listView =
        new NpcListView(
            entries,
            recentSpeakers::newestFirst,
            store::overriddenIds,
            chatheads,
            this::openDetail,
            this::resolveNames,
            transferBar);
    detailView = new NpcDetailView(catalog, store, chatheads, this::showList, this::refresh);

    add(title(), BorderLayout.NORTH);
    content.setBackground(ColorScheme.DARK_GRAY_COLOR);
    content.add(listView, LIST_CARD);
    content.add(detailView, DETAIL_CARD);
    add(content, BorderLayout.CENTER);
    recentSpeakers.setListener(this::refreshListLater);
  }

  public static BufferedImage navigationIcon() {
    return PanelIcons.navigation();
  }

  @Override
  public void onActivate() {
    if (formStale && DETAIL_CARD.equals(shownCard)) {
      detailView.reload();
    }
    formStale = false;
    refresh();
    if (LIST_CARD.equals(shownCard)) {
      listView.focusSearch();
    }
  }

  public void refreshLater() {
    if (!refreshQueued.compareAndSet(false, true)) {
      return;
    }
    uiThread.accept(
        () -> {
          refreshQueued.set(false);
          if (!showing.getAsBoolean()) {
            formStale = true;
          } else if (LIST_CARD.equals(shownCard)) {
            listView.refresh();
          } else {
            detailView.reload();
          }
        });
  }

  private void refreshListLater() {
    uiThread.accept(
        () -> {
          if (showing.getAsBoolean()) {
            refresh();
          }
        });
  }

  void refresh() {
    if (LIST_CARD.equals(shownCard)) {
      listView.refresh();
    }
  }

  public void showNpc(int npcId, String name) {
    catalog.remember(npcId, name);
    openDetail(entries.forNpc(npcId, name, recentSpeakers.newestFirst(), store.overriddenIds()));
  }

  private void openDetail(NpcListEntry entry) {
    detailView.open(entry);
    show(DETAIL_CARD);
  }

  private void showList() {
    show(LIST_CARD);
    listView.refresh();
  }

  private void show(String card) {
    shownCard = card;
    cards.show(content, card);
  }

  private void resolveNames(Set<Integer> ids) {
    Set<Integer> fresh = new HashSet<>(ids);
    fresh.removeAll(requestedNames);
    if (fresh.isEmpty()) {
      return;
    }
    requestedNames.addAll(fresh);
    nameResolver.resolve(fresh, names -> uiThread.accept(() -> remember(names)));
  }

  private void remember(Map<Integer, String> names) {
    names.forEach(catalog::remember);
    refresh();
  }

  private static JPanel title() {
    JPanel title = new JPanel(new GridLayout(2, 1));
    title.setOpaque(false);
    JLabel heading = new JLabel("NPC Voices");
    heading.setFont(FontManager.getRunescapeBoldFont());
    heading.setForeground(ColorScheme.BRAND_ORANGE);
    JLabel blurb = new JLabel("Choose how any NPC sounds to you.");
    blurb.setFont(FontManager.getRunescapeSmallFont());
    blurb.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    title.add(heading);
    title.add(blurb);
    return title;
  }

  String shownCard() {
    return shownCard;
  }

  NpcListView listView() {
    return listView;
  }

  NpcVoiceTransferBar transferBar() {
    return transferBar;
  }

  NpcDetailView detailView() {
    return detailView;
  }
}

package com.grahambartley.runelite.voiced.dialogue.panel;

import static com.grahambartley.runelite.voiced.dialogue.panel.NpcDetailView.npcCount;

import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceImport;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceImportPlan;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceOverride;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceOverrideStore;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceTransferCodec;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import java.util.Map;

final class NpcVoiceTransfer {

  static final long MAX_IMPORT_BYTES = 1_000_000;
  static final String EXTENSION = ".json";
  static final String REVOICE_NOTE =
      "Imported NPCs are re-voiced, and re-billed, the next time you hear them.";

  interface Dialogs {
    void copyToClipboard(String text);

    Path chooseExportFile();

    String pasteImport();

    Path chooseImportFile();

    NpcVoiceImportPlan.Mode confirmImport(String summary);

    void info(String message);

    void error(String message);
  }

  private final NpcVoiceOverrideStore store;
  private final NpcVoiceTransferCodec codec;
  private final Dialogs dialogs;
  private final Runnable onImported;

  NpcVoiceTransfer(
      NpcVoiceOverrideStore store,
      NpcVoiceTransferCodec codec,
      Dialogs dialogs,
      Runnable onImported) {
    this.store = store;
    this.codec = codec;
    this.dialogs = dialogs;
    this.onImported = onImported;
  }

  void exportToClipboard() {
    Map<Integer, NpcVoiceOverride> overrides = store.all();
    dialogs.copyToClipboard(codec.encode(overrides));
    dialogs.info("Copied edits for " + npcCount(overrides.size()) + " to the clipboard.");
  }

  void exportToFile() {
    Path chosen = dialogs.chooseExportFile();
    if (chosen == null) {
      return;
    }
    Path target = withJsonExtension(chosen);
    Map<Integer, NpcVoiceOverride> overrides = store.all();
    try {
      Files.write(target, codec.encode(overrides).getBytes(StandardCharsets.UTF_8));
    } catch (IOException | RuntimeException e) {
      dialogs.error("Could not save " + target.getFileName() + ": " + e.getMessage());
      return;
    }
    dialogs.info(
        "Saved edits for " + npcCount(overrides.size()) + " to " + target.getFileName() + ".");
  }

  void importFromText() {
    String text = dialogs.pasteImport();
    if (text != null) {
      importDocument(text);
    }
  }

  void importFromFile() {
    Path chosen = dialogs.chooseImportFile();
    if (chosen == null) {
      return;
    }
    String text;
    try {
      if (Files.size(chosen) > MAX_IMPORT_BYTES) {
        dialogs.error(chosen.getFileName() + " is too large to be an NPC voices file.");
        return;
      }
      text = new String(Files.readAllBytes(chosen), StandardCharsets.UTF_8);
    } catch (IOException | RuntimeException e) {
      dialogs.error("Could not read " + chosen.getFileName() + ": " + e.getMessage());
      return;
    }
    importDocument(text);
  }

  private void importDocument(String text) {
    NpcVoiceImport imported;
    try {
      imported = codec.decode(text);
    } catch (NpcVoiceTransferCodec.InvalidDocumentException e) {
      dialogs.error(e.getMessage() + " Nothing was imported.");
      return;
    }
    NpcVoiceImportPlan plan = new NpcVoiceImportPlan(imported, store.overriddenIds());
    if (plan.sets() == 0) {
      dialogs.error("There are no NPC voices to import." + skippedNote(plan.skipped()));
      return;
    }
    NpcVoiceImportPlan.Mode mode = dialogs.confirmImport(summary(plan));
    if (mode == null) {
      return;
    }
    plan.apply(store, mode);
    onImported.run();
    dialogs.info("Imported voices for " + npcCount(plan.sets()) + ". " + REVOICE_NOTE);
  }

  static String summary(NpcVoiceImportPlan plan) {
    StringBuilder summary =
        new StringBuilder("This sets voices for ").append(npcCount(plan.sets())).append('.');
    if (plan.replaces() > 0) {
      summary
          .append(' ')
          .append(
              plan.replaces() == 1
                  ? "1 of them already has"
                  : plan.replaces() + " of them already have")
          .append(" an edit it will replace.");
    }
    summary.append(skippedNote(plan.skipped()));
    summary.append("\n\nMerge keeps your other edits.");
    summary.append(
        plan.clearedByReplaceAll() == 0
            ? " Replace all has no other edits to clear."
            : " Replace all also clears your "
                + plan.clearedByReplaceAll()
                + (plan.clearedByReplaceAll() == 1 ? " other edit." : " other edits."));
    return summary.toString();
  }

  static Path withJsonExtension(Path chosen) {
    String name = chosen.getFileName().toString();
    return name.toLowerCase(Locale.ROOT).endsWith(EXTENSION)
        ? chosen
        : chosen.resolveSibling(name + EXTENSION);
  }

  private static String skippedNote(int skipped) {
    if (skipped == 0) {
      return "";
    }
    return skipped == 1
        ? " 1 entry was skipped as invalid."
        : " " + skipped + " entries were skipped as invalid.";
  }
}

