package com.grahambartley.runelite.voiced.dialogue.panel;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

final class PanelIcons {

  static final int NAVIGATION_SIZE = 16;

  static final String NAVIGATION_RESOURCE = "navigation_icon.png";

  private PanelIcons() {}

  static BufferedImage navigation() {
    return ImageUtil.loadImageResource(PanelIcons.class, NAVIGATION_RESOURCE);
  }

  static BufferedImage chatheadPlaceholder(int size) {
    BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = smooth(image);
    try {
      g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
      double head = size * 0.42;
      g.fill(new Ellipse2D.Double((size - head) / 2, size * 0.14, head, head));
      double body = size * 0.72;
      g.fill(new Ellipse2D.Double((size - body) / 2, size * 0.58, body, size * 0.6));
    } finally {
      g.dispose();
    }
    return image;
  }

  private static Graphics2D smooth(BufferedImage image) {
    Graphics2D g = image.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    return g;
  }
}

package com.grahambartley.runelite.voiced.dialogue.panel;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import javax.swing.JTextArea;

final class PlaceholderTextArea extends JTextArea {

  private final String placeholder;

  PlaceholderTextArea(String placeholder, int rows) {
    super(rows, 0);
    this.placeholder = placeholder;
    setLineWrap(true);
    setWrapStyleWord(true);
  }

  @Override
  public Dimension getPreferredSize() {
    return new Dimension(1, super.getPreferredSize().height);
  }

  @Override
  public Dimension getMinimumSize() {
    return getPreferredSize();
  }

  String placeholder() {
    return placeholder;
  }

  @Override
  protected void paintComponent(Graphics g) {
    super.paintComponent(g);
    if (!getText().isEmpty()) {
      return;
    }
    Graphics2D g2 = (Graphics2D) g.create();
    try {
      g2.setRenderingHint(
          RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
      g2.setColor(getDisabledTextColor());
      g2.setFont(getFont());
      Insets insets = getInsets();
      g2.drawString(placeholder, insets.left, insets.top + g2.getFontMetrics().getAscent());
    } finally {
      g2.dispose();
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.panel;

import com.grahambartley.runelite.voiced.dialogue.profile.NpcVoiceImportPlan;
import java.awt.Component;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.File;
import java.nio.file.Path;
import javax.swing.JFileChooser;
import javax.swing.JOptionPane;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.filechooser.FileNameExtensionFilter;

final class SwingTransferDialogs implements NpcVoiceTransfer.Dialogs {

  static final String TITLE = "NPC Voices";
  static final String DEFAULT_FILE_NAME = "npc-voices.json";

  private final Component parent;

  SwingTransferDialogs(Component parent) {
    this.parent = parent;
  }

  @Override
  public void copyToClipboard(String text) {
    Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
  }

  @Override
  public Path chooseExportFile() {
    JFileChooser chooser = chooser();
    chooser.setDialogTitle("Export NPC voices");
    chooser.setSelectedFile(new File(DEFAULT_FILE_NAME));
    while (chooser.showSaveDialog(parent) == JFileChooser.APPROVE_OPTION) {
      Path target = NpcVoiceTransfer.withJsonExtension(chooser.getSelectedFile().toPath());
      if (!target.toFile().exists() || confirmOverwrite(target)) {
        return target;
      }
    }
    return null;
  }

  @Override
  public String pasteImport() {
    JTextArea text = new JTextArea(12, 28);
    text.setLineWrap(true);
    JScrollPane scroll = new JScrollPane(text);
    int choice =
        JOptionPane.showConfirmDialog(
            parent,
            new Object[] {"Paste an exported NPC voices file:", scroll},
            "Import NPC voices",
            JOptionPane.OK_CANCEL_OPTION,
            JOptionPane.PLAIN_MESSAGE);
    return choice == JOptionPane.OK_OPTION ? text.getText() : null;
  }

  @Override
  public Path chooseImportFile() {
    JFileChooser chooser = chooser();
    chooser.setDialogTitle("Import NPC voices");
    return chooser.showOpenDialog(parent) == JFileChooser.APPROVE_OPTION
        ? chooser.getSelectedFile().toPath()
        : null;
  }

  @Override
  public NpcVoiceImportPlan.Mode confirmImport(String summary) {
    String[] options = {"Merge", "Replace all", "Cancel"};
    int choice =
        JOptionPane.showOptionDialog(
            parent,
            summary,
            "Import NPC voices",
            JOptionPane.DEFAULT_OPTION,
            JOptionPane.QUESTION_MESSAGE,
            null,
            options,
            options[0]);
