  static NpcVoiceImportPlan.Mode importMode(int choice) {
    if (choice == 0) {
      return NpcVoiceImportPlan.Mode.MERGE;
    }
    return choice == 1 ? NpcVoiceImportPlan.Mode.REPLACE_ALL : null;
