package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.CategoryRule;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.Layer;
import com.grahambartley.runelite.voiced.dialogue.speaker.LifeStage;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class NpcProfileParser {

  static final String AGE_KEY = "age";

  static final int MIN_AGE = 1;

  static final int MAX_AGE = 120;

  private NpcProfileParser() {}

  static NpcProfileLayers loadResource(String resource) {
    try (InputStream stream = NpcProfileParser.class.getResourceAsStream(resource)) {
      if (stream == null) {
        log.warn(
            "NPC profile table {} not found - using the built-in British default for every line",
            resource);
        return null;
      }
      JsonObject root =
          new JsonParser()
              .parse(new InputStreamReader(stream, StandardCharsets.UTF_8))
              .getAsJsonObject();
      if (!root.has("profiles") || !root.get("profiles").isJsonObject()) {
        log.warn(
            "NPC profile table {} has no 'profiles' object - using the built-in British default",
            resource);
        return null;
      }
      return parse(root.getAsJsonObject("profiles"), optObject(root, "symbols"));
    } catch (Exception e) {
      log.error("Failed to load NPC profile table {}: {}", resource, e.getMessage());
      return null;
    }
  }

  static NpcProfileLayers parse(JsonObject profiles) {
    return parse(profiles, null);
  }

  static NpcProfileLayers parse(JsonObject profiles, JsonObject symbols) {
    CharacterProfile parsedDefault = parseComplete(optObject(profiles, "default"));
    if (parsedDefault == null) {
      log.warn("profiles.default is missing or incomplete - using the built-in British default");
      parsedDefault = NpcProfileLayers.BUILTIN_DEFAULT;
    }
    return new NpcProfileLayers(
        parsedDefault,
        parseLayer(optObject(profiles, "player")),
        parseLayer(optObject(profiles, "narrator")),
        parseLayerMap(optObject(profiles, "byRace")),
        parseLayerMap(optObject(profiles, "byEthnicity")),
        parseCategories(profiles),
        parseByIdLayers(profiles),
        parseSymbols(symbols));
  }

  private static Map<Integer, String> parseSymbols(JsonObject symbols) {
    if (symbols == null) {
      return Collections.emptyMap();
    }
    Map<Integer, String> parsed = new HashMap<>();
    for (String key : symbols.keySet()) {
      JsonElement value = symbols.get(key);
      if (isComment(key)
          || !value.isJsonPrimitive()
          || !value.getAsJsonPrimitive().isString()
          || value.getAsString().isEmpty()) {
        continue;
      }
      try {
        parsed.put(Integer.parseInt(key), value.getAsString());
      } catch (NumberFormatException e) {
        log.warn("Skipping non-numeric symbols key '{}'", key);
      }
    }
    return Collections.unmodifiableMap(parsed);
  }

  private static List<CategoryRule> parseCategories(JsonObject profiles) {
    List<CategoryRule> categories = new ArrayList<>();
    if (profiles.has("byCategory") && profiles.get("byCategory").isJsonArray()) {
      JsonArray arr = profiles.getAsJsonArray("byCategory");
      for (JsonElement el : arr) {
        if (!el.isJsonObject()) {
          continue;
        }
        JsonObject entry = el.getAsJsonObject();
        if (!entry.has("keywords") || !entry.get("keywords").isJsonArray()) {
          continue;
        }
        List<String> keywords = new ArrayList<>();
        for (JsonElement kw : entry.getAsJsonArray("keywords")) {
          keywords.add(kw.getAsString().toLowerCase(Locale.ROOT));
        }
        String id = entry.has("id") ? entry.get("id").getAsString() : "category";
        boolean child = LifeStage.CHILD.equalsIgnoreCase(optString(entry, "lifeStage"));
        categories.add(new CategoryRule(id, keywords, parseLayer(entry), child));
      }
    }
    return Collections.unmodifiableList(categories);
  }

  private static Map<Integer, Layer> parseByIdLayers(JsonObject profiles) {
    Map<Integer, Layer> ids = new HashMap<>();
    JsonObject idObj = optObject(profiles, "byId");
    if (idObj != null) {
      for (String key : idObj.keySet()) {
        if (isComment(key) || !idObj.get(key).isJsonObject()) {
          continue;
        }
        try {
          ids.put(Integer.parseInt(key), parseLayer(idObj.getAsJsonObject(key)));
        } catch (NumberFormatException e) {
          log.warn("Skipping non-numeric byId profile key '{}'", key);
        }
      }
    }
    return Collections.unmodifiableMap(ids);
  }

  private static Map<String, Layer> parseLayerMap(JsonObject obj) {
    if (obj == null) {
      return Collections.emptyMap();
    }
    Map<String, Layer> map = new HashMap<>();
    for (String key : obj.keySet()) {
      if (isComment(key) || !obj.get(key).isJsonObject()) {
        continue;
      }
      map.put(key.toLowerCase(Locale.ROOT), parseLayer(obj.getAsJsonObject(key)));
    }
    return Collections.unmodifiableMap(map);
  }

  private static Layer parseLayer(JsonObject obj) {
    if (obj == null) {
      return null;
    }
    return new Layer(
        optString(obj, "name"),
        optString(obj, "accent"),
        optString(obj, "accentDetail"),
        optString(obj, "style"),
        obj.has("replaceStyle") && obj.get("replaceStyle").getAsBoolean(),
        optString(obj, "pace"),
        optString(obj, "pitch"),
        optString(obj, "voiceRegion"),
        optAge(obj));
  }

  private static CharacterProfile parseComplete(JsonObject obj) {
    Layer layer = parseLayer(obj);
    if (layer == null
        || layer.name() == null
        || layer.accent() == null
        || layer.style() == null
        || layer.pace() == null) {
      return null;
    }
    return new CharacterProfile(
        layer.name(),
        layer.accent(),
        layer.accentDetail(),
        layer.style(),
        layer.pace(),
        layer.pitch(),
        layer.voiceRegion());
  }

  private static JsonObject optObject(JsonObject parent, String key) {
    return parent.has(key) && parent.get(key).isJsonObject() ? parent.getAsJsonObject(key) : null;
  }

  private static String optString(JsonObject obj, String key) {
    if (!obj.has(key) || obj.get(key).isJsonNull()) {
      return null;
    }
    String value = obj.get(key).getAsString();
    return value.isEmpty() ? null : value;
  }

  private static Integer optAge(JsonObject obj) {
    if (!obj.has(AGE_KEY) || !obj.get(AGE_KEY).isJsonPrimitive()) {
      return null;
    }
    JsonPrimitive value = obj.getAsJsonPrimitive(AGE_KEY);
    if (!value.isNumber()) {
      return null;
    }
    int age = value.getAsInt();
    return age >= MIN_AGE && age <= MAX_AGE ? age : null;
  }

  private static boolean isComment(String key) {
    return key.startsWith("_");
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.CategoryRule;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.Layer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import lombok.Value;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class NpcProfileTable {

  private static final String TABLE_RESOURCE = "/npc-voices.json";

  private static final Pattern ENDS_SENTENCE = Pattern.compile("[.!?]$");

  @Value
  @Accessors(fluent = true)
  public static class Resolution {
    CharacterProfile profile;
    String source;
  }

  public static final class NameMatch {

    static final NameMatch NONE = new NameMatch(Collections.emptyList());

    private final List<CategoryRule> rules;

    NameMatch(List<CategoryRule> rules) {
      this.rules = rules;
    }

    public boolean child() {
      for (CategoryRule rule : rules) {
        if (rule.child()) {
          return true;
        }
      }
      return false;
    }
  }

  private static final class MatchedLayer {
    private final Layer layer;
    private final String source;

    MatchedLayer(Layer layer, String source) {
      this.layer = layer;
      this.source = source;
    }
  }

  private final DirectionSanitizer directionSanitizer;

  private NpcProfileLayers layers = NpcProfileLayers.EMPTY;
  private boolean loaded = false;

  public NpcProfileTable() {
    this(new DirectionSanitizer(new ProfanityFilter()));
  }

  public NpcProfileTable(DirectionSanitizer directionSanitizer) {
    this.directionSanitizer = directionSanitizer;
  }

  public void initialize() {
    NpcProfileLayers parsed = NpcProfileParser.loadResource(TABLE_RESOURCE);
    if (parsed == null) {
      return;
    }
    this.layers = parsed;
    this.loaded = true;
    log.info(
        "NPC profiles loaded: {} race, {} ethnicity, {} keyword categories, {} bespoke NPC"
            + " overrides, {} cache symbols",
        layers.byRace().size(),
        layers.byEthnicity().size(),
        layers.byCategory().size(),
        layers.byId().size(),
        layers.symbols().size());
  }

  static NpcProfileTable fromProfilesJson(JsonObject profiles) {
    NpcProfileTable table = new NpcProfileTable();
    table.layers = NpcProfileParser.parse(profiles);
    table.loaded = true;
    return table;
  }

  public boolean hasBespokeProfile(int npcId) {
    return layers.byId().containsKey(npcId);
  }

  public NameMatch matchName(String npcName) {
    if (npcName == null || npcName.isEmpty()) {
      return NameMatch.NONE;
    }
    String lower = npcName.toLowerCase(Locale.ROOT);
    List<CategoryRule> matches = new ArrayList<>();
    for (CategoryRule rule : layers.byCategory()) {
      for (String keyword : rule.keywords()) {
        if (wordContains(lower, keyword)) {
          matches.add(rule);
          break;
        }
      }
    }
    return new NameMatch(matches);
  }

  public Resolution resolveNpc(
      Integer npcId,
      NameMatch nameMatch,
      String race,
      String ethnicity,
      boolean child,
      NpcVoiceOverride override) {
    return mergeLayers(collectLayers(npcId, nameMatch, race, ethnicity, child), override);
  }

  private List<MatchedLayer> collectLayers(
      Integer npcId, NameMatch nameMatch, String race, String ethnicity, boolean child) {
    List<MatchedLayer> matched = new ArrayList<>();

    Layer raceLayer = race == null ? null : layers.byRace().get(race.toLowerCase(Locale.ROOT));
    if (raceLayer != null) {
      matched.add(new MatchedLayer(raceLayer, "race:" + race));
    }
    boolean plainRace =
        race == null || race.equalsIgnoreCase("Human") || race.equalsIgnoreCase("Unknown");
    Layer ethnicityLayer =
        (ethnicity == null || !plainRace)
            ? null
            : layers.byEthnicity().get(ethnicity.toLowerCase(Locale.ROOT));
    if (ethnicityLayer != null) {
      matched.add(new MatchedLayer(ethnicityLayer, "ethnicity:" + ethnicity));
    }
    for (CategoryRule rule : nameMatch.rules) {
      matched.add(new MatchedLayer(rule.layer(), "keyword:" + rule.id()));
    }
    if (child && !nameMatch.child()) {
      for (CategoryRule rule : layers.byCategory()) {
        if (rule.child()) {
          matched.add(new MatchedLayer(rule.layer(), "lifeStage:" + rule.id()));
        }
      }
    }
    Layer idLayer = npcId == null ? null : layers.byId().get(npcId);
    if (idLayer != null) {
      matched.add(new MatchedLayer(idLayer, "id:" + npcId));
    }
    return matched;
  }

  private Resolution mergeLayers(List<MatchedLayer> matched, NpcVoiceOverride override) {
    CharacterProfile defaultProfile = layers.defaultProfile();
    String name = defaultProfile.name();
    String accent = defaultProfile.accent();
    String accentDetail = defaultProfile.accentDetail();
    String voiceRegion = defaultProfile.voiceRegion();
    String pace = defaultProfile.pace();
    String pitch = defaultProfile.pitch();
    Integer age = defaultProfile.age();
    List<String> styleParts = new ArrayList<>();
    boolean accentOverridden = false;
    List<String> sources = new ArrayList<>();
    for (MatchedLayer entry : matched) {
      Layer layer = entry.layer;
      if (layer.name() != null) {
        name = layer.name();
      }
      if (layer.accent() != null) {
        accent = layer.accent();
        accentDetail = layer.accentDetail();
        voiceRegion = layer.voiceRegion();
      }
      if (layer.pace() != null) {
        pace = layer.pace();
      }
      if (layer.pitch() != null) {
        pitch = layer.pitch();
      }
      if (layer.age() != null) {
        age = layer.age();
      }
      if (layer.style() != null) {
        if (layer.replaceStyle()) {
          styleParts.clear();
        }
        styleParts.add(asSentence(layer.style()));
      }
      sources.add(entry.source);
    }
    if (override != null && override.hasProfileFields()) {
      if (override.name() != null) {
        name = override.name();
      }
      if (override.accent() != null) {
        accent = override.accent();
        accentDetail = null;
        accentOverridden = true;
      }
      if (override.style() != null) {
        styleParts.clear();
        styleParts.add(asSentence(override.style()));
      }
      if (override.pace() != null) {
        pace = override.pace();
      }
      sources.add("override");
    }
    String style = styleParts.isEmpty() ? defaultProfile.style() : String.join(" ", styleParts);
    String source = sources.isEmpty() ? "default" : String.join("+", sources);

    return new Resolution(
        new CharacterProfile(
            name, accent, accentDetail, style, pace, pitch, voiceRegion, accentOverridden, age),
        source);
  }

  private static String asSentence(String style) {
    String trimmed = style.trim();
    return ENDS_SENTENCE.matcher(trimmed).find() ? trimmed : trimmed + ".";
  }

  public CharacterProfile resolvePlayer(String accent, String style, String pace) {
    CharacterProfile base = apply(layers.defaultProfile(), layers.playerLayer());
    return new CharacterProfile(
        base.name(),
        sanitizedOr(accent, base.accent()),
        sanitizedOr(style, base.style()),
        sanitizedOr(pace, base.pace()));
  }

  public CharacterProfile resolveNarrator() {
    return apply(layers.defaultProfile(), layers.narratorLayer());
  }

  private String sanitizedOr(String configured, String fallback) {
    if (isBlank(configured)) {
      return fallback;
    }
    String sanitized = directionSanitizer.sanitize(configured);
    return isBlank(sanitized) ? fallback : sanitized;
  }

  public NpcVoiceCatalog buildCatalog() {
    return NpcVoiceCatalog.from(layers);
  }

  public boolean isLoaded() {
    return loaded;
  }

  static boolean wordContains(String haystack, String needle) {
    if (needle.isEmpty()) {
      return false;
    }
    int idx = haystack.indexOf(needle);
    while (idx >= 0) {
      boolean leftOk = idx == 0 || !Character.isLetter(haystack.charAt(idx - 1));
      int end = idx + needle.length();
      boolean rightOk = end == haystack.length() || !Character.isLetter(haystack.charAt(end));
      if (leftOk && rightOk) {
        return true;
      }
      idx = haystack.indexOf(needle, idx + 1);
    }
    return false;
  }

  private static CharacterProfile apply(CharacterProfile base, Layer layer) {
    if (layer == null) {
      return base;
    }
    boolean ownAccent = layer.accent() != null;
    return new CharacterProfile(
        layer.name() != null ? layer.name() : base.name(),
        ownAccent ? layer.accent() : base.accent(),
        ownAccent ? layer.accentDetail() : base.accentDetail(),
        layer.style() != null ? layer.style() : base.style(),
        layer.pace() != null ? layer.pace() : base.pace(),
        null,
        null);
  }

  private static boolean isBlank(String value) {
    return value == null || value.trim().isEmpty();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.Layer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeSet;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;

public final class NpcVoiceCatalog {

  private static final Pattern VARIANT_SUFFIX = Pattern.compile("_VARIANT\\d+");
  private static final Pattern SEX_SUFFIX = Pattern.compile("_[FM](?=_|$)");
  private static final Pattern DIGIT_RUN = Pattern.compile("\\d+");

  private final Map<Integer, String> bundledNames;
  private final Map<Integer, String> symbols;
  private final Map<String, TreeSet<Integer>> bundledIdsByName = new HashMap<>();
  private final Map<String, String> bundledDisplayNames = new HashMap<>();
  private final Map<String, TreeSet<Integer>> idsByCharacter = new HashMap<>();
  private final Map<Integer, String> sessionNames = new ConcurrentHashMap<>();

  public NpcVoiceCatalog(Map<Integer, String> bundledNames, Map<Integer, String> symbols) {
    this.bundledNames = Collections.unmodifiableMap(new HashMap<>(bundledNames));
    this.symbols = Collections.unmodifiableMap(new HashMap<>(symbols));
    for (Map.Entry<Integer, String> entry : this.bundledNames.entrySet()) {
      String key = key(entry.getValue());
      bundledIdsByName.computeIfAbsent(key, k -> new TreeSet<>()).add(entry.getKey());
      bundledDisplayNames.merge(key, entry.getValue(), NpcVoiceCatalog::firstAlphabetically);
    }
    for (Map.Entry<Integer, String> entry : this.symbols.entrySet()) {
      idsByCharacter
          .computeIfAbsent(characterKey(entry.getValue()), k -> new TreeSet<>())
          .add(entry.getKey());
    }
  }

  static NpcVoiceCatalog from(NpcProfileLayers layers) {
    Map<Integer, String> names = new HashMap<>();
    for (Map.Entry<Integer, Layer> entry : layers.byId().entrySet()) {
      String name = entry.getValue().name();
      if (name != null && !name.trim().isEmpty()) {
        names.put(entry.getKey(), name.trim());
      }
    }
    return new NpcVoiceCatalog(names, layers.symbols());
  }

  public void remember(int npcId, String name) {
    if (name != null && !name.trim().isEmpty() && !bundledNames.containsKey(npcId)) {
      sessionNames.put(npcId, name.trim());
    }
  }

  public String nameOf(int npcId) {
    String bundled = bundledNames.get(npcId);
    return bundled != null ? bundled : sessionNames.get(npcId);
  }

  public String displayName(String name) {
    String bundled = bundledDisplayNames.get(key(name));
    return bundled != null ? bundled : name.trim();
  }

  public List<Integer> idsNamed(String name) {
    String key = key(name);
    TreeSet<Integer> ids = new TreeSet<>(bundledIdsByName.getOrDefault(key, new TreeSet<>()));
    for (Map.Entry<Integer, String> entry : sessionNames.entrySet()) {
      if (key(entry.getValue()).equals(key)) {
        ids.add(entry.getKey());
      }
    }
    return new ArrayList<>(ids);
  }

  public List<String> namesMatching(String query) {
    String needle = key(query);
    TreeSet<String> keys = new TreeSet<>();
    for (String key : bundledIdsByName.keySet()) {
      if (key.contains(needle)) {
        keys.add(key);
      }
    }
    for (String name : sessionNames.values()) {
      if (key(name).contains(needle)) {
        keys.add(key(name));
      }
    }
    List<String> names = new ArrayList<>();
    for (String key : keys) {
      names.add(displayNameForKey(key));
    }
    return names;
  }

  public List<Integer> scopeIds(int npcId, NpcVoiceScope scope) {
    switch (scope) {
      case THIS_CHARACTER:
        String symbol = symbols.get(npcId);
        return symbol == null
            ? Collections.singletonList(npcId)
            : new ArrayList<>(idsByCharacter.get(characterKey(symbol)));
      case SAME_NAME:
        String name = nameOf(npcId);
        if (name == null) {
          return Collections.singletonList(npcId);
        }
        TreeSet<Integer> named = new TreeSet<>(idsNamed(name));
        named.add(npcId);
        return new ArrayList<>(named);
      case THIS_NPC:
      default:
        return Collections.singletonList(npcId);
    }
  }

  static String characterKey(String symbol) {
    String stripped = VARIANT_SUFFIX.matcher(symbol).replaceAll("");
    stripped = SEX_SUFFIX.matcher(stripped).replaceAll("");
    return DIGIT_RUN.matcher(stripped).replaceAll("");
  }

  private String displayNameForKey(String key) {
    String bundled = bundledDisplayNames.get(key);
    if (bundled != null) {
      return bundled;
    }
    for (String name : sessionNames.values()) {
      if (key(name).equals(key)) {
        return name;
      }
    }
    return key;
  }

  private static String firstAlphabetically(String a, String b) {
    return a.compareTo(b) <= 0 ? a : b;
  }

  private static String key(String name) {
    return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
  }
}

