package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

final class NpcVoiceOverrideJson {

  private NpcVoiceOverrideJson() {}

  static NpcVoiceOverride parse(JsonElement element) {
    JsonObject json = element.getAsJsonObject();
    return new NpcVoiceOverride(
        optString(json, "name"),
        optString(json, "accent"),
        optString(json, "style"),
        optString(json, "pace"),
        parseVoiceType(optString(json, "voiceType")));
  }

  static JsonObject toJson(NpcVoiceOverride override) {
    JsonObject json = new JsonObject();
    addIfSet(json, "name", override.name());
    addIfSet(json, "accent", override.accent());
    addIfSet(json, "style", override.style());
    addIfSet(json, "pace", override.pace());
    if (override.voiceType() != null) {
      json.addProperty("voiceType", override.voiceType().name());
    }
    return json;
  }

  private static VoiceType parseVoiceType(String voiceType) {
    return voiceType == null ? null : VoiceType.valueOf(voiceType);
  }

  private static String optString(JsonObject json, String field) {
    JsonElement value = json.get(field);
    return value == null || value.isJsonNull() ? null : value.getAsString();
  }

  private static void addIfSet(JsonObject json, String field, String value) {
    if (value != null) {
      json.addProperty(field, value);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
public final class NpcVoiceOverrideStore {

  static final String KEY_PREFIX = "npcVoice_";

  private static final String WHOLE_KEY_PREFIX =
      ConfigManager.getWholeKey(VoicedDialogueConfig.GROUP, null, KEY_PREFIX);

  private final ConfigManager configManager;
  private final DirectionSanitizer directionSanitizer;
  private volatile Map<Integer, NpcVoiceOverride> overrides = new ConcurrentHashMap<>();

  public NpcVoiceOverrideStore(ConfigManager configManager) {
    this(configManager, new DirectionSanitizer(new ProfanityFilter()));
  }

  NpcVoiceOverrideStore(ConfigManager configManager, DirectionSanitizer directionSanitizer) {
    this.configManager = configManager;
    this.directionSanitizer = directionSanitizer;
  }

  public synchronized void load() {
    Map<Integer, NpcVoiceOverride> loaded = new ConcurrentHashMap<>();
    for (String wholeKey : configManager.getConfigurationKeys(WHOLE_KEY_PREFIX)) {
      readInto(loaded, KEY_PREFIX + wholeKey.substring(WHOLE_KEY_PREFIX.length()));
    }
    overrides = loaded;
    log.info("Loaded {} NPC voice overrides", loaded.size());
  }

  public static boolean isOverrideKey(String key) {
    return key != null && key.startsWith(KEY_PREFIX);
  }

  public synchronized void refresh(String key) {
    if (isOverrideKey(key)) {
      readInto(overrides, key);
    }
  }

  private void readInto(Map<Integer, NpcVoiceOverride> target, String key) {
    int npcId;
    try {
      npcId = Integer.parseInt(key.substring(KEY_PREFIX.length()));
    } catch (NumberFormatException e) {
      log.warn("Skipping NPC voice override with a non-numeric id: {}", key);
      return;
    }
    NpcVoiceOverride override = read(key);
    if (override == null || override.isEmpty()) {
      target.remove(npcId);
    } else {
      target.put(npcId, override);
    }
  }

  private NpcVoiceOverride read(String key) {
    String value = configManager.getConfiguration(VoicedDialogueConfig.GROUP, key);
    if (value == null) {
      return null;
    }
    try {
      return sanitize(NpcVoiceOverrideJson.parse(new JsonParser().parse(value)));
    } catch (RuntimeException e) {
      log.warn("Skipping malformed NPC voice override {}: {}", key, e.getMessage());
      return null;
    }
  }

  public NpcVoiceOverride get(Integer npcId) {
    return npcId == null ? null : overrides.get(npcId);
  }

  public Set<Integer> overriddenIds() {
    return new HashSet<>(overrides.keySet());
  }

  public Map<Integer, NpcVoiceOverride> all() {
    return new TreeMap<>(overrides);
  }

  public synchronized void set(int npcId, NpcVoiceOverride override) {
    NpcVoiceOverride sanitized = override == null ? null : sanitize(override);
    if (sanitized == null || sanitized.isEmpty()) {
      clear(npcId);
      return;
    }
    overrides.put(npcId, sanitized);
    configManager.setConfiguration(
        VoicedDialogueConfig.GROUP,
        KEY_PREFIX + npcId,
        NpcVoiceOverrideJson.toJson(sanitized).toString());
  }

  public synchronized void clear(int npcId) {
    overrides.remove(npcId);
    configManager.unsetConfiguration(VoicedDialogueConfig.GROUP, KEY_PREFIX + npcId);
  }

  public NpcVoiceOverride sanitize(NpcVoiceOverride override) {
    return new NpcVoiceOverride(
        sanitize(override.name()),
        sanitize(override.accent()),
        sanitize(override.style()),
        sanitize(override.pace()),
        override.voiceType());
  }

  private String sanitize(String field) {
    String sanitized = directionSanitizer.sanitize(field);
    return sanitized == null || sanitized.isEmpty() ? null : sanitized;
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NameNormalizer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcDemographicParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speaker.wiki.NpcLearningService;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class NpcVoiceResolver {

  private final VoicedDialogueConfig config;

  private NpcLearningService learningService;

  NpcVoiceResolver(VoicedDialogueConfig config) {
    this.config = config;
  }

  void setLearningService(NpcLearningService learningService) {
    this.learningService = learningService;
  }

  VoiceSpec resolve(String npcName, NpcIdentity identity, VoiceType voiceType) {
    if (npcName == null || npcName.isEmpty()) {
      return defaultVoice(npcName, null, identity, voiceType, "blank-name");
    }
    if (identity.worldId() == null) {
      return defaultVoice(npcName, null, identity, voiceType, "not-in-world");
    }
    NpcAttributes attributes = identity.attributes();
    if (attributes == null) {
      return defaultVoice(npcName, identity.baseId(), identity, voiceType, "analysis-failed");
    }

    NpcRace race = NpcDemographicParser.toRace(attributes.getRace());
    NpcGender gender = NpcDemographicParser.toGender(attributes.getGender());
    String source =
        AttributeSource.STATIC_TABLE.equals(attributes.getSource()) ? "table-hit" : "table-miss";

    if (learningService != null) {
      learningService.considerLearning(attributes.getNpcId(), npcName);
    }

    NpcRace voiceRace = race == NpcRace.UNKNOWN ? NpcRace.HUMAN : race;
    NpcGender voiceGender = NpcDemographicParser.toVoiceGender(gender);
    if (voiceType != null) {
      voiceGender = voiceType.getGender();
      gender = voiceGender;
      source += "+voice-type-override";
    }
    boolean child = identity.child();
    int seed = voiceSeed(identity.baseId(), npcName);
    if (config.debugMode()) {
      log.info(
          VoiceTraceFormatter.buildNpcTrace(
              npcName, identity.worldId(), race, gender, child, source, seed));
    }
    return VoiceSpec.npc(voiceRace, voiceGender, seed, child);
  }

  private VoiceSpec defaultVoice(
      String npcName, Integer npcId, NpcIdentity identity, VoiceType voiceType, String source) {
    boolean child = identity.child();
    int seed = voiceSeed(npcId, npcName);
    NpcGender voiceTypeGender = voiceType == null ? null : voiceType.getGender();
    if (voiceTypeGender != null) {
      source += "+voice-type-override";
    }
    if (config.debugMode()) {
      log.info(
          VoiceTraceFormatter.buildNpcTrace(
              npcName,
              npcId,
              NpcRace.UNKNOWN,
              voiceTypeGender == null ? NpcGender.UNKNOWN : voiceTypeGender,
              child,
              source,
              seed));
    }
    return VoiceSpec.npc(
        NpcRace.HUMAN, voiceTypeGender == null ? NpcGender.MALE : voiceTypeGender, seed, child);
  }

  private static int voiceSeed(Integer npcId, String npcName) {
    int hash =
        npcId != null ? Integer.hashCode(npcId) : NameNormalizer.normalize(npcName).hashCode();
    return hash & Integer.MAX_VALUE;
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

public enum NpcVoiceScope {
  THIS_NPC,
  THIS_CHARACTER,
  SAME_NAME
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.math.BigDecimal;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.UnaryOperator;

public final class NpcVoiceTransferCodec {

  public static final String FORMAT = "voiced-dialogue-npc-voices";
  public static final int VERSION = 1;

  private final UnaryOperator<NpcVoiceOverride> sanitizer;
  private final Gson gson;

  public NpcVoiceTransferCodec(UnaryOperator<NpcVoiceOverride> sanitizer, Gson gson) {
    this.sanitizer = sanitizer;
    this.gson = gson.newBuilder().setPrettyPrinting().create();
  }

  public String encode(Map<Integer, NpcVoiceOverride> overrides) {
    JsonObject entries = new JsonObject();
    new TreeMap<>(overrides)
        .forEach(
            (id, override) -> entries.add(id.toString(), NpcVoiceOverrideJson.toJson(override)));
    JsonObject document = new JsonObject();
    document.addProperty("format", FORMAT);
    document.addProperty("version", VERSION);
    document.add("overrides", entries);
    return gson.toJson(document);
  }

  public NpcVoiceImport decode(String text) throws InvalidDocumentException {
    JsonObject document = parseDocument(text);
    if (!FORMAT.equals(stringOrNull(document.get("format")))) {
      throw new InvalidDocumentException("That is not a Voiced Dialogue NPC voices file.");
    }
    checkVersion(document.get("version"));
    JsonElement entries = document.get("overrides");
    if (entries == null || !entries.isJsonObject()) {
      throw new InvalidDocumentException("The file has no NPC voices list.");
    }
    Map<Integer, NpcVoiceOverride> overrides = new TreeMap<>();
    int skipped = 0;
    for (Map.Entry<String, JsonElement> entry : entries.getAsJsonObject().entrySet()) {
      Integer id = npcId(entry.getKey());
      NpcVoiceOverride override = id == null ? null : override(entry.getValue());
      if (override == null) {
        skipped++;
      } else {
        overrides.put(id, override);
      }
    }
    return new NpcVoiceImport(overrides, skipped);
  }

  private static JsonObject parseDocument(String text) throws InvalidDocumentException {
    JsonElement parsed;
    try {
      parsed = new JsonParser().parse(text == null ? "" : text);
    } catch (RuntimeException e) {
      throw new InvalidDocumentException("That is not valid JSON.");
    }
    if (!parsed.isJsonObject()) {
      throw new InvalidDocumentException("That is not a Voiced Dialogue NPC voices file.");
    }
    return parsed.getAsJsonObject();
  }

  private static void checkVersion(JsonElement version) throws InvalidDocumentException {
    boolean known =
        version != null
            && version.isJsonPrimitive()
            && version.getAsJsonPrimitive().isNumber()
            && version.getAsBigDecimal().compareTo(BigDecimal.valueOf(VERSION)) == 0;
    if (!known) {
      throw new InvalidDocumentException(
          "This file uses a version this plugin does not know. Update Voiced Dialogue and try"
              + " again.");
    }
  }

  private static Integer npcId(String key) {
    try {
      int id = Integer.parseInt(key);
      return id < 0 || !String.valueOf(id).equals(key) ? null : id;
    } catch (NumberFormatException e) {
      return null;
    }
  }

  private NpcVoiceOverride override(JsonElement value) {
    NpcVoiceOverride sanitized;
    try {
      sanitized = sanitizer.apply(NpcVoiceOverrideJson.parse(value));
    } catch (RuntimeException e) {
      return null;
    }
    return sanitized.isEmpty() ? null : sanitized;
  }

  private static String stringOrNull(JsonElement element) {
    return element != null && element.isJsonPrimitive() && element.getAsJsonPrimitive().isString()
        ? element.getAsString()
        : null;
  }

  public static final class InvalidDocumentException extends Exception {
    InvalidDocumentException(String message) {
      super(message);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class ProfanityFilter {

  private static final String WORDLIST_RESOURCE = "/profanity.txt";

  private static final Pattern TOKEN =
      Pattern.compile("[\\p{L}\\p{N}@$](?:[\\p{L}\\p{N}._*@$-]*[\\p{L}\\p{N}@$])?");

  private static final char[] LEET_FROM = {'0', '1', '3', '4', '5', '7', '@', '$'};

  private static final char[] LEET_TO = {'o', 'i', 'e', 'a', 's', 't', 'a', 's'};

  private static final Set<String> ALLOWLIST =
      Collections.unmodifiableSet(
          new HashSet<>(
              Arrays.asList(
                  "scunthorpe",
                  "assassin",
                  "assassinate",
                  "assassination",
                  "assess",
                  "assassins",
                  "sussex",
                  "penistone",
                  "class",
                  "pass",
                  "bass",
                  "grass",
                  "compass",
                  "cockle",
                  "shitake",
                  "dickens")));

  private final Set<String> blocklist;

  public ProfanityFilter() {
    this.blocklist = loadBundled();
  }

  private Set<String> loadBundled() {
    Set<String> words = new HashSet<>();
    try (InputStream stream = getClass().getResourceAsStream(WORDLIST_RESOURCE)) {
      if (stream == null) {
        log.warn(
            "Profanity wordlist {} not found - profanity masking is a no-op this session",
            WORDLIST_RESOURCE);
        return Collections.emptySet();
      }
      try (BufferedReader reader =
          new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
        String line;
        while ((line = reader.readLine()) != null) {
          String entry = line.trim();
          if (entry.isEmpty() || entry.charAt(0) == '#') {
            continue;
          }
          String normalized = normalize(entry);
          if (!normalized.isEmpty()) {
            words.add(normalized);
          }
        }
      }
    } catch (Exception e) {
      log.error("Failed to load profanity wordlist {}: {}", WORDLIST_RESOURCE, e.getMessage());
      return Collections.emptySet();
    }
    return Collections.unmodifiableSet(words);
  }

  static String normalize(String text) {
    StringBuilder out = new StringBuilder(text.length());
    String lower = text.toLowerCase(Locale.ROOT);
    for (int i = 0; i < lower.length(); i++) {
      char c = lower.charAt(i);
      char mapped = leet(c);
      if (mapped >= 'a' && mapped <= 'z') {
        out.append(mapped);
      }
    }
    return out.toString();
  }

  private static char leet(char c) {
    for (int i = 0; i < LEET_FROM.length; i++) {
      if (LEET_FROM[i] == c) {
        return LEET_TO[i];
      }
    }
    return c;
  }

  public String mask(String text) {
    if (text == null || text.isEmpty() || blocklist.isEmpty()) {
      return text;
    }
    Matcher matcher = TOKEN.matcher(text);
    StringBuilder out = null;
    int last = 0;
    while (matcher.find()) {
      String token = matcher.group();
      String normalized = normalize(token);
      if (normalized.isEmpty()
          || ALLOWLIST.contains(normalized)
          || !blocklist.contains(normalized)) {
        continue;
      }
      if (out == null) {
        out = new StringBuilder(text.length());
      }
      out.append(text, last, matcher.start());
      for (int i = matcher.start(); i < matcher.end(); i++) {
        out.append('*');
      }
      last = matcher.end();
    }
    if (out == null) {
      return text;
    }
    out.append(text, last, text.length());
    return out.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public final class RecentNpcSpeakers {

  static final int CAPACITY = 30;

  private final Deque<HeardNpc> ring = new ArrayDeque<>();
  private volatile Runnable listener = () -> {};

  public void record(int npcId, String npcName) {
    if (npcName == null || npcName.trim().isEmpty()) {
      return;
    }
    HeardNpc heard = new HeardNpc(npcId, npcName.trim());
    synchronized (this) {
      if (heard.equals(ring.peekFirst())) {
        return;
      }
      ring.remove(heard);
      ring.addFirst(heard);
      while (ring.size() > CAPACITY) {
        ring.removeLast();
      }
    }
    listener.run();
  }

  public synchronized List<HeardNpc> newestFirst() {
    return new ArrayList<>(ring);
  }

  public void setListener(Runnable listener) {
    this.listener = listener == null ? () -> {} : listener;
  }
}

