public final class NameNormalizer {

  private static final Pattern TAG = Pattern.compile("<[^>]*>");

  private static final char NON_BREAKING_SPACE = ' ';

  private NameNormalizer() {}

  public static String normalize(String name) {
    if (name == null) {
