package com.grahambartley.runelite.voiced.dialogue.speaker;

public enum RaceBucket {
  ARCEUUS("Arceuus", NpcRace.ARCEUUS, "arceuus"),
  ARANEI("Aranei", NpcRace.ARANEI, "aranei"),
  HUMAN("Human", NpcRace.HUMAN, "human", "man", "person"),
  ELF("Elf", NpcRace.ELF, "elf", "elven"),
  DWARF("Dwarf", NpcRace.DWARF, "dwarf", "dwarven"),
  GNOME("Gnome", NpcRace.GOBLIN, "gnome"),
  GOBLIN("Goblin", NpcRace.GOBLIN, "goblin"),
  TROLL("Troll", NpcRace.TROLL, "troll", "giant"),
  UNDEAD("Undead", NpcRace.UNDEAD, "undead", "skeleton", "zombie", "ghost", "revenant", "reanimat"),
  DEMON("Demon", NpcRace.DEMON, "demon", "dragon", "devil", "hellhound"),
  DOG("Dog", NpcRace.DOG, "dog"),
  CRAB("Crab", NpcRace.CRAB, "crab"),
  PENGUIN("Penguin", NpcRace.PENGUIN, "penguin"),
  GORILLA("Gorilla", NpcRace.GORILLA, "gorilla"),
  MONKEY("Monkey", NpcRace.MONKEY, "monkey", "primate"),
  WIZARD("Wizard", NpcRace.WIZARD, "wizard", "mage"),
  TORTUGAN("Tortugan", NpcRace.TORTUGAN, "tortugan", "tortuga"),
  ICYENE("Icyene", NpcRace.ICYENE, "icyene");

  private final String bucketName;
  private final NpcRace race;
  private final String[] keywords;

  RaceBucket(String bucketName, NpcRace race, String... keywords) {
    this.bucketName = bucketName;
    this.race = race;
    this.keywords = keywords;
  }

  public NpcRace race() {
    return race;
  }

  static RaceBucket forBucketName(String race) {
    for (RaceBucket bucket : values()) {
      if (bucket.bucketName.equalsIgnoreCase(race)) {
        return bucket;
      }
    }
    return null;
  }

  static RaceBucket forKeyword(String race) {
    String lower = race.toLowerCase();
    for (RaceBucket bucket : values()) {
      for (String keyword : bucket.keywords) {
        if (lower.contains(keyword)) {
          return bucket;
        }
      }
    }
    return null;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.grahambartley.runelite.voiced.dialogue.speaker.LearnedNpcStore;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import java.util.function.IntPredicate;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class NpcLearningService {

  private static final String DIALOGUE_OPTION_PREFIX = "talk";

  private static final int FAILURES_BEFORE_QUIET = 3;

  private static final long QUIET_MILLIS = TimeUnit.MINUTES.toMillis(2);

  private final WikiNpcClient client;
  private final LearnedNpcStore store;
  private final Executor executor;
  private final BooleanSupplier enabled;
  private final IntPredicate voiced;
  private final WikiCallThrottle throttle;
  private final Set<Integer> attempted = ConcurrentHashMap.newKeySet();

  private final AtomicInteger consecutiveFailures = new AtomicInteger();

  private volatile long quietUntilMillis;

  private volatile boolean closed;

  public NpcLearningService(
      WikiNpcClient client,
      LearnedNpcStore store,
      Executor executor,
      BooleanSupplier enabled,
      IntPredicate voiced,
      WikiCallThrottle throttle) {
    this.client = client;
    this.store = store;
    this.executor = executor;
    this.enabled = enabled;
    this.voiced = voiced;
    this.throttle = throttle;
  }

  public void close() {
    closed = true;
  }

  public boolean isEnabled() {
    return enabled.getAsBoolean();
  }

  public boolean startsConversation(String menuOption) {
    return menuOption != null
        && menuOption.regionMatches(
            true, 0, DIALOGUE_OPTION_PREFIX, 0, DIALOGUE_OPTION_PREFIX.length());
  }

  public void considerLearning(int npcId, String npcName) {
    if (closed || !enabled.getAsBoolean() || npcName == null || npcName.isEmpty()) {
      return;
    }
    long now = System.currentTimeMillis();
    if (now < quietUntilMillis) {
      return;
    }
    if (voiced.test(npcId) || !store.isPastMissWindow(npcId, now) || !attempted.add(npcId)) {
      return;
    }
    executor.execute(
        () -> {
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          throttle.awaitTurn();
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          WikiLookup lookup = client.lookup(npcId, npcName);
          if (closed) {
            attempted.remove(npcId);
            return;
          }
          if (lookup.isUnreachable()) {
            attempted.remove(npcId);
            if (consecutiveFailures.incrementAndGet() >= FAILURES_BEFORE_QUIET) {
              quietUntilMillis = System.currentTimeMillis() + QUIET_MILLIS;
            }
            log.debug("[TTS learn] wiki was unreachable for '{}' (id {})", npcName, npcId);
            return;
          }
          consecutiveFailures.set(0);
          if (lookup.isUndocumented()) {
            store.missed(npcId, System.currentTimeMillis());
            log.debug("[TTS learn] wiki had no usable entry for '{}' (id {})", npcName, npcId);
            return;
          }
          NpcAttributes attributes = lookup.attributes();
          store.learn(
              npcId, attributes.getRace(), attributes.getGender(), attributes.getEthnicity());
          log.info(
              "[TTS learn] learned '{}' (id {}) from wiki -> race={} gender={} ethnicity={}",
              npcName,
              npcId,
              attributes.getRace(),
              attributes.getGender(),
              attributes.getEthnicity() == null ? "-" : attributes.getEthnicity());
        });
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

public final class WikiCallThrottle {

  private final long intervalNanos;

  private boolean started;

  private long lastCallAt;

  public WikiCallThrottle(long intervalMillis) {
    this.intervalNanos = TimeUnit.MILLISECONDS.toNanos(intervalMillis);
  }

  public void awaitTurn() {
    long waitNanos;
    synchronized (this) {
      long now = System.nanoTime();
      long turnAt = started ? lastCallAt + intervalNanos : now;
      if (turnAt < now) {
        turnAt = now;
      }
      waitNanos = turnAt - now;
      lastCallAt = turnAt;
      started = true;
    }
    if (waitNanos <= 0) {
      return;
    }
    CompletableFuture.runAsync(
            () -> {}, CompletableFuture.delayedExecutor(waitNanos, TimeUnit.NANOSECONDS))
        .join();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.UnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class WikiInfobox {

  private static final Pattern RACE = versionedField("race");
  private static final Pattern GENDER = versionedField("gender");
  private static final Pattern ID = versionedField("id");
  private static final Pattern LEAGUE_REGION = field("leagueRegion");
  private static final Pattern LOCATION = field("location");
  private static final Pattern ID_SEPARATOR = Pattern.compile("[,\\s]+");
  private static final Pattern LINK = Pattern.compile("\\[\\[([^\\[\\]]*)\\]\\]");
  private static final Pattern REF_TAG =
      Pattern.compile("<ref[^>]*>.*?</ref>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
  private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
  private static final Pattern TEMPLATE = Pattern.compile("\\{\\{[^}]*\\}\\}");
  private static final UnaryOperator<String> LINK_TARGET = body -> body.split("\\|", -1)[0];
  private static final UnaryOperator<String> LINK_DISPLAY =
      body -> {
        String[] parts = body.split("\\|", -1);
        return parts[parts.length - 1];
      };

  private static Pattern versionedField(String key) {
    return field(key + "\\d*");
  }

  private static Pattern field(String key) {
    return Pattern.compile("\\|\\s*" + key + "\\s*=\\s*([^\\n]+)", Pattern.CASE_INSENSITIVE);
  }

  private final List<String> raceReadings;
  private final String leagueRegion;
  private final String location;
  private final List<String> genders;
  private final List<List<Integer>> idGroups;
  private final List<String> categories;

  private WikiInfobox(
      List<String> raceReadings,
      String leagueRegion,
      String location,
      List<String> genders,
      List<List<Integer>> idGroups,
      List<String> categories) {
    this.raceReadings = raceReadings;
    this.leagueRegion = leagueRegion;
    this.location = location;
    this.genders = genders;
    this.idGroups = idGroups;
    this.categories = categories;
  }

  static WikiInfobox parse(String wikitext, List<String> categories) {
    return new WikiInfobox(
        linkReadings(rawField(RACE, wikitext)),
        firstField(LEAGUE_REGION, wikitext),
        firstField(LOCATION, wikitext),
        cleanFields(GENDER, wikitext),
        idGroups(wikitext),
        categories == null ? Collections.<String>emptyList() : categories);
  }

  List<String> raceReadings() {
    return raceReadings;
  }

  String leagueRegion() {
    return leagueRegion;
  }

  String location() {
    return location;
  }

  List<String> categories() {
    return categories;
  }

  String genderForVersion(int npcId) {
    if (genders.isEmpty()) {
      return null;
    }
    if (genders.size() != idGroups.size()) {
      return genders.get(0);
    }
    for (int index = 0; index < idGroups.size(); index++) {
      if (idGroups.get(index).contains(npcId)) {
        return genders.get(index);
      }
    }
    return genders.get(0);
  }

  private static List<List<Integer>> idGroups(String wikitext) {
    List<List<Integer>> groups = new ArrayList<>();
    for (String raw : fieldTexts(ID, wikitext)) {
      List<Integer> ids = new ArrayList<>();
      for (String token : ID_SEPARATOR.split(clean(raw, LINK_TARGET))) {
        if (!token.isEmpty() && token.chars().allMatch(Character::isDigit)) {
          ids.add(Integer.valueOf(token));
        }
      }
      if (!ids.isEmpty()) {
        groups.add(ids);
      }
    }
    return groups;
  }

  private static List<String> cleanFields(Pattern pattern, String wikitext) {
    List<String> values = new ArrayList<>();
    for (String raw : fieldTexts(pattern, wikitext)) {
      values.add(clean(raw, LINK_TARGET));
    }
    return values;
  }

  private static String firstField(Pattern pattern, String wikitext) {
    String raw = rawField(pattern, wikitext);
    return raw == null ? null : clean(raw, LINK_TARGET);
  }

  private static String rawField(Pattern pattern, String wikitext) {
    List<String> texts = fieldTexts(pattern, wikitext);
    return texts.isEmpty() ? null : texts.get(0);
  }

  private static List<String> fieldTexts(Pattern pattern, String wikitext) {
    List<String> values = new ArrayList<>();
    Matcher matcher = pattern.matcher(wikitext);
    int from = 0;
    while (from <= wikitext.length() && matcher.find(from)) {
      String text = fieldText(matcher.group(1));
      values.add(text);
      from = matcher.start(1) + text.length();
    }
    return values;
  }

  private static String fieldText(String value) {
    int depth = 0;
    int index = 0;
    while (index < value.length()) {
      String token = value.length() - index >= 2 ? value.substring(index, index + 2) : "";
      if ("[[".equals(token) || "{{".equals(token)) {
        depth++;
        index += 2;
      } else if ("]]".equals(token) || "}}".equals(token)) {
        if (depth == 0) {
          return value.substring(0, index);
        }
        depth--;
        index += 2;
      } else if (value.charAt(index) == '|' && depth == 0) {
        return value.substring(0, index);
      } else {
        index++;
      }
    }
    return value;
  }

  private static List<String> linkReadings(String value) {
    List<String> readings = new ArrayList<>();
    if (value == null) {
      return readings;
    }
    String target = clean(value, LINK_TARGET);
    String display = clean(value, LINK_DISPLAY);
    if (!target.isEmpty()) {
      readings.add(target);
    }
    if (!display.isEmpty() && !display.equals(target)) {
      readings.add(display);
    }
    return readings;
  }

  private static String clean(String value, UnaryOperator<String> side) {
    String cleaned = REF_TAG.matcher(value).replaceAll("");
    cleaned = HTML_TAG.matcher(cleaned).replaceAll("");
    cleaned = resolveLinks(cleaned, side);
    cleaned = cleaned.replace("[[", "").replace("]]", "");
    cleaned = TEMPLATE.matcher(cleaned).replaceAll("");
    return cleaned.trim();
  }

  private static String resolveLinks(String value, UnaryOperator<String> side) {
    Matcher matcher = LINK.matcher(value);
    StringBuilder out = new StringBuilder();
    while (matcher.find()) {
      matcher.appendReplacement(out, Matcher.quoteReplacement(side.apply(matcher.group(1))));
    }
    matcher.appendTail(out);
    return out.toString();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;

public final class WikiLookup {

  private static final WikiLookup UNDOCUMENTED = new WikiLookup(null, true);
  private static final WikiLookup UNREACHABLE = new WikiLookup(null, false);

  private final NpcAttributes attributes;
  private final boolean answered;

  private WikiLookup(NpcAttributes attributes, boolean answered) {
    this.attributes = attributes;
    this.answered = answered;
  }

  static WikiLookup of(NpcAttributes attributes) {
    return new WikiLookup(attributes, true);
  }

  static WikiLookup undocumented() {
    return UNDOCUMENTED;
  }

  static WikiLookup unreachable() {
    return UNREACHABLE;
  }

  public NpcAttributes attributes() {
    return attributes;
  }

  public boolean isUndocumented() {
    return answered && attributes == null;
  }

  public boolean isUnreachable() {
    return !answered;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

final class WikiMapping {

  private static final String RESOURCE = "/wiki-mapping.json";

  private static final WikiMapping INSTANCE = load();

  private final List<RacePattern> raceRules;
  private final List<CategoryRule> categoryRules;
  private final Map<String, String> leagueRegionEthnicity;
  private final Pattern infoboxTemplates;
  private final String defaultRace;
  private final String defaultGender;
  private final String femaleGender;
  private final String desertLeagueRegion;
  private final Pattern menaphiteHint;
  private final String menaphiteEthnicity;
  private final String desertEthnicity;

  private WikiMapping(JsonObject root) {
    raceRules = new ArrayList<>();
    for (JsonElement element : root.getAsJsonArray("raceRules")) {
      JsonObject rule = element.getAsJsonObject();
      raceRules.add(
          new RacePattern(
              Pattern.compile(rule.get("pattern").getAsString(), Pattern.CASE_INSENSITIVE),
              rule.get("race").getAsString()));
    }
    categoryRules = new ArrayList<>();
    for (JsonElement element : root.getAsJsonArray("categoryRaceRules")) {
      JsonObject rule = element.getAsJsonObject();
      categoryRules.add(
          new CategoryRule(
              rule.get("keyword").getAsString().toLowerCase(Locale.ROOT),
              rule.get("race").getAsString()));
    }
    leagueRegionEthnicity = new HashMap<>();
    JsonObject regions = root.getAsJsonObject("leagueRegionEthnicity");
    for (String region : regions.keySet()) {
      leagueRegionEthnicity.put(region.toLowerCase(Locale.ROOT), regions.get(region).getAsString());
    }
    infoboxTemplates = infoboxPattern(root.getAsJsonArray("infoboxTemplates"));
    defaultRace = root.get("defaultRace").getAsString();
    defaultGender = root.get("defaultGender").getAsString();
    femaleGender = root.get("femaleGender").getAsString();
    JsonObject desert = root.getAsJsonObject("desert");
    desertLeagueRegion = desert.get("leagueRegion").getAsString().toLowerCase(Locale.ROOT);
    menaphiteHint = Pattern.compile(desert.get("hint").getAsString(), Pattern.CASE_INSENSITIVE);
    menaphiteEthnicity = desert.get("hinted").getAsString();
    desertEthnicity = desert.get("default").getAsString();
  }

  static WikiMapping get() {
    return INSTANCE;
  }

  String defaultRace() {
    return defaultRace;
  }

  String genderForWikiText(String genderText) {
    if (genderText != null) {
      String normalised = genderText.trim().toLowerCase(Locale.ROOT);
      if (normalised.startsWith("f")) {
        return femaleGender;
      }
    }
    return defaultGender;
  }

  String raceForWikiText(List<String> raceReadings) {
    if (raceReadings.isEmpty()) {
      return null;
    }
    for (String reading : raceReadings) {
      for (RacePattern rule : raceRules) {
        if (rule.pattern.matcher(reading).find()) {
          return rule.race;
        }
      }
    }
    return defaultRace;
  }

  String raceForCategories(List<String> categories) {
    if (categories == null || categories.isEmpty()) {
      return null;
    }
    String joined = String.join(" ", categories).toLowerCase(Locale.ROOT);
    for (CategoryRule rule : categoryRules) {
      if (joined.contains(rule.keyword)) {
        return rule.race;
      }
    }
    return null;
  }

  String ethnicityKey(String leagueRegion, String location, List<String> categories) {
    if (leagueRegion == null) {
      return null;
    }
    String region = leagueRegion.trim();
    if (region.contains(",") || region.contains("&")) {
      return null;
    }
    String key = region.toLowerCase(Locale.ROOT);
    if (key.equals(desertLeagueRegion)) {
      StringBuilder hint = new StringBuilder(location == null ? "" : location);
      if (categories != null) {
        for (String category : categories) {
          hint.append(' ').append(category);
        }
      }
      return menaphiteHint.matcher(hint).find() ? menaphiteEthnicity : desertEthnicity;
    }
    return leagueRegionEthnicity.get(key);
  }

  boolean isNpcPage(String wikitext) {
    return wikitext != null && infoboxTemplates.matcher(wikitext).find();
  }

  private static Pattern infoboxPattern(JsonArray templates) {
    StringBuilder alternatives = new StringBuilder();
    for (JsonElement element : templates) {
      String name = element.getAsString().replaceFirst("^[^:]+:", "");
      alternatives.append(alternatives.length() == 0 ? "" : "|");
      alternatives.append(Pattern.quote(name).replace(" ", "\\E[ _]+\\Q"));
    }
    return Pattern.compile("\\{\\{\\s*(" + alternatives + ")", Pattern.CASE_INSENSITIVE);
  }

  private static WikiMapping load() {
    try (InputStream stream = WikiMapping.class.getResourceAsStream(RESOURCE)) {
      if (stream == null) {
        throw new IllegalStateException("Missing bundled resource " + RESOURCE);
      }
      JsonObject root =
          new JsonParser()
              .parse(new InputStreamReader(stream, StandardCharsets.UTF_8))
              .getAsJsonObject();
      return new WikiMapping(root);
    } catch (Exception e) {
      throw new IllegalStateException("Could not read " + RESOURCE, e);
    }
  }

  private static final class RacePattern {
    private final Pattern pattern;
    private final String race;

    private RacePattern(Pattern pattern, String race) {
      this.pattern = pattern;
      this.race = race;
    }
  }

  private static final class CategoryRule {
    private final String keyword;
    private final String race;

    private CategoryRule(String keyword, String race) {
      this.keyword = keyword;
      this.race = race;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speaker.wiki;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.AttributeSource;
import com.grahambartley.runelite.voiced.dialogue.speaker.NameNormalizer;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcAttributes;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class WikiNpcClient {

  private static final String PRODUCTION_API = "https://oldschool.runescape.wiki/api.php";
  private static final String USER_AGENT = "runelite-voiced-dialogue";
  private static final Duration CALL_TIMEOUT = Duration.ofSeconds(8);
  private static final String CATEGORY_LIMIT = "500";

  private final OkHttpClient httpClient;
  private final String api;
  private final WikiMapping mapping = WikiMapping.get();

  public WikiNpcClient(OkHttpClient httpClient) {
    this(httpClient, PRODUCTION_API);
  }

  WikiNpcClient(OkHttpClient httpClient, String api) {
    this.httpClient = httpClient.newBuilder().callTimeout(CALL_TIMEOUT).build();
    this.api = api;
  }

  public WikiLookup lookup(int npcId, String npcName) {
    String title = NameNormalizer.normalize(npcName);
    if (title.isEmpty()) {
      return WikiLookup.undocumented();
    }
    HttpUrl url =
        HttpUrl.get(api)
            .newBuilder()
            .addQueryParameter("action", "query")
            .addQueryParameter("prop", "revisions|categories")
            .addQueryParameter("rvprop", "content")
            .addQueryParameter("rvslots", "main")
            .addQueryParameter("rvsection", "0")
            .addQueryParameter("cllimit", CATEGORY_LIMIT)
            .addQueryParameter("redirects", "1")
            .addQueryParameter("format", "json")
            .addQueryParameter("formatversion", "2")
            .addQueryParameter("titles", title)
            .build();
    Request request =
        new Request.Builder().url(url).addHeader("User-Agent", USER_AGENT).get().build();

    String body;
    try (Response response = httpClient.newCall(request).execute()) {
      if (!response.isSuccessful()) {
        log.debug("Wiki lookup for '{}' answered {}", title, response.code());
        return WikiLookup.unreachable();
      }
      ResponseBody payload = response.body();
      body = payload == null ? null : payload.string();
    } catch (Exception e) {
      log.debug("Wiki lookup for '{}' failed: {}", title, e.getMessage());
      return WikiLookup.unreachable();
    }

    JsonObject query = queryOf(body);
    if (query == null) {
      log.debug("Wiki lookup for '{}' answered something other than wiki json", title);
      return WikiLookup.unreachable();
    }
    JsonObject page = firstPage(query);
    if (page == null) {
      return WikiLookup.undocumented();
    }
    String wikitext = wikitextOf(page);
    if (wikitext == null || !mapping.isNpcPage(wikitext)) {
      return WikiLookup.undocumented();
    }
    return WikiLookup.of(attributesFrom(npcId, WikiInfobox.parse(wikitext, categoriesOf(page))));
  }

  private NpcAttributes attributesFrom(int npcId, WikiInfobox infobox) {
    String race = mapping.raceForWikiText(infobox.raceReadings());
    if (race == null) {
      race = mapping.raceForCategories(infobox.categories());
    }
    if (race == null) {
      race = mapping.defaultRace();
    }
    NpcAttributes attributes =
        new NpcAttributes(race, gender(npcId, infobox), AttributeSource.WIKI);
    attributes.setNpcId(npcId);
    attributes.setEthnicity(
        mapping.ethnicityKey(infobox.leagueRegion(), infobox.location(), infobox.categories()));
    return attributes;
  }

  private String gender(int npcId, WikiInfobox infobox) {
    return mapping.genderForWikiText(infobox.genderForVersion(npcId));
  }

  private static JsonObject queryOf(String json) {
    if (json == null) {
      return null;
    }
    try {
      JsonElement root = new JsonParser().parse(json);
      if (!root.isJsonObject() || !root.getAsJsonObject().has("query")) {
        return null;
      }
      return root.getAsJsonObject().getAsJsonObject("query");
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static JsonObject firstPage(JsonObject query) {
    try {
      JsonArray pages = query.getAsJsonArray("pages");
      return pages.size() == 0 ? null : pages.get(0).getAsJsonObject();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static String wikitextOf(JsonObject page) {
    try {
      return page.getAsJsonArray("revisions")
          .get(0)
          .getAsJsonObject()
          .getAsJsonObject("slots")
          .getAsJsonObject("main")
          .get("content")
          .getAsString();
    } catch (RuntimeException e) {
      return null;
    }
  }

  private static List<String> categoriesOf(JsonObject page) {
    List<String> categories = new ArrayList<>();
    if (!page.has("categories") || !page.get("categories").isJsonArray()) {
      return categories;
    }
    for (JsonElement element : page.getAsJsonArray("categories")) {
      JsonObject category = element.getAsJsonObject();
      if (category.has("title")) {
        categories.add(category.get("title").getAsString());
      }
    }
    return categories;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class BackendProvider {

  private final SynthesisBackend openRouter;
  private final SynthesisBackend googleAiStudio;
  private final Supplier<VoicedDialogueConfig.TtsProvider> selectedProvider;

  public BackendProvider(SynthesisBackend backend) {
    this(backend, backend, () -> VoicedDialogueConfig.TtsProvider.OPENROUTER);
  }

  public BackendProvider(
      SynthesisBackend openRouter,
      SynthesisBackend googleAiStudio,
      Supplier<VoicedDialogueConfig.TtsProvider> selectedProvider) {
    this.openRouter = openRouter;
    this.googleAiStudio = googleAiStudio;
    this.selectedProvider = selectedProvider;
  }

  public void clearRateLimits() {
    openRouter.clearRateLimit();
    googleAiStudio.clearRateLimit();
  }

  public SynthesisBackend active() {
    return selectedProvider.get() == VoicedDialogueConfig.TtsProvider.GOOGLE_AI_STUDIO
        ? googleAiStudio
        : openRouter;
  }

  public static SynthesisRequest downgradeFor(SynthesisBackend backend, SynthesisRequest request) {
    if (backend.supportedEmotions().contains(request.emotion())) {
      return request;
    }
    return request.withEmotion(Emotion.NEUTRAL);
  }

  public Pcm synthesizeWith(SynthesisBackend backend, SynthesisRequest request) {
    return backend.synthesize(downgradeFor(backend, request));
  }

  public Pcm synthesizeStreamingWith(
      SynthesisBackend backend, SynthesisRequest request, PcmSink sink) {
    return backend.synthesizeStreaming(downgradeFor(backend, request), sink);
  }

  public void warmUpActive() {
    active().warmUp();
  }

  public void close() {
    closeQuietly(openRouter);
    if (googleAiStudio != openRouter) {
      closeQuietly(googleAiStudio);
    }
  }

  private static void closeQuietly(SynthesisBackend backend) {
    try {
      backend.close();
    } catch (RuntimeException e) {
      log.debug("Error closing backend {}: {}", backend.id(), e.getMessage());
    }
  }
}

