import java.util.List;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class CloudSpeechExecutor {

  public static final int MAX_SPEECH_ATTEMPTS = 2;

  public static final String CACHE_NAMESPACE = "cloud-speech";

  public interface Ops {

    public String apiKey();

    String missingKeyNotice();

    String translate(String text, String language, String apiKey);

    PreparedSpeech buildRequests(SpokenLine line, SynthesisRequest request);

    Call newCall(Request httpRequest, int inputLen);

    default String generationId(Response response) {
      return "";
    }

    DecodedSpeech decodeBuffered(byte[] bytes, PreparedSpeech prepared);

    StreamDrain newStreamDrain();

    default void recordSpendOnFirstChunk(PreparedSpeech prepared) {}

    String failureNotice(int httpCode, byte[] body);

    default long statedWaitMillis(byte[] body) {
      return 0;
    }

    String emptyBodyNotice();
  }

  public interface StreamDrain {

    void drain(ResponseBody body, ChunkSink chunk) throws IOException;

    default boolean finishedCleanly() {
      return true;
    }

    default void bankSpend(PreparedSpeech prepared) {}
  }

  public interface ChunkSink {
    void accept(byte[] bytes, int len);
  }

  public static final class SpokenLine {
    public final String apiKey;
    public final String input;
    public final String style;
    public final String voice;
    public final double speedRatio;

    public SpokenLine(String apiKey, String input, String style, String voice, double speedRatio) {
      this.apiKey = apiKey;
      this.input = input;
      this.style = style;
      this.voice = voice;
      this.speedRatio = speedRatio;
    }
  }

  public static final class PreparedSpeech {
    final Request buffered;
    final Request streaming;
    public final double speedRatio;
    public final int inputLen;
    public final boolean prefetch;

    public PreparedSpeech(
        Request buffered, Request streaming, double speedRatio, int inputLen, boolean prefetch) {
      this.buffered = buffered;
      this.streaming = streaming;
      this.speedRatio = speedRatio;
      this.inputLen = inputLen;
      this.prefetch = prefetch;
    }

    public PreparedSpeech(Request request, double speedRatio, int inputLen, boolean prefetch) {
      this(request, request, speedRatio, inputLen, prefetch);
    }
  }

  public static final class DecodedSpeech {

    public static final DecodedSpeech EMPTY = new DecodedSpeech(null, 0, () -> {});

    final Pcm pcm;
    final int audioBytes;

    final Runnable bankSpend;

    public DecodedSpeech(Pcm pcm, int audioBytes, Runnable bankSpend) {
      this.pcm = pcm;
      this.audioBytes = audioBytes;
      this.bankSpend = bankSpend;
    }
  }

  private final VoicedDialogueConfig config;
  private final CloudBackendSupport support;
  private final GeminiTtsModel model;
  private final String providerName;
  private final Ops ops;
  private final RateLimitBackoff backoff = new RateLimitBackoff();

  public CloudSpeechExecutor(
      VoicedDialogueConfig config,
      CloudBackendSupport support,
      GeminiTtsModel model,
      String providerName,
      Ops ops) {
    this.config = config;
    this.support = support;
    this.model = model;
    this.providerName = providerName;
    this.ops = ops;
  }

  public boolean isThrottled() {
    return backoff.isThrottled();
  }

  public void clearRateLimit() {
    backoff.reset();
  }

  public String cacheVariant(SynthesisRequest request) {
    return CloudCacheKeyBuilder.build(
        model.voiceFor(request.voice(), request.profile()),
        request.voice(),
        support.speedPercent(),
        request.profile(),
        CloudTtsText.languageCacheToken(config, request));
  }

  public Pcm synthesize(SynthesisRequest request) {
    PreparedSpeech prepared = prepare(request);
    if (prepared == null) {
      return null;
    }
    return runBuffered(prepared);
  }

  public Pcm synthesizeStreaming(SynthesisRequest request, PcmSink sink) {
    PreparedSpeech prepared = prepare(request);
    if (prepared == null) {
      return null;
    }
    return runStreaming(prepared, sink);
  }

  private PreparedSpeech prepare(SynthesisRequest request) {
    if (backoff.isRefusing()) {
      log.debug("[TTS cloud] {} asked to be left alone; this line was not voiced", providerName);
      return null;
    }
    String rawKey = ops.apiKey();
    if (!CloudHttp.isNonBlank(rawKey)) {
      support.noticeMissingKey(ops.missingKeyNotice());
      return null;
    }
    String apiKey = rawKey.trim();
    String text = request.text();
    String language = CloudTtsText.effectiveSpokenLanguage(config, request);
    boolean translating =
        CloudTtsText.needsTranslation(language) && !request.skipTranslation() && !text.isEmpty();
    String spokenText = text;
    if (translating) {
      String translated = ops.translate(text, language.trim(), apiKey);
      if (translated == null) {
        support.warnOnce(
            providerName
                + " translation to "
                + language.trim()
                + " failed; this line was not voiced.");
        return null;
      }
      spokenText = translated;
    }
    CharacterProfile profile = request.profile();
    int speed = support.speedPercent();
    double speedRatio = speed / (double) CloudBackendSupport.DEFAULT_SPEED_PERCENT;
    String spokenLanguage =
        translating ? CloudTtsText.spokenLanguage(config) : CloudTtsText.DEFAULT_LANGUAGE;
    String style =
        speed != CloudBackendSupport.DEFAULT_SPEED_PERCENT
            ? model.speechStyle(profile, request.voice(), request.emotion(), spokenLanguage, speed)
            : model.speechStyle(profile, request.voice(), request.emotion(), spokenLanguage);

    String voice = model.voiceFor(request.voice(), profile);

    if (config.debugMode()) {
      String region = model.voiceRegionFor(request.voice(), profile);
      log.info(
          "[TTS voice] cloud voice {} region {} emotion {} -> style '{}'",
          voice,
          region == null ? "-" : region,
          request.emotion(),
          style);
      log.info(
          "[TTS cloud] character profile '{}' accent='{}' (cacheKey={})",
          profile.name(),
          profile.accent(),
          profile.cacheKey());
      if (speed != CloudBackendSupport.DEFAULT_SPEED_PERCENT) {
        log.info("[TTS cloud] speed {}", speedRatio);
      }
    }

    return ops.buildRequests(new SpokenLine(apiKey, spokenText, style, voice, speedRatio), request);
  }

  private Pcm runBuffered(PreparedSpeech prepared) {
    for (int attempt = 1; attempt <= MAX_SPEECH_ATTEMPTS; attempt++) {
      long attemptStart = System.nanoTime();
      long backoffGeneration = backoff.generation();
      try (Response response = ops.newCall(prepared.buffered, prepared.inputLen).execute()) {
        ResponseBody body = response.body();
        byte[] bytes = body == null ? CloudHttp.EMPTY_BODY : body.bytes();
        String contentType = CloudHttp.headerOrEmpty(response, "Content-Type");
        String generationId = ops.generationId(response);
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);

        if (!response.isSuccessful()) {
          if (response.code() == CloudHttp.HTTP_TOO_MANY_REQUESTS) {
            backoff.recordRateLimited(statedWait(response, bytes), backoffGeneration);
          }
          support.warnOnce(ops.failureNotice(response.code(), bytes));
          support.logFailure(
              "non-2xx",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        backoff.recordSuccess();
        DecodedSpeech decoded = ops.decodeBuffered(bytes, prepared);
        if (decoded.audioBytes == 0) {
          support.logFailure(
              "empty-body",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("empty-body", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(ops.emptyBodyNotice());
          return null;
        }
        if (decoded.pcm == null) {
          support.warnOnce(
              providerName
                  + " TTS returned audio that could not be decoded; this line was not voiced.");
          support.logFailure(
              "undecodable",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        if (PcmCompleteness.isTruncated(decoded.pcm, prepared.speedRatio)) {
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("truncated", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(
              providerName + " TTS returned a truncated line; this line was not voiced.");
          support.logFailure(
              "truncated",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        if (config.debugMode()) {
          log.info(
              CloudSynthTrace.success(
                  attempt,
                  MAX_SPEECH_ATTEMPTS,
                  elapsedMs,
                  prepared.inputLen,
                  decoded.audioBytes,
                  generationId));
        }
        decoded.bankSpend.run();
        return decoded.pcm;
      } catch (ConnectException e) {
        support.warnOnce(networkNotice());
        support.logNetworkFailure(
            "connect", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      } catch (IOException e) {
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (attempt < MAX_SPEECH_ATTEMPTS) {
          log.debug(CloudSynthTrace.retry("network", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
          support.backoffBeforeNetworkRetry(attempt);
          continue;
        }
        support.warnOnce(networkNotice());
        support.logNetworkFailure("network", attempt, elapsedMs, prepared.inputLen, e);
        return null;
      } catch (RuntimeException e) {
        support.warnOnce(
            providerName + " TTS request failed unexpectedly; this line was not voiced.");
        support.logNetworkFailure(
            "unexpected", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      }
    }
    return null;
  }

  private Pcm runStreaming(PreparedSpeech prepared, PcmSink sink) {
    int rate = model.sampleRate();
    for (int attempt = 1; attempt <= MAX_SPEECH_ATTEMPTS; attempt++) {
      long attemptStart = System.nanoTime();
      StreamDrain drain = ops.newStreamDrain();
      Accumulator acc = new Accumulator(prepared, sink, rate, attemptStart);
      long backoffGeneration = backoff.generation();
      try (Response response = ops.newCall(prepared.streaming, prepared.inputLen).execute()) {
        String contentType = CloudHttp.headerOrEmpty(response, "Content-Type");
        String generationId = ops.generationId(response);
        if (!response.isSuccessful()) {
          byte[] bytes = CloudHttp.errorBody(response);
          if (response.code() == CloudHttp.HTTP_TOO_MANY_REQUESTS) {
            backoff.recordRateLimited(statedWait(response, bytes), backoffGeneration);
          }
          support.warnOnce(ops.failureNotice(response.code(), bytes));
          support.logFailure(
              "non-2xx",
              attempt,
              CloudHttp.elapsedMs(attemptStart),
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              bytes);
          return null;
        }
        backoff.recordSuccess();
        ResponseBody body = response.body();
        if (body != null) {
          drain.drain(body, acc);
        }
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (acc.totalBytes == 0) {
          support.logFailure(
              "empty-body",
              attempt,
              elapsedMs,
              prepared.inputLen,
              response.code(),
              response.message(),
              contentType,
              generationId,
              CloudHttp.EMPTY_BODY);
          if (attempt < MAX_SPEECH_ATTEMPTS) {
            log.debug(CloudSynthTrace.retry("empty-body", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
            continue;
          }
          support.warnOnce(ops.emptyBodyNotice());
          return null;
        }
        drain.bankSpend(prepared);
        if (config.debugMode()) {
          log.info(
              "{} firstChunkMs={}",
              CloudSynthTrace.success(
                  attempt,
                  MAX_SPEECH_ATTEMPTS,
                  elapsedMs,
                  prepared.inputLen,
                  (int) acc.totalBytes,
                  generationId),
              acc.firstChunkMs);
        }
        Pcm pcm = new Pcm(flatten(acc.chunks, acc.sampleCount), rate);
        if (!drain.finishedCleanly()
            || acc.decoder.hasPendingByte()
            || PcmCompleteness.isTruncated(pcm, prepared.speedRatio)) {
          log.debug("[TTS cloud] streamed line played but not cached (incomplete tail)");
          return null;
        }
        return pcm;
      } catch (ConnectException e) {
        support.warnOnce(networkNotice());
        support.logNetworkFailure(
            "connect", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      } catch (IOException e) {
        long elapsedMs = CloudHttp.elapsedMs(attemptStart);
        if (!acc.fedSink && attempt < MAX_SPEECH_ATTEMPTS) {
          log.debug(CloudSynthTrace.retry("network", attempt, MAX_SPEECH_ATTEMPTS, elapsedMs));
          support.backoffBeforeNetworkRetry(attempt);
          continue;
        }
        support.warnOnce(networkNotice());
        support.logNetworkFailure("network", attempt, elapsedMs, prepared.inputLen, e);
        return null;
      } catch (RuntimeException e) {
        support.warnOnce(
            providerName + " TTS request failed unexpectedly; this line was not voiced.");
        support.logNetworkFailure(
            "unexpected", attempt, CloudHttp.elapsedMs(attemptStart), prepared.inputLen, e);
        return null;
      }
    }
    return null;
  }

  private long statedWait(Response response, byte[] body) {
    return Math.max(CloudHttp.retryAfterMillis(response), ops.statedWaitMillis(body));
  }

  private String networkNotice() {
    return providerName + " TTS request could not reach the network; this line was not voiced.";
  }

  private final class Accumulator implements ChunkSink {
    final StreamingPcmDecoder decoder = new StreamingPcmDecoder();
    final List<float[]> chunks = new ArrayList<>();
    int sampleCount;
    long totalBytes;
    boolean fedSink;
    long firstChunkMs = -1;

    private final PreparedSpeech prepared;
    private final PcmSink sink;
    private final int rate;
    private final long attemptStart;

    Accumulator(PreparedSpeech prepared, PcmSink sink, int rate, long attemptStart) {
      this.prepared = prepared;
      this.sink = sink;
      this.rate = rate;
      this.attemptStart = attemptStart;
    }

    @Override
    public void accept(byte[] bytes, int len) {
      totalBytes += len;
      float[] chunk = decoder.decode(bytes, len);
      if (chunk.length > 0) {
        sink.accept(chunk, rate);
        if (!fedSink) {
          firstChunkMs = CloudHttp.elapsedMs(attemptStart);
          ops.recordSpendOnFirstChunk(prepared);
        }
        fedSink = true;
        chunks.add(chunk);
        sampleCount += chunk.length;
      }
    }
  }

  private static float[] flatten(List<float[]> chunks, int totalSamples) {
    float[] out = new float[totalSamples];
    int pos = 0;
    for (float[] chunk : chunks) {
      System.arraycopy(chunk, 0, out, pos, chunk.length);
      pos += chunk.length;
    }
    return out;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class CloudTranslatorCall {

  public interface Ops {

    Request buildRequest(String text, String language, String apiKey);

    String extractText(String raw);
  }

  public static final class Outcome {
    public final String text;
    public final String raw;

    public Outcome(String text, String raw) {
      this.text = text;
      this.raw = raw;
    }
  }

  private CloudTranslatorCall() {}

  public static Outcome run(
      OkHttpClient httpClient,
      VoicedDialogueConfig config,
      Ops ops,
      String text,
      String language,
      String apiKey) {
    Request httpRequest = ops.buildRequest(text, language, apiKey);
    long start = System.nanoTime();
    try (Response response = httpClient.newCall(httpRequest).execute()) {
      ResponseBody body = response.body();
      String raw = body == null ? "" : body.string();
      long elapsedMs = CloudHttp.elapsedMs(start);
      if (!response.isSuccessful()) {
        log.warn(
            "[TTS cloud] translate fail reason=non-2xx http={} elapsedMs={} inLen={} detail={}",
            response.code(),
            elapsedMs,
            text.length(),
            response.message());
        return null;
      }
      String translated = ops.extractText(raw);
      if (translated == null || translated.isEmpty()) {
        log.warn(
            "[TTS cloud] translate fail reason=no-content http={} elapsedMs={} inLen={}",
            response.code(),
            elapsedMs,
            text.length());
        return null;
      }
      if (config.debugMode()) {
        log.info(
            "[TTS cloud] translate ok lang={} elapsedMs={} inLen={} outLen={} -> \"{}\"",
            language,
            elapsedMs,
            text.length(),
            translated.length(),
            translated);
      }
      return new Outcome(translated, raw);
    } catch (IOException | RuntimeException e) {
      log.warn(
          "[TTS cloud] translate fail reason=error elapsedMs={} inLen={} detail={}",
          CloudHttp.elapsedMs(start),
          text.length(),
          e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;

public final class CloudTtsText {

  static final String DEFAULT_LANGUAGE = "English";

  private CloudTtsText() {}

  static boolean needsTranslation(String language) {
    return language != null
        && !language.trim().isEmpty()
        && !language.trim().equalsIgnoreCase(DEFAULT_LANGUAGE);
  }

  static String effectiveSpokenLanguage(VoicedDialogueConfig config, SynthesisRequest request) {
    return combineLanguage(config.cloudLanguage().label(), styleFor(config, request));
  }

  static String languageCacheToken(VoicedDialogueConfig config, SynthesisRequest request) {
    if (request.skipTranslation() || !needsTranslation(effectiveSpokenLanguage(config, request))) {
      return null;
    }
    VoicedDialogueConfig.SpeakingStyle style = styleFor(config, request);
    String language = config.cloudLanguage().name();
    return style.isNone() ? language : language + "+" + style.name();
  }

  private static VoicedDialogueConfig.SpeakingStyle styleFor(
      VoicedDialogueConfig config, SynthesisRequest request) {
    if (request.voice().narrator()) {
      return VoicedDialogueConfig.SpeakingStyle.NONE;
    }
    return request.player() ? config.cloudPlayerSpeakingStyle() : config.cloudNpcSpeakingStyle();
  }

  static String spokenLanguage(VoicedDialogueConfig config) {
    return baseLanguage(config.cloudLanguage().label());
  }

  private static String baseLanguage(String language) {
    return language == null || language.trim().isEmpty() ? DEFAULT_LANGUAGE : language.trim();
  }

  static String combineLanguage(String language, VoicedDialogueConfig.SpeakingStyle quirk) {
    String base = baseLanguage(language);
    if (quirk == null || quirk.isNone()) {
      return base;
    }
    return base + " " + quirk.phrase();
  }

  public static String translatorSystemPrompt(String language) {
    return "You are a translation engine for an Old School RuneScape dialogue voice plugin."
        + " Translate the user's line into "
        + language
        + ". Preserve proper nouns, character names, place names, item names, and RuneScape"
        + " terminology exactly as written. Output only the translation, with no quotes, notes,"
        + " explanations, or preamble.";
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import com.grahambartley.runelite.voiced.dialogue.audio.AudioOutput;
import com.grahambartley.runelite.voiced.dialogue.audio.CaveEcho;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.cache.DiskAudioCache;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache.CacheKey;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class DialogueAudioService {

  private static final CompletableFuture<Void> NOTHING_PLAYING =
      CompletableFuture.completedFuture(null);

  private static final int SYNTH_THREADS = 2;

  private static final int PREFETCH_THREADS = 2;

  private static final int PREFETCH_QUEUE_CAPACITY = 16;

  private static final int SHUTDOWN_WAIT_SECONDS = 2;

  private static final int AMBIENT_SYNTH_THREADS = 6;

  private static final int AMBIENT_PLAYBACK_KEEPALIVE_SECONDS = 30;

  private final BackendProvider backends;
  private final AudioOutput output;
  private final Executor executor;
  private final Executor warmExecutor;
  private final Executor prefetchExecutor;
  private final TieredSynthesisCache cache;
  private final IntSupplier volume;
  private final Supplier<AudioOutput> ambientOutputs;
  private final Executor ambientExecutor;
  private final Executor ambientPlaybackExecutor;
  private final Set<AmbientLine> ambientLines = ConcurrentHashMap.newKeySet();
  private final Map<Integer, CompletableFuture<Void>> ambientChains = new ConcurrentHashMap<>();
  private final AtomicLong epoch = new AtomicLong();

  private volatile boolean closed;
  private final AtomicLong prefetchEpoch = new AtomicLong();
  private final AtomicLong ambientEpoch = new AtomicLong();

  public DialogueAudioService(
      BackendProvider backends,
      AudioOutput output,
      Supplier<AudioOutput> ambientOutputs,
      DiskAudioCache diskCache,
      int cacheSize,
      int queueCapacity,
      IntSupplier volume) {
    this(
        backends,
        output,
        ambientOutputs,
        new TieredSynthesisCache(cacheSize, diskCache),
        buildExecutor(queueCapacity),
        buildWarmExecutor(),
        buildPrefetchExecutor(),
        buildAmbientExecutor(),
        buildAmbientPlaybackExecutor(),
        volume);
  }

  DialogueAudioService(
      BackendProvider backends,
      AudioOutput output,
      Supplier<AudioOutput> ambientOutputs,
      TieredSynthesisCache cache,
      Executor executor,
      Executor warmExecutor,
      Executor prefetchExecutor,
      Executor ambientExecutor,
      Executor ambientPlaybackExecutor,
      IntSupplier volume) {
    this.backends = backends;
    this.output = output;
    this.ambientOutputs = ambientOutputs;
    this.cache = cache;
    this.executor = executor;
    this.warmExecutor = warmExecutor;
    this.prefetchExecutor = prefetchExecutor;
    this.ambientExecutor = ambientExecutor;
    this.ambientPlaybackExecutor = ambientPlaybackExecutor;
    this.volume = volume;
  }

  public void prewarm(Runnable warm) {
    submitQuietly(
        warmExecutor,
        () -> {
          if (!closed) {
            warm.run();
          }
        });
  }

  public void speak(SynthesisRequest request) {
    speak(request, false);
  }

  public void speak(SynthesisRequest request, boolean applyEcho) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    long mine = epoch.incrementAndGet();
    output.stop();
    cutAmbient();
    SynthesisBackend backend = backends.active();
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    submitQuietly(executor, () -> run(mine, backend, effective, key, applyEcho));
  }

  public void speakAmbient(
      SynthesisRequest request, boolean applyEcho, int speakerId, IntSupplier distanceVolume) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    SynthesisBackend backend = backends.active();
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    long node = ambientEpoch.get();
    AmbientLine line = new AmbientLine(distanceVolume);
    ambientLines.add(line);
    try {
      queueAmbientPlayback(
          speakerId,
          CompletableFuture.supplyAsync(
              () -> synthesizeAmbient(node, backend, effective, key, applyEcho), ambientExecutor),
          node,
          line);
    } catch (RejectedExecutionException closing) {
      ambientLines.remove(line);
    }
  }

  private Pcm synthesizeAmbient(
      long node,
      SynthesisBackend backend,
      SynthesisRequest request,
      CacheKey key,
      boolean applyEcho) {
    if (ambientEpoch.get() != node) {
      return null;
    }
    Pcm cached = cache.lookup(key);
    if (cached == null && backend.isThrottled()) {
      return null;
    }
    Pcm pcm = cached != null ? cached : synthesizeDeduped(backend, request, key);
    if (pcm == null) {
      return null;
    }
    return applyEcho ? CaveEcho.apply(pcm) : pcm;
  }

  private void queueAmbientPlayback(
      int speakerId, CompletableFuture<Pcm> synthesis, long node, AmbientLine line) {
    CompletableFuture<Pcm> rendered = synthesis.handle((pcm, error) -> pcm);
    CompletableFuture<Void> queued =
        ambientChains.compute(
            speakerId,
            (id, playing) ->
                (playing == null ? NOTHING_PLAYING : playing)
                    .handle((ignored, error) -> (Void) null)
                    .thenCombine(rendered, (ignored, pcm) -> pcm)
                    .thenAcceptAsync(
                        pcm -> {
                          if (pcm != null && ambientEpoch.get() == node) {
                            playAmbient(node, pcm, line);
                          }
                        },
                        ambientPlaybackExecutor));
    queued.whenComplete(
        (ignored, error) -> {
          ambientLines.remove(line);
          ambientChains.remove(speakerId, queued);
        });
  }

  private void playAmbient(long node, Pcm pcm, AmbientLine line) {
    int openingVolume = line.volumePercent.get();
    if (cutRequested(openingVolume)) {
      return;
    }
    AudioOutput ambient = ambientOutputs.get();
    line.output = ambient;
    try {
      if (ambientEpoch.get() == node) {
        ambient.stream(pcm.getSamples(), pcm.getSampleRate(), openingVolume);
      }
    } finally {
      line.output = null;
      ambient.close();
    }
  }

  public void refreshAmbientVolumes() {
    if (ambientLines.isEmpty()) {
      return;
    }
    for (AmbientLine line : ambientLines) {
      int volumePercent = line.distanceVolume.getAsInt();
      line.volumePercent.set(volumePercent);
      AudioOutput sounding = line.output;
      if (sounding == null) {
        continue;
      }
      if (cutRequested(volumePercent)) {
        sounding.stop();
        continue;
      }
      sounding.setVolume(volumePercent);
    }
  }

  private static boolean cutRequested(int volumePercent) {
    return volumePercent < 0;
  }

  private void cutAmbient() {
    ambientEpoch.incrementAndGet();
    if (ambientLines.isEmpty()) {
      return;
    }
    submitQuietly(ambientPlaybackExecutor, this::stopLiveAmbient);
  }

  private void stopLiveAmbient() {
    for (AmbientLine line : ambientLines) {
      AudioOutput sounding = line.output;
      if (sounding != null) {
        sounding.stop();
      }
    }
  }

  private static final class AmbientLine {
    private final IntSupplier distanceVolume;
    private final AtomicInteger volumePercent;
    private volatile AudioOutput output;

    private AmbientLine(IntSupplier distanceVolume) {
      this.distanceVolume = distanceVolume;
      this.volumePercent = new AtomicInteger(distanceVolume.getAsInt());
    }
  }

  public void prefetch(SynthesisRequest request) {
    if (request == null || request.text() == null || request.text().isEmpty()) {
      return;
    }
    SynthesisBackend backend = backends.active();
    if (!backend.isAvailable() || backend.isThrottled()) {
      return;
    }
    SynthesisRequest effective = BackendProvider.downgradeFor(backend, request);
    CacheKey key = keyFor(backend, effective);
    if (cache.memoryHit(key) != null) {
      return;
    }
    long node = prefetchEpoch.get();
    submitQuietly(
        prefetchExecutor,
        () -> {
          if (prefetchEpoch.get() != node || backend.isThrottled() || cache.lookup(key) != null) {
            return;
          }
          log.debug(
              "[TTS synth] prefetch ({}/{}) \"{}\"",
              key.namespace(),
              key.voiceKey(),
              key.textPreview());
          synthesizeDeduped(backend, effective, key);
        });
  }

  public void cancelPrefetch() {
    prefetchEpoch.incrementAndGet();
  }

  private CacheKey keyFor(SynthesisBackend backend, SynthesisRequest effective) {
    String variant = backend.cacheVariant(effective);
    String voiceKey = variant.isEmpty() ? effective.voice().key() : variant;
    return new CacheKey(backend.cacheNamespace(), voiceKey, effective.emotion(), effective.text());
  }

  public void cutPlayback() {
    epoch.incrementAndGet();
    output.stop();
  }

  public void close() {
    closed = true;
    epoch.incrementAndGet();
    prefetchEpoch.incrementAndGet();
    output.stop();
    ambientEpoch.incrementAndGet();
    stopLiveAmbient();
    ambientChains.clear();
    ambientLines.clear();
    stopAccepting(ambientExecutor);
    stopAccepting(ambientPlaybackExecutor);
    stopAndAwait(executor);
    if (warmExecutor != executor) {
      stopAndAwait(warmExecutor);
    }
    if (prefetchExecutor != executor && prefetchExecutor != warmExecutor) {
      stopAndAwait(prefetchExecutor);
    }
    output.close();
  }

  private static void stopAccepting(Executor exec) {
    if (exec instanceof ExecutorService) {
      ((ExecutorService) exec).shutdown();
    }
  }

  private static void stopAndAwait(Executor exec) {
    if (exec instanceof ExecutorService) {
      ExecutorService es = (ExecutorService) exec;
      es.shutdown();
      try {
        if (!es.awaitTermination(SHUTDOWN_WAIT_SECONDS, TimeUnit.SECONDS)) {
          log.debug("A worker was still running after {}s, leaving it be", SHUTDOWN_WAIT_SECONDS);
        }
      } catch (InterruptedException e) {
        log.debug("Interrupted while awaiting executor shutdown");
      }
    }
  }

  private void run(
      long mine,
      SynthesisBackend backend,
      SynthesisRequest request,
      CacheKey key,
      boolean applyEcho) {
    if (epoch.get() != mine) {
      return;
    }
    Pcm pcm = cache.lookup(key);
    if (pcm != null) {
      playBuffered(mine, pcm, applyEcho);
      return;
    }
    if (!applyEcho) {
      runStreaming(mine, backend, request, key);
      return;
    }
    pcm = synthesizeDeduped(backend, request, key);
    if (pcm == null) {
      return;
    }
    playBuffered(mine, pcm, applyEcho);
  }

  private void playBuffered(long mine, Pcm pcm, boolean applyEcho) {
    if (epoch.get() != mine) {
      return;
    }
    Pcm toPlay = applyEcho ? CaveEcho.apply(pcm) : pcm;
    output.stream(toPlay.getSamples(), toPlay.getSampleRate(), volume.getAsInt());
  }

  void runStreaming(long mine, SynthesisBackend backend, SynthesisRequest request, CacheKey key) {
    if (epoch.get() != mine) {
      synthesizeDeduped(backend, request, key);
      return;
    }
    AtomicBoolean deduped = new AtomicBoolean();
    Pcm pcm =
        cache.withInFlight(
            key,
            () -> {
              AudioOutput.AudioStream stream = output.beginStream(volume.getAsInt());
              try {
                PcmSink sink = stream::write;
                return backends.synthesizeStreamingWith(backend, request, sink);
              } finally {
                stream.end();
              }
            },
            () -> deduped.set(true));
    if (deduped.get() && pcm != null) {
      playBuffered(mine, pcm, false);
    }
  }

  private Pcm synthesizeDeduped(SynthesisBackend backend, SynthesisRequest request, CacheKey key) {
    return cache.withInFlight(
        key,
        () -> {
          long start = System.nanoTime();
          Pcm pcm = backends.synthesizeWith(backend, request);
          log.debug(
              "[TTS synth] backend={} ok={} synthMs={} ({}/{}) \"{}\"",
              backend.id(),
              pcm != null,
              elapsedMs(start),
              key.namespace(),
              key.voiceKey(),
              key.textPreview());
          return pcm;
        },
        () ->
            log.debug(
                "[TTS synth] dedup reuse ({}/{}) \"{}\"",
                key.namespace(),
                key.voiceKey(),
                key.textPreview()));
  }

  private static void submitQuietly(Executor exec, Runnable task) {
    try {
      exec.execute(task);
    } catch (RejectedExecutionException ignored) {
    }
  }

  private static ThreadFactory daemonThreadFactory(String name) {
    return r -> {
      Thread t = new Thread(r, name);
      t.setDaemon(true);
      return t;
    };
  }

  private static ExecutorService buildExecutor(int queueCapacity) {
    return new ThreadPoolExecutor(
        SYNTH_THREADS,
        SYNTH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(queueCapacity),
        daemonThreadFactory("dialogue-audio"),
        (r, exec) -> {
          log.debug("[TTS synth] queue saturated; dropping oldest queued line");
          new ThreadPoolExecutor.DiscardOldestPolicy().rejectedExecution(r, exec);
        });
  }

  private static ExecutorService buildWarmExecutor() {
    return new ThreadPoolExecutor(
        1,
        1,
        0L,
        TimeUnit.MILLISECONDS,
        new LinkedBlockingQueue<>(),
        daemonThreadFactory("dialogue-warm"));
  }

  private static ExecutorService buildAmbientExecutor() {
    return new ThreadPoolExecutor(
        AMBIENT_SYNTH_THREADS,
        AMBIENT_SYNTH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new LinkedBlockingQueue<>(),
        daemonThreadFactory("dialogue-ambient"));
  }

  private static ExecutorService buildAmbientPlaybackExecutor() {
    return new ThreadPoolExecutor(
        0,
        Integer.MAX_VALUE,
        AMBIENT_PLAYBACK_KEEPALIVE_SECONDS,
        TimeUnit.SECONDS,
        new SynchronousQueue<>(),
        daemonThreadFactory("dialogue-ambient-play"));
  }

  private static ExecutorService buildPrefetchExecutor() {
    return new ThreadPoolExecutor(
        PREFETCH_THREADS,
        PREFETCH_THREADS,
        0L,
        TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(PREFETCH_QUEUE_CAPACITY),
        daemonThreadFactory("dialogue-prefetch"),
        new ThreadPoolExecutor.DiscardOldestPolicy());
  }

  private static long elapsedMs(long startNanos) {
    return (System.nanoTime() - startNanos) / 1_000_000L;
  }
}

