package com.grahambartley.runelite.voiced.dialogue.speech.model;

import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.Map;

public final class GeminiVoiceMap {

  static final String DEFAULT_VOICE = "Charon";

  static final String DEFAULT_CHILD_VOICE = "Puck";

  static final String FALLBACK_NARRATOR_VOICE = "Callirrhoe";

  static final int PLAYER_SEED = 0;

  private final Map<NpcRace, Map<NpcGender, String[]>> npcVoices;
  private final Map<NpcGender, String[]> playerVoices;
  private final Map<NpcGender, String[]> childVoices;
  private final GeminiVoiceRegions regions;

  public GeminiVoiceMap() {
    this(GeminiVoiceRegions.bundled());
  }

  GeminiVoiceMap(GeminiVoiceRegions regions) {
    this.regions = regions;
    playerVoices = new EnumMap<>(NpcGender.class);
    playerVoices.put(NpcGender.MALE, new String[] {"Achird", "Iapetus"});
    playerVoices.put(NpcGender.FEMALE, new String[] {"Aoede", "Autonoe"});

    childVoices = new EnumMap<>(NpcGender.class);
    childVoices.put(NpcGender.MALE, new String[] {"Puck"});
    childVoices.put(NpcGender.FEMALE, new String[] {"Leda", "Zephyr"});

    npcVoices = new EnumMap<>(NpcRace.class);
    put(NpcRace.HUMAN, male("Charon", "Iapetus"), female("Despina", "Erinome"));
    put(NpcRace.ELF, male("Iapetus", "Rasalgethi"), female("Vindemiatrix", "Erinome"));
    put(NpcRace.DWARF, male("Algenib", "Alnilam"), female("Gacrux", "Kore"));
    put(NpcRace.GOBLIN, male("Puck", "Zubenelgenubi"), female("Leda", "Laomedeia"));
    put(NpcRace.MONKEY, male("Fenrir", "Sadachbia"), female("Zephyr", "Pulcherrima"));
    put(NpcRace.GORILLA, male("Algenib", "Orus"), female("Gacrux", "Kore"));
    put(NpcRace.TROLL, male("Algenib", "Orus"), female("Gacrux", "Kore"));
    put(NpcRace.UNDEAD, male("Enceladus", "Schedar"), female("Achernar", "Sulafat"));
    put(NpcRace.DEMON, male("Algenib", "Rasalgethi"), female("Gacrux", "Despina"));
    put(NpcRace.WIZARD, male("Sadaltager", "Charon"), female("Sulafat", "Vindemiatrix"));
    put(NpcRace.TORTUGAN, male("Achird"), female("Sulafat", "Vindemiatrix"));

    put(NpcRace.ICYENE, male("Alnilam", "Schedar"), female("Kore", "Despina"));
    put(NpcRace.ARCEUUS, male("Iapetus", "Rasalgethi"), female("Vindemiatrix", "Erinome"));
    put(NpcRace.ARANEI, male("Enceladus", "Iapetus"), female("Achernar", "Erinome"));
    put(NpcRace.DOG, male("Fenrir", "Orus"), female("Pulcherrima", "Gacrux"));
    put(NpcRace.CRAB, male("Zubenelgenubi", "Sadachbia"), female("Pulcherrima", "Laomedeia"));
    put(NpcRace.PENGUIN, male("Puck", "Zubenelgenubi"), female("Zephyr", "Laomedeia"));
  }

  private static String[] male(String... voices) {
    return voices;
  }

  private static String[] female(String... voices) {
    return voices;
  }

  private void put(NpcRace race, String[] maleVoices, String[] femaleVoices) {
    Map<NpcGender, String[]> byGender = new EnumMap<>(NpcGender.class);
    byGender.put(NpcGender.MALE, maleVoices);
    byGender.put(NpcGender.FEMALE, femaleVoices);
    npcVoices.put(race, byGender);
  }

  public String voiceFor(VoiceSpec spec, CharacterProfile profile) {
    if (spec == null) {
      return DEFAULT_VOICE;
    }
    if (spec.narrator()) {
      String narrator = regions.narratorVoice();
      return narrator != null ? narrator : FALLBACK_NARRATOR_VOICE;
    }
    NpcGender gender = normalizeGender(spec.gender());
    String region = regionFor(spec, profile);
    if (spec.player()) {
      String regional = regions.playerVoiceFor(region, gender, PLAYER_SEED);
      return regional != null ? regional : anchor(playerVoices.get(gender));
    }
    if (spec.child()) {
      String regional = regions.childVoiceFor(region, gender, spec.voiceSeed());
      if (regional != null) {
        return regional;
      }
      String[] pool = childVoices.get(gender);
      return (pool == null || pool.length == 0) ? DEFAULT_CHILD_VOICE : pick(pool, spec);
    }
    String regional =
        regions.voiceFor(region, gender, spec.voiceSeed(), profile == null ? null : profile.age());
    if (regional != null) {
      return regional;
    }
    Map<NpcGender, String[]> byGender = npcVoices.get(spec.race());
    if (byGender == null) {
      return pick(playerVoices.get(gender), spec);
    }
    return pick(byGender.get(gender), spec);
  }

  public String regionFor(VoiceSpec spec, CharacterProfile profile) {
    if (spec == null || spec.narrator()) {
      return null;
    }
    if (spec.player()) {
      return regions.regionForAccent(profile == null ? null : profile.accent());
    }
    return npcRegion(spec, profile);
  }

  private String npcRegion(VoiceSpec spec, CharacterProfile profile) {
    if (profile == null || !spec.hasVoiceSeed()) {
      return null;
    }
    if (profile.accentOverridden()) {
      String matched = regions.regionForAccent(profile.accent());
      if (matched != null) {
        return matched;
      }
    }
    return profile.voiceRegion();
  }

  private static String anchor(String[] pool) {
    return (pool == null || pool.length == 0) ? DEFAULT_VOICE : pool[0];
  }

  private static String pick(String[] pool, VoiceSpec spec) {
    if (pool == null || pool.length == 0) {
      return DEFAULT_VOICE;
    }
    if (!spec.hasVoiceSeed()) {
      return pool[0];
    }
    return GeminiVoiceRegions.pick(Arrays.asList(pool), spec.voiceSeed());
  }

  private static NpcGender normalizeGender(NpcGender gender) {
    return gender == NpcGender.FEMALE ? NpcGender.FEMALE : NpcGender.MALE;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.model;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class GeminiVoiceRegions {

  static final String RESOURCE = "/voice-regions.json";

  static final String REGIONS_KEY = "regions";

  static final String NARRATOR_KEY = "narratorVoice";

  static final String PLAYER_KEYWORDS_KEY = "playerKeywords";

  static final String VOICE_AGES_KEY = "voiceAges";

  static final int AGE_WINDOW = 10;

  static final int MIN_AGE_MATCHES = 3;

  private static final long HASH_MULTIPLIER = 0x9E3779B97F4A7C15L;

  private static final long UNSIGNED_INT_MASK = 0xFFFFFFFFL;

  private static final int SEED_SHIFT = 32;

  private static final int FIRST_MIX_SHIFT = 31;

  private static final int SECOND_MIX_SHIFT = 29;

  static final String CHILD_POOL_PREFIX = "CHILD_";

  static final String PLAYER_VOICE_PREFIX = "PLAYER_";

  private static final NpcGender[] VOICED_GENDERS = {NpcGender.MALE, NpcGender.FEMALE};

  private final Map<String, Map<NpcGender, List<String>>> pools = new LinkedHashMap<>();
  private final Map<String, Map<NpcGender, List<String>>> childPools = new LinkedHashMap<>();
  private final Map<String, Map<NpcGender, String>> playerVoices = new LinkedHashMap<>();
  private final Map<String, List<Pattern>> playerKeywords = new LinkedHashMap<>();
  private final Map<String, Integer> voiceAges;
  private final String narratorVoice;

  GeminiVoiceRegions(JsonObject regions) {
    this(regions, null);
  }

  GeminiVoiceRegions(JsonObject regions, String narratorVoice) {
    this(regions, narratorVoice, Collections.emptyMap());
  }

  GeminiVoiceRegions(JsonObject regions, String narratorVoice, Map<String, Integer> voiceAges) {
    this.narratorVoice = narratorVoice;
    this.voiceAges = voiceAges;
    for (Map.Entry<String, JsonElement> entry : regions.entrySet()) {
      if (!entry.getValue().isJsonObject()) {
        continue;
      }
      JsonObject region = entry.getValue().getAsJsonObject();
      Map<NpcGender, List<String>> byGender = new EnumMap<>(NpcGender.class);
      Map<NpcGender, List<String>> childByGender = new EnumMap<>(NpcGender.class);
      Map<NpcGender, String> playerByGender = new EnumMap<>(NpcGender.class);
      for (NpcGender gender : VOICED_GENDERS) {
        byGender.put(gender, strings(region, gender.name()));
        childByGender.put(gender, strings(region, CHILD_POOL_PREFIX + gender.name()));
        String playerKey = PLAYER_VOICE_PREFIX + gender.name();
        if (region.has(playerKey)) {
          playerByGender.put(gender, region.get(playerKey).getAsString());
        }
      }
      pools.put(entry.getKey(), byGender);
      childPools.put(entry.getKey(), childByGender);
      playerVoices.put(entry.getKey(), playerByGender);
      List<Pattern> keywords = new ArrayList<>();
      for (String keyword : strings(region, PLAYER_KEYWORDS_KEY)) {
        keywords.add(
            Pattern.compile("\\b" + Pattern.quote(keyword.toLowerCase(Locale.ROOT)) + "\\b"));
      }
      playerKeywords.put(entry.getKey(), keywords);
    }
  }

  static GeminiVoiceRegions bundled() {
    return Bundled.INSTANCE;
  }

  String narratorVoice() {
    return narratorVoice;
  }

  String voiceFor(String region, NpcGender gender, int seed) {
    return voiceFor(region, gender, seed, null);
  }

  String voiceFor(String region, NpcGender gender, int seed, Integer age) {
    List<String> pool = pool(pools, region, gender);
    return pick(age == null ? pool : closestInAge(pool, age), seed);
  }

  private List<String> closestInAge(List<String> pool, int age) {
    if (pool == null) {
      return null;
    }
    List<String> aged =
        pool.stream()
            .filter(voiceAges::containsKey)
            .sorted(
                Comparator.<String>comparingInt(voice -> ageGap(voice, age))
                    .thenComparing(Comparator.naturalOrder()))
            .collect(Collectors.toList());
    if (aged.isEmpty()) {
      return pool;
    }
    List<String> matches = new ArrayList<>();
    for (String voice : aged) {
      if (matches.size() >= MIN_AGE_MATCHES && ageGap(voice, age) > AGE_WINDOW) {
        break;
      }
      matches.add(voice);
    }
    return matches;
  }

  private int ageGap(String voice, int age) {
    return Math.abs(voiceAges.get(voice) - age);
  }

  String playerVoiceFor(String region, NpcGender gender, int seed) {
    Map<NpcGender, String> pinned = region == null ? null : playerVoices.get(region);
    String voice = pinned == null ? null : pinned.get(gender);
    return voice != null ? voice : voiceFor(region, gender, seed);
  }

  String childVoiceFor(String region, NpcGender gender, int seed) {
    return pick(pool(childPools, region, gender), seed);
  }

  private static List<String> pool(
      Map<String, Map<NpcGender, List<String>>> source, String region, NpcGender gender) {
    Map<NpcGender, List<String>> byGender = region == null ? null : source.get(region);
    return byGender == null ? null : byGender.get(gender);
  }

  static String pick(List<String> pool, int seed) {
    if (pool == null || pool.isEmpty()) {
      return null;
    }
    String chosen = null;
    long best = Long.MIN_VALUE;
    for (String voice : pool) {
      long weight = weight(seed, voice);
      if (chosen == null || weight > best) {
        best = weight;
        chosen = voice;
      }
    }
    return chosen;
  }

  String regionForAccent(String accent) {
    if (accent == null) {
      return null;
    }
    String lower = accent.toLowerCase(Locale.ROOT);
    for (Map.Entry<String, List<Pattern>> entry : playerKeywords.entrySet()) {
      for (Pattern keyword : entry.getValue()) {
        if (keyword.matcher(lower).find()) {
          return entry.getKey();
        }
      }
    }
    return null;
  }

  private static long weight(int seed, String voice) {
    long mixed = (((long) seed) << SEED_SHIFT) ^ (voice.hashCode() & UNSIGNED_INT_MASK);
    mixed *= HASH_MULTIPLIER;
    mixed ^= mixed >>> FIRST_MIX_SHIFT;
    mixed *= HASH_MULTIPLIER;
    return mixed ^ (mixed >>> SECOND_MIX_SHIFT);
  }

  private static List<String> strings(JsonObject object, String key) {
    if (!object.has(key) || !object.get(key).isJsonArray()) {
      return Collections.emptyList();
    }
    List<String> values = new ArrayList<>();
    JsonArray array = object.getAsJsonArray(key);
    for (JsonElement element : array) {
      values.add(element.getAsString());
    }
    return Collections.unmodifiableList(values);
  }

  static Map<String, Integer> ages(JsonObject root) {
    if (!root.has(VOICE_AGES_KEY) || !root.get(VOICE_AGES_KEY).isJsonObject()) {
      return Collections.emptyMap();
    }
    Map<String, Integer> ages = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject(VOICE_AGES_KEY).entrySet()) {
      JsonElement value = entry.getValue();
      if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber()) {
        ages.put(entry.getKey(), value.getAsInt());
      }
    }
    return Collections.unmodifiableMap(ages);
  }

  private static final class Bundled {
    static final GeminiVoiceRegions INSTANCE = load();

    private static GeminiVoiceRegions load() {
      try (InputStream stream = GeminiVoiceRegions.class.getResourceAsStream(RESOURCE)) {
        if (stream == null) {
          log.warn("Voice region table {} not found - every NPC keeps its race voice", RESOURCE);
          return new GeminiVoiceRegions(new JsonObject());
        }
        JsonObject root =
            new JsonParser()
                .parse(new InputStreamReader(stream, StandardCharsets.UTF_8))
                .getAsJsonObject();
        JsonObject regions =
            root.has(REGIONS_KEY) && root.get(REGIONS_KEY).isJsonObject()
                ? root.getAsJsonObject(REGIONS_KEY)
                : new JsonObject();
        String narrator = root.has(NARRATOR_KEY) ? root.get(NARRATOR_KEY).getAsString() : null;
        return new GeminiVoiceRegions(regions, narrator, ages(root));
      } catch (Exception e) {
        log.error("Failed to load voice region table {}: {}", RESOURCE, e.getMessage());
        return new GeminiVoiceRegions(new JsonObject());
      }
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

public final class OpenRouterCreditMeter {

  private Double baseline;

  private String baselineKey;

  public synchronized void recordBaseline(String apiKey, Double usage) {
    if (usage == null) {
      return;
    }
    if (baseline != null && sameKey(apiKey)) {
      return;
    }
    baseline = usage;
    baselineKey = apiKey == null ? null : apiKey.trim();
  }

  public synchronized Double spentSince(String apiKey, Double currentUsage) {
    if (baseline == null || currentUsage == null || !sameKey(apiKey)) {
      return null;
    }
    return Math.max(0, currentUsage - baseline);
  }

  public synchronized boolean hasBaselineFor(String apiKey) {
    return baseline != null && sameKey(apiKey);
  }

  public synchronized void reset() {
    baseline = null;
    baselineKey = null;
  }

  private boolean sameKey(String apiKey) {
    String trimmed = apiKey == null ? null : apiKey.trim();
    return baselineKey == null ? trimmed == null : baselineKey.equals(trimmed);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import okhttp3.Request;

final class OpenRouterProvider {

  static final String THROUGHPUT_SORT = "throughput";

  static final String GOOGLE_AI_STUDIO = "google-ai-studio";

  static final String APP_TITLE = "RuneLite Voiced Dialogue";

  static final String APP_URL = "https://github.com/grabartley/runelite-voiced-dialogue";

  private OpenRouterProvider() {}

  static void apply(JsonObject body) {
    apply(body, null);
  }

  static void apply(JsonObject body, JsonObject speechMetadata) {
    JsonObject provider = new JsonObject();
    provider.addProperty("sort", THROUGHPUT_SORT);
    if (speechMetadata != null) {
      JsonObject googleOptions = new JsonObject();
      googleOptions.add(GeminiTtsModel.SPEECH_METADATA, speechMetadata);
      JsonObject options = new JsonObject();
      options.add(GOOGLE_AI_STUDIO, googleOptions);
      provider.add("options", options);
    }
    body.add("provider", provider);
  }

  static Request.Builder attributedRequest(String url, String apiKey) {
    return new Request.Builder()
        .url(url)
        .addHeader("Authorization", "Bearer " + apiKey)
        .addHeader("User-Agent", CloudHttp.USER_AGENT)
        .addHeader("HTTP-Referer", APP_URL)
        .addHeader("X-Title", APP_TITLE);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTranslatorCall;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudTtsText;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTranslationModel;
import java.nio.charset.StandardCharsets;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

@Slf4j
final class OpenRouterTranslator implements CloudTranslatorCall.Ops {

  static final String MODEL = GeminiTranslationModel.MODEL_ID;

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;

  OpenRouterTranslator(
      OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson, String endpoint) {
    this.httpClient = httpClient;
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
  }

  String translate(String text, String language, String apiKey) {
    if (text == null || text.isEmpty()) {
      return text;
    }
    CloudTranslatorCall.Outcome outcome =
        CloudTranslatorCall.run(httpClient, config, this, text, language, apiKey);
    return outcome == null ? null : outcome.text;
  }

  @Override
  public Request buildRequest(String text, String language, String apiKey) {
    JsonObject payload = new JsonObject();
    payload.addProperty("model", MODEL);
    JsonArray messages = new JsonArray();
    messages.add(message("system", CloudTtsText.translatorSystemPrompt(language)));
    messages.add(message("user", text));
    payload.add("messages", messages);
    OpenRouterProvider.apply(payload);

    return OpenRouterProvider.attributedRequest(endpoint, apiKey)
        .post(
            RequestBody.create(
                CloudHttp.JSON_MEDIA_TYPE, gson.toJson(payload).getBytes(StandardCharsets.UTF_8)))
        .build();
  }

  private static JsonObject message(String role, String content) {
    JsonObject message = new JsonObject();
    message.addProperty("role", role);
    message.addProperty("content", content);
    return message;
  }

  @Override
  public String extractText(String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      JsonObject parsed = gson.fromJson(raw, JsonObject.class);
      if (parsed == null || !parsed.has("choices")) {
        return null;
      }
      JsonArray choices = parsed.getAsJsonArray("choices");
      if (choices.size() == 0) {
        return null;
      }
      JsonObject message = choices.get(0).getAsJsonObject().getAsJsonObject("message");
      if (message == null || !message.has("content")) {
        return null;
      }
      return message.get("content").getAsString().trim();
    } catch (RuntimeException e) {
      log.debug("[TTS cloud] translation response parse error: {}", e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.audio.PcmSink;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudBackendSupport;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudSpeechExecutor;
import com.grahambartley.runelite.voiced.dialogue.speech.RetryTuning;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisBackend;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker;
import java.io.IOException;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.EnumSet;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class OpenRouterTtsBackend implements SynthesisBackend {

  public static final String ID = "cloud-openrouter";

  private static final String API_BASE = "https://openrouter.ai/api/v1";
  private static final String SPEECH_PATH = "/audio/speech";
  private static final String CHAT_COMPLETIONS_PATH = "/chat/completions";

  private static final String KEY_PATH = "/key";

  private static final String PRODUCTION_ENDPOINT = API_BASE + SPEECH_PATH;

  private static final Duration CALL_BUDGET_BASE = Duration.ofSeconds(15);

  private static final long CALL_BUDGET_MILLIS_PER_CHAR = 75;

  private static final Duration KEEP_ALIVE = Duration.ofMinutes(15);

  static final int WARM_UP_CONNECTIONS = 2;

  private static final int STREAM_READ_BUFFER = 16_384;

  public static final String NO_KEY_NOTICE =
      "Add your OpenRouter API key in the Voiced Dialogue settings to hear dialogue; without a key,"
          + " lines are not voiced.";

  static final String OUT_OF_CREDITS_NOTICE =
      "Your OpenRouter account is out of credits, so dialogue cannot be voiced. Top up at"
          + " openrouter.ai/settings/credits.";

  private static final Callback WARM_UP_CALLBACK =
      new Callback() {
        @Override
        public void onFailure(Call call, IOException e) {
          log.debug("[TTS cloud] OpenRouter warm-up failed: {}", e.getMessage());
        }

        @Override
        public void onResponse(Call call, Response response) {
          try (ResponseBody body = response.body()) {
            if (body != null) {
              body.bytes();
            }
            log.debug("[TTS cloud] OpenRouter warm-up HTTP {}", response.code());
          } catch (IOException e) {
            log.debug("[TTS cloud] OpenRouter warm-up body read failed: {}", e.getMessage());
          }
        }
      };

  private final OkHttpClient httpClient;
  private final VoicedDialogueConfig config;
  private final Gson gson;
  private final String endpoint;
  private final String warmUpEndpoint;
  private final GeminiTtsModel model = new GeminiTtsModel();
  private final OpenRouterTranslator translator;

  private final Duration callTimeout;

  private final CloudBackendSupport support;

  private final CloudSpeechExecutor executor;

  public OpenRouterTtsBackend(OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson) {
    this(httpClient, config, gson, PRODUCTION_ENDPOINT);
  }

  OpenRouterTtsBackend(
      OkHttpClient httpClient, VoicedDialogueConfig config, Gson gson, String endpoint) {
    this(httpClient, config, gson, endpoint, RetryTuning.openRouter());
  }

  OpenRouterTtsBackend(
      OkHttpClient httpClient,
      VoicedDialogueConfig config,
      Gson gson,
      String endpoint,
      RetryTuning tuning) {
    this.httpClient = CloudHttp.deriveClient(httpClient, tuning, KEEP_ALIVE, true);
    this.callTimeout = tuning.callTimeout;
    this.support =
        new CloudBackendSupport(
            config,
            VoicedDialogueConfig.TtsProvider.OPENROUTER,
            CloudSpeechExecutor.MAX_SPEECH_ATTEMPTS,
            tuning);
    this.config = config;
    this.gson = gson;
    this.endpoint = endpoint;
    this.warmUpEndpoint = siblingEndpoint(endpoint, KEY_PATH);
    this.translator =
        new OpenRouterTranslator(
            this.httpClient, config, gson, siblingEndpoint(endpoint, CHAT_COMPLETIONS_PATH));
    this.executor = new CloudSpeechExecutor(config, support, model, "OpenRouter", new Ops());
  }

  private static String siblingEndpoint(String endpoint, String path) {
    return endpoint.contains(SPEECH_PATH) ? endpoint.replace(SPEECH_PATH, path) : API_BASE + path;
  }

  public void setNotice(Consumer<String> notice) {
    support.setNotice(notice);
  }

  public void setSpendTracker(SpendTracker spend) {
    support.setSpendTracker(spend);
  }

  @Override
  public String id() {
    return ID;
  }

  @Override
  public String cacheNamespace() {
    return CloudSpeechExecutor.CACHE_NAMESPACE;
  }

  @Override
  public boolean isAvailable() {
    return CloudHttp.isNonBlank(config.openRouterApiKey());
  }

  @Override
  public String missingKeyNotice() {
    return NO_KEY_NOTICE;
  }

  @Override
  public EnumSet<Emotion> supportedEmotions() {
    return model.supportedEmotions();
  }

  @Override
  public boolean isThrottled() {
    return executor.isThrottled();
  }

  @Override
  public void clearRateLimit() {
    executor.clearRateLimit();
  }

  @Override
  public void warmUp() {
    if (!isAvailable() || pooledConnectionCount() > 0) {
      return;
    }
    Request request =
        new Request.Builder()
            .url(warmUpEndpoint)
            .addHeader("Authorization", "Bearer " + config.openRouterApiKey().trim())
            .addHeader("User-Agent", CloudHttp.USER_AGENT)
            .get()
            .build();
    for (int i = 0; i < WARM_UP_CONNECTIONS; i++) {
      httpClient.newCall(request).enqueue(WARM_UP_CALLBACK);
    }
  }

  int pooledConnectionCount() {
    return httpClient.connectionPool().connectionCount();
  }

  int idlePooledConnectionCount() {
    return httpClient.connectionPool().idleConnectionCount();
  }

  Duration callBudgetFor(int inputLength) {
    Duration scaled =
        CALL_BUDGET_BASE.plusMillis(Math.max(0, inputLength) * CALL_BUDGET_MILLIS_PER_CHAR);
    return scaled.compareTo(callTimeout) > 0 ? callTimeout : scaled;
  }

  @Override
  public String cacheVariant(SynthesisRequest request) {
    return executor.cacheVariant(request);
  }

  @Override
  public Pcm synthesize(SynthesisRequest request) {
    return executor.synthesize(request);
  }

  @Override
  public Pcm synthesizeStreaming(SynthesisRequest request, PcmSink sink) {
    return executor.synthesizeStreaming(request, sink);
  }

  static String failureNotice(int httpCode) {
    if (httpCode == HttpURLConnection.HTTP_PAYMENT_REQUIRED) {
      return OUT_OF_CREDITS_NOTICE;
    }
    if (httpCode == HttpURLConnection.HTTP_UNAUTHORIZED
        || httpCode == HttpURLConnection.HTTP_FORBIDDEN) {
      return "OpenRouter TTS request failed (HTTP "
          + httpCode
          + "); check your API key. This line was not voiced.";
    }
    if (CloudHttp.isRejectedRequest(httpCode)) {
      return "OpenRouter rejected the TTS request (HTTP "
          + httpCode
          + "). This line was not voiced.";
    }
    return "OpenRouter TTS request failed (HTTP " + httpCode + "). This line was not voiced.";
  }

  private final class Ops implements CloudSpeechExecutor.Ops {

    @Override
    public String apiKey() {
      return config.openRouterApiKey();
    }

    @Override
    public String missingKeyNotice() {
      return NO_KEY_NOTICE;
    }

    @Override
    public String translate(String text, String language, String apiKey) {
      String translated = translator.translate(text, language, apiKey);
      if (translated != null) {
        support.recordTranslationSpend(text.length());
      }
      return translated;
    }

    @Override
    public CloudSpeechExecutor.PreparedSpeech buildRequests(
        CloudSpeechExecutor.SpokenLine line, SynthesisRequest request) {
      JsonObject payload = new JsonObject();
      payload.addProperty("model", model.modelId());
      payload.addProperty("input", line.input);
      payload.addProperty("voice", line.voice);
      payload.addProperty("response_format", model.responseFormat());
      OpenRouterProvider.apply(payload, model.speechMetadata(line.style));

      Request httpRequest =
          OpenRouterProvider.attributedRequest(endpoint, line.apiKey)
              .post(
                  RequestBody.create(
                      CloudHttp.JSON_MEDIA_TYPE,
                      gson.toJson(payload).getBytes(StandardCharsets.UTF_8)))
              .build();
      return new CloudSpeechExecutor.PreparedSpeech(
          httpRequest, line.speedRatio, line.input.length(), request.prefetch());
    }

    @Override
    public Call newCall(Request httpRequest, int inputLength) {
      Call call = httpClient.newCall(httpRequest);
      call.timeout().timeout(callBudgetFor(inputLength).toMillis(), TimeUnit.MILLISECONDS);
      return call;
    }

    @Override
    public String generationId(Response response) {
      return CloudHttp.headerOrEmpty(response, "X-Generation-Id");
    }

    @Override
    public CloudSpeechExecutor.DecodedSpeech decodeBuffered(
        byte[] bytes, CloudSpeechExecutor.PreparedSpeech prepared) {
      if (bytes.length == 0) {
        return CloudSpeechExecutor.DecodedSpeech.EMPTY;
      }
      return new CloudSpeechExecutor.DecodedSpeech(
          model.decodeResponse(bytes),
          bytes.length,
          () -> support.recordSpeechSpend(prepared.inputLen, prepared.prefetch));
    }

    @Override
    public CloudSpeechExecutor.StreamDrain newStreamDrain() {
      return OpenRouterTtsBackend::drainRawBody;
    }

    @Override
    public void recordSpendOnFirstChunk(CloudSpeechExecutor.PreparedSpeech prepared) {
      support.recordSpeechSpend(prepared.inputLen, prepared.prefetch);
    }

    @Override
    public String failureNotice(int httpCode, byte[] body) {
      return OpenRouterTtsBackend.failureNotice(httpCode);
    }

    @Override
    public String emptyBodyNotice() {
      return "OpenRouter TTS returned an empty response; this line was not voiced.";
    }
  }

  private static void drainRawBody(ResponseBody body, CloudSpeechExecutor.ChunkSink chunk)
      throws IOException {
    InputStream in = body.byteStream();
    byte[] buffer = new byte[STREAM_READ_BUFFER];
    int read;
    while ((read = in.read(buffer)) != -1) {
      if (read == 0) {
        continue;
      }
      chunk.accept(buffer, read);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
public final class OpenRouterUsageClient {

  static final String PRODUCTION_ENDPOINT = "https://openrouter.ai/api/v1/key";

  private final OkHttpClient httpClient;
  private final Gson gson;
  private final String endpoint;

  public OpenRouterUsageClient(OkHttpClient httpClient, Gson gson) {
    this(httpClient, gson, PRODUCTION_ENDPOINT);
  }

  OpenRouterUsageClient(OkHttpClient httpClient, Gson gson, String endpoint) {
    this.httpClient = httpClient;
    this.gson = gson;
    this.endpoint = endpoint;
  }

  public Double fetchUsage(String apiKey) {
    if (!CloudHttp.isNonBlank(apiKey)) {
      return null;
    }
    Request request =
        new Request.Builder()
            .url(endpoint)
            .addHeader("Authorization", "Bearer " + apiKey.trim())
            .addHeader("User-Agent", CloudHttp.USER_AGENT)
            .get()
            .build();
    try (Response response = httpClient.newCall(request).execute()) {
      ResponseBody body = response.body();
      String raw = body == null ? "" : body.string();
      if (!response.isSuccessful()) {
        log.debug("[TTS spend] balance read HTTP {}", response.code());
        return null;
      }
      return extractUsage(raw);
    } catch (IOException | RuntimeException e) {
      log.debug("[TTS spend] balance read failed: {}", e.getMessage());
      return null;
    }
  }

  Double extractUsage(String raw) {
    if (raw == null || raw.isEmpty()) {
      return null;
    }
    try {
      JsonObject parsed = gson.fromJson(raw, JsonObject.class);
      if (parsed == null || !parsed.has("data")) {
        return null;
      }
      JsonObject data = parsed.getAsJsonObject("data");
      if (data == null || !data.has("usage") || data.get("usage").isJsonNull()) {
        return null;
      }
      return data.get("usage").getAsDouble();
    } catch (RuntimeException e) {
      log.debug("[TTS spend] balance response parse error: {}", e.getMessage());
      return null;
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

public final class SpendPricing {

  static final double AUDIO_USD_PER_TOKEN = 9.00 / 1_000_000;

  static final double SPEECH_TEXT_USD_PER_TOKEN = 0.50 / 1_000_000;

  static final double TRANSLATION_INPUT_USD_PER_TOKEN = 0.10 / 1_000_000;

  static final double TRANSLATION_OUTPUT_USD_PER_TOKEN = 0.40 / 1_000_000;

  private SpendPricing() {}

  public static double estimateSpeechUsd(long audioTokens, long promptTokens) {
    return Math.max(0, audioTokens) * AUDIO_USD_PER_TOKEN
        + Math.max(0, promptTokens) * SPEECH_TEXT_USD_PER_TOKEN;
  }

  public static double estimateTranslationUsd(long inputTokens, long outputTokens) {
    return Math.max(0, inputTokens) * TRANSLATION_INPUT_USD_PER_TOKEN
        + Math.max(0, outputTokens) * TRANSLATION_OUTPUT_USD_PER_TOKEN;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import com.grahambartley.runelite.voiced.dialogue.speech.spend.SpendTracker.ProviderSpend;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public final class SpendReport {

  public static final String COMMAND = "voicedspend";

  private static final String NOTHING_SPENT =
      "Nothing has been voiced this session, so nothing has been spent.";

  private static final double SMALLEST_SHOWN_USD = 0.0001;

  private SpendReport() {}

  public static boolean matches(String command) {
    return command != null && COMMAND.equalsIgnoreCase(command.trim());
  }

  public static List<String> lines(List<ProviderSpend> snapshot, Double openRouterSpentUsd) {
    if (snapshot == null || snapshot.isEmpty()) {
      return Collections.singletonList(NOTHING_SPENT);
    }
    List<String> lines = new ArrayList<>(snapshot.size());
    for (ProviderSpend spend : snapshot) {
      lines.add(
          spend.provider() == TtsProvider.GOOGLE_AI_STUDIO
              ? aiStudioLine(spend)
              : openRouterLine(spend, openRouterSpentUsd));
    }
    return lines;
  }

  private static String openRouterLine(ProviderSpend spend, Double spentUsd) {
    StringBuilder text = counts(spend);
    text.append(count(spend.speechCharacters())).append(" characters sent");
    translation(text, spend);
    if (spentUsd == null) {
      return text.append(
              ". OpenRouter's billed spend could not be read; see openrouter.ai/settings/credits.")
          .toString();
    }
    return text.append(". Spent ")
        .append(usd(spentUsd))
        .append(", billed by OpenRouter.")
        .toString();
  }

  private static String aiStudioLine(ProviderSpend spend) {
    StringBuilder text = counts(spend);
    long tokens =
        spend.audioTokens()
            + spend.speechPromptTokens()
            + spend.translationInputTokens()
            + spend.translationOutputTokens();
    if (tokens == 0) {
      text.append(count(spend.speechCharacters())).append(" characters sent");
      translation(text, spend);
      return text.append(". Google AI Studio reported no token counts, so cost is unknown.")
          .toString();
    }
    text.append(count(spend.audioTokens()))
        .append(" audio tokens, ")
        .append(count(spend.speechPromptTokens()))
        .append(" text tokens");
    translationTokens(text, spend);
    double usd =
        SpendPricing.estimateSpeechUsd(spend.audioTokens(), spend.speechPromptTokens())
            + SpendPricing.estimateTranslationUsd(
                spend.translationInputTokens(), spend.translationOutputTokens());
    return text.append(". Estimated ")
        .append(usd(usd))
        .append(" (tokens measured, price from Google's published rate).")
        .toString();
  }

  private static StringBuilder counts(ProviderSpend spend) {
    return new StringBuilder()
        .append(spend.provider())
        .append(" this session: ")
        .append(count(spend.voicedLines()))
        .append(" lines voiced, ")
        .append(count(spend.prefetchedLines()))
        .append(" prefetched, ");
  }

  private static void translation(StringBuilder text, ProviderSpend spend) {
    if (spend.translationCalls() > 0) {
      text.append(", plus ")
          .append(count(spend.translationCalls()))
          .append(" translation calls (")
          .append(count(spend.translationCharacters()))
          .append(" characters)");
    }
  }

  private static void translationTokens(StringBuilder text, ProviderSpend spend) {
    if (spend.translationCalls() > 0) {
      text.append(", plus ")
          .append(count(spend.translationCalls()))
          .append(" translation calls (")
          .append(count(spend.translationInputTokens() + spend.translationOutputTokens()))
          .append(" tokens)");
    }
  }

  private static String count(long value) {
    return String.format(Locale.US, "%,d", value);
  }

  private static String usd(double value) {
    if (value > 0 && value < SMALLEST_SHOWN_USD) {
      return "under $" + String.format(Locale.US, "%.4f", SMALLEST_SHOWN_USD);
    }
    return String.format(Locale.US, "$%.4f", value);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.spend;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.TtsProvider;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import lombok.Value;
import lombok.experimental.Accessors;

public final class SpendTracker {

  @Value
  @Accessors(fluent = true)
  public static class ProviderSpend {
    TtsProvider provider;
    long voicedLines;
    long prefetchedLines;
    long speechCharacters;
    long translationCalls;
    long translationCharacters;

    long audioTokens;

    long speechPromptTokens;

    long translationInputTokens;

    long translationOutputTokens;
  }

  private final Map<TtsProvider, Counters> byProvider = new ConcurrentHashMap<>();

  public void recordSpeech(TtsProvider provider, int characters, boolean prefetch) {
    recordSpeech(provider, characters, prefetch, 0, 0);
  }

  public void recordSpeech(
      TtsProvider provider, int characters, boolean prefetch, long audioTokens, long promptTokens) {
    Counters counters = counters(provider);
    if (prefetch) {
      counters.prefetchedLines.incrementAndGet();
    } else {
      counters.voicedLines.incrementAndGet();
    }
    counters.speechCharacters.addAndGet(Math.max(0, characters));
    counters.audioTokens.addAndGet(Math.max(0, audioTokens));
    counters.speechPromptTokens.addAndGet(Math.max(0, promptTokens));
  }

  public void recordTranslation(TtsProvider provider, int characters) {
    recordTranslation(provider, characters, 0, 0);
  }

  public void recordTranslation(
      TtsProvider provider, int characters, long inputTokens, long outputTokens) {
    Counters counters = counters(provider);
    counters.translationCalls.incrementAndGet();
    counters.translationCharacters.addAndGet(Math.max(0, characters));
    counters.translationInputTokens.addAndGet(Math.max(0, inputTokens));
    counters.translationOutputTokens.addAndGet(Math.max(0, outputTokens));
  }

  public List<ProviderSpend> snapshot() {
    List<ProviderSpend> out = new ArrayList<>(byProvider.size());
    for (TtsProvider provider : TtsProvider.values()) {
      Counters counters = byProvider.get(provider);
      if (counters != null) {
        out.add(counters.toSpend(provider));
      }
    }
    return out;
  }

  private Counters counters(TtsProvider provider) {
    return byProvider.computeIfAbsent(provider, p -> new Counters());
  }

  private static final class Counters {
    final AtomicLong voicedLines = new AtomicLong();
    final AtomicLong prefetchedLines = new AtomicLong();
    final AtomicLong speechCharacters = new AtomicLong();
    final AtomicLong translationCalls = new AtomicLong();
    final AtomicLong translationCharacters = new AtomicLong();
    final AtomicLong audioTokens = new AtomicLong();
    final AtomicLong speechPromptTokens = new AtomicLong();
    final AtomicLong translationInputTokens = new AtomicLong();
    final AtomicLong translationOutputTokens = new AtomicLong();

    ProviderSpend toSpend(TtsProvider provider) {
      return new ProviderSpend(
          provider,
          voicedLines.get(),
          prefetchedLines.get(),
          speechCharacters.get(),
          translationCalls.get(),
          translationCharacters.get(),
          audioTokens.get(),
          speechPromptTokens.get(),
          translationInputTokens.get(),
          translationOutputTokens.get());
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.puppycrawl.tools.checkstyle.Checker;
import com.puppycrawl.tools.checkstyle.ConfigurationLoader;
import com.puppycrawl.tools.checkstyle.PropertiesExpander;
import com.puppycrawl.tools.checkstyle.api.AuditEvent;
import com.puppycrawl.tools.checkstyle.api.AuditListener;
import com.puppycrawl.tools.checkstyle.api.Configuration;
import java.io.File;
import java.io.InputStream;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.junit.BeforeClass;
import org.junit.ClassRule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class NoCommentsRuleTest {

  private static final String CONFIG_PATH = "config/checkstyle/checkstyle.xml";
  private static final String FIXTURE_RESOURCE = "/comment-gate/CommentGateFixture.java.txt";
  private static final String RULE_ID = "NoComments";
  private static final String STANDARD_DOC = "docs/development.md";

  private static final Map<Integer, String> COMMENT_LINES = commentLines();
  private static final Map<Integer, String> COMMENT_LIKE_LITERAL_LINES = commentLikeLiteralLines();

  @ClassRule public static final TemporaryFolder WORKSPACE = new TemporaryFolder();

  private static List<AuditEvent> violations;

  private static Map<Integer, String> commentLines() {
    Map<Integer, String> lines = new LinkedHashMap<>();
    lines.put(3, "javadoc on the type");
    lines.put(6, "a plain line comment");
    lines.put(19, "a trailing comment after code");
    lines.put(21, "a bare double slash carrying no text");
    lines.put(23, "a block comment");
    lines.put(25, "an inline block comment after code");
    return Collections.unmodifiableMap(lines);
  }

  private static Map<Integer, String> commentLikeLiteralLines() {
    Map<Integer, String> lines = new LinkedHashMap<>();
    lines.put(7, "a url whose slashes sit inside a string");
    lines.put(9, "block comment markers inside a string");
    lines.put(11, "a double quote character literal");
    lines.put(13, "an escaped quote followed by slashes inside a string");
    lines.put(15, "the opening delimiter of a text block");
    lines.put(16, "comment markers inside a text block");
    lines.put(17, "the closing delimiter of a text block");
    return Collections.unmodifiableMap(lines);
  }

  @BeforeClass
  public static void auditTheFixture() throws Exception {
    File config = new File(CONFIG_PATH);
    assertTrue(
        CONFIG_PATH + " is missing, so the gate has no configuration to enforce", config.isFile());
    violations = audit(config, fixtureWrittenToDisk());
  }

  @Test
  public void everyCommentFormIsReported() {
    Set<Integer> reported = reportedLines();
    List<String> missed = new ArrayList<>();
    for (Map.Entry<Integer, String> line : COMMENT_LINES.entrySet()) {
      if (!reported.contains(line.getKey())) {
        missed.add("line " + line.getKey() + " (" + line.getValue() + ")");
      }
    }
    assertEquals(
        "the gate failed to report comment forms it must catch, so it has stopped gating",
        Collections.emptyList(),
        missed);
  }

  @Test
  public void noCommentLikeStringLiteralIsMistakenForAComment() {
    Set<Integer> reported = reportedLines();
    List<String> wronglyReported = new ArrayList<>();
    for (Map.Entry<Integer, String> line : COMMENT_LIKE_LITERAL_LINES.entrySet()) {
      if (reported.contains(line.getKey())) {
        wronglyReported.add("line " + line.getKey() + " (" + line.getValue() + ")");
      }
    }
    assertEquals(
        "the gate reported source that is not a comment, so the query matches too much",
        Collections.emptyList(),
        wronglyReported);
  }

  @Test
  public void theGateReportsEveryCommentAndNothingElse() {
    assertEquals(
        "expected one violation per comment in the fixture, got them at lines " + reportedLines(),
        COMMENT_LINES.size(),
        violations.size());
  }

  @Test
  public void everyViolationCarriesTheRuleIdSoCiOutputIsTraceable() {
    assertFalse("no violations were produced, so the id proves nothing", violations.isEmpty());
    for (AuditEvent violation : violations) {
      assertEquals(
          "a violation reached the build without the rule id that names it",
          RULE_ID,
          violation.getModuleId());
    }
  }

  @Test
  public void everyViolationNamesTheStandardItEnforces() {
    assertFalse("no violations were produced, so the message proves nothing", violations.isEmpty());
    for (AuditEvent violation : violations) {
      assertTrue(
          "a violation reached the build without pointing at " + STANDARD_DOC,
          violation.getMessage().contains(STANDARD_DOC));
    }
  }

  private static Set<Integer> reportedLines() {
    Set<Integer> lines = new TreeSet<>();
    for (AuditEvent violation : violations) {
      lines.add(violation.getLine());
    }
    return lines;
  }

  private static File fixtureWrittenToDisk() throws Exception {
    File target = new File(WORKSPACE.getRoot(), "CommentGateFixture.java");
    try (InputStream source = NoCommentsRuleTest.class.getResourceAsStream(FIXTURE_RESOURCE)) {
      assertNotNull(FIXTURE_RESOURCE + " is missing from the gate test resources", source);
      Files.copy(source, target.toPath());
    }
    return target;
  }

  private static List<AuditEvent> audit(File config, File subject) throws Exception {
    Configuration configuration =
        ConfigurationLoader.loadConfiguration(
            config.getPath(), new PropertiesExpander(System.getProperties()));
    List<AuditEvent> collected = new ArrayList<>();
    Checker checker = new Checker();
    try {
      checker.setModuleClassLoader(Checker.class.getClassLoader());
      checker.configure(configuration);
      checker.addListener(new ViolationCollector(collected));
      checker.process(Collections.singletonList(subject));
    } finally {
      checker.destroy();
    }
    return collected;
  }

  private static final class ViolationCollector implements AuditListener {

    private final List<AuditEvent> collected;

    private ViolationCollector(List<AuditEvent> collected) {
      this.collected = collected;
    }

    @Override
    public void addError(AuditEvent event) {
      collected.add(event);
    }

    @Override
    public void addException(AuditEvent event, Throwable throwable) {
      throw new IllegalStateException("checkstyle failed to audit the fixture", throwable);
    }

    @Override
    public void auditStarted(AuditEvent event) {}

    @Override
    public void auditFinished(AuditEvent event) {}

    @Override
    public void fileStarted(AuditEvent event) {}

    @Override
    public void fileFinished(AuditEvent event) {}
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static java.util.stream.Collectors.toList;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.junit.Test;

public class PackageDependencyTest {

  private static final String BASE = "com.grahambartley.runelite.voiced.dialogue";
  private static final Path MAIN = Paths.get("src/main/java", BASE.replace('.', '/'));

  private static final Map<String, Integer> TIER = new HashMap<>();

  static {
    TIER.put("", 8);
    TIER.put("capture", 7);
    TIER.put("panel", 7);
    TIER.put("speech.openrouter", 7);
    TIER.put("speech.aistudio", 7);
    TIER.put("speech", 6);
    TIER.put("cache", 5);
    TIER.put("speech.model", 5);
    TIER.put("profile", 4);
    TIER.put("speaker.wiki", 3);
    TIER.put("speaker", 2);
    TIER.put("audio", 1);
    TIER.put("speech.spend", 1);
  }

  private static final Set<String> ROOT_TYPES_ANY_TIER =
      Collections.singleton("VoicedDialogueConfig");

  private static final Pattern IMPORT =
      Pattern.compile("^import (?:static )?" + Pattern.quote(BASE) + "\\.([\\w.]+);");

  private static String packageOfImport(String path) {
    StringBuilder pkg = new StringBuilder();
    for (String segment : path.split("\\.")) {
      if (!Character.isLowerCase(segment.charAt(0))) {
        break;
      }
      pkg.append(pkg.length() == 0 ? "" : ".").append(segment);
    }
    return pkg.toString();
  }

  @Test
  public void everyPackageIsPlacedInTheLayering() throws IOException {
    for (Path dir : walk(Files::isDirectory)) {
      assertTrue(
          "package '"
              + packageOf(dir)
              + "' is missing from the layering; place it here and in"
              + " docs/development.md",
          TIER.containsKey(packageOf(dir)));
    }
  }

  @Test
  public void noImportRunsAgainstTheLayering() throws IOException {
    List<String> violations = new ArrayList<>();
    for (Path source : sources()) {
      String from = packageOf(source.getParent());
      for (String line : Files.readAllLines(source, StandardCharsets.UTF_8)) {
        Matcher matcher = IMPORT.matcher(line);
        if (!matcher.find()) {
          continue;
        }
        String to = packageOfImport(matcher.group(1));
        if (from.equals(to)) {
          continue;
        }
        if (to.isEmpty()) {
          String type = matcher.group(1).split("\\.")[0];
          if (!ROOT_TYPES_ANY_TIER.contains(type)) {
            violations.add(
                String.format(
                    "%s imports root type %s in %s", label(from), type, source.getFileName()));
          }
          continue;
        }
        if (!TIER.containsKey(to)) {
          violations.add(
              String.format(
                  "%s imports unplaced package %s in %s",
                  label(from), label(to), source.getFileName()));
          continue;
        }
        if (TIER.get(from) > TIER.get(to)) {
          continue;
        }
        violations.add(
            String.format(
                "%s (tier %d) imports %s (tier %d) in %s",
                label(from), TIER.get(from), to, TIER.get(to), source.getFileName()));
      }
    }
    if (!violations.isEmpty()) {
      fail("imports run against the package layering:\n  " + String.join("\n  ", violations));
    }
  }

  @Test
  public void everySourceFileSitsInTheDirectoryItsPackageNames() throws IOException {
    for (Path source : sources()) {
      String pkg = packageOf(source.getParent());
      String expected = pkg.isEmpty() ? BASE : BASE + "." + pkg;
      assertEquals("misplaced source file " + source, expected, declaredPackage(source));
    }
  }

  private static String label(String pkg) {
    return pkg.isEmpty() ? "<root>" : pkg;
  }

  private static String declaredPackage(Path source) throws IOException {
    for (String line : Files.readAllLines(source, StandardCharsets.UTF_8)) {
      if (line.startsWith("package ")) {
        return line.substring("package ".length()).replace(";", "").trim();
      }
    }
    throw new AssertionError("no package declaration in " + source);
  }

  private static String packageOf(Path dir) {
    return MAIN.relativize(dir).toString().replace('/', '.');
  }

  private static List<Path> sources() throws IOException {
    return walk(path -> path.toString().endsWith(".java"));
  }

  private static List<Path> walk(java.util.function.Predicate<Path> keep) throws IOException {
    try (Stream<Path> walk = Files.walk(MAIN)) {
      return walk.filter(keep).sorted().collect(toList());
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.RETURNS_SELF;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuEntryAdded;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class SetVoiceMenuTest {

  private static final int HANS = 3105;
  private static final int PROFILE_ID = 3106;
  private static final String TARGET = "<col=ffff00>Hans";

  private final Client client = mock(Client.class);
  private final Menu menu = mock(Menu.class);
  private final MenuEntry created = mock(MenuEntry.class, RETURNS_SELF);
  private final Map<NPC, Integer> profileIds = new HashMap<>();
  private final Set<Integer> speakers = new HashSet<>();
  private final List<Runnable> uiQueue = new ArrayList<>();
  private final List<String> opened = new ArrayList<>();
  private boolean enabled = true;

  private final SetVoiceMenu setVoiceMenu =
      new SetVoiceMenu(
          client,
          () -> enabled,
          profileIds::get,
          speakers::contains,
          uiQueue::add,
          (npcId, name) -> opened.add(npcId + ":" + name));

  public SetVoiceMenuTest() {
    when(client.getMenu()).thenReturn(menu);
    when(menu.createMenuEntry(anyInt())).thenReturn(created);
  }

  private static NPC npc(int id, String name) {
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(id);
    when(npc.getName()).thenReturn(name);
    return npc;
  }

  private NPC speaker(String name) {
    NPC npc = npc(HANS, name);
    profileIds.put(npc, PROFILE_ID);
    speakers.add(PROFILE_ID);
    return npc;
  }

  private static MenuEntryAdded added(MenuAction type, NPC npc) {
    MenuEntry entry = mock(MenuEntry.class);
    when(entry.getType()).thenReturn(type);
    when(entry.getNpc()).thenReturn(npc);
    when(entry.getTarget()).thenReturn(TARGET);
    when(entry.getIdentifier()).thenReturn(7);
    return new MenuEntryAdded(entry);
  }

  @SuppressWarnings("unchecked")
  private void clickCreatedEntry() {
    ArgumentCaptor<Consumer<MenuEntry>> onClick = ArgumentCaptor.forClass(Consumer.class);
    verify(created).onClick(onClick.capture());
    onClick.getValue().accept(created);
  }

  private void drainUi() {
    List<Runnable> queued = new ArrayList<>(uiQueue);
    uiQueue.clear();
    queued.forEach(Runnable::run);
  }

  @Test
  public void examiningAnNpcAddsSetVoiceBesideIt() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, speaker("Hans")));

    verify(menu).createMenuEntry(-1);
    verify(created).setOption("Set-voice");
    verify(created).setTarget(TARGET);
    verify(created).setIdentifier(7);
    verify(created).setType(MenuAction.RUNELITE);
  }

  @Test
  public void otherNpcOptionsAddNothingSoEachNpcGetsOneEntry() {
    NPC hans = speaker("Hans");
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.NPC_FIRST_OPTION, hans));
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.NPC_SECOND_OPTION, hans));

    verify(menu, never()).createMenuEntry(anyInt());
  }

  @Test
  public void nonNpcEntriesAddNothing() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_OBJECT, null));
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.WALK, null));

    verify(menu, never()).createMenuEntry(anyInt());
  }

  @Test
  public void anExamineEntryWithNoNpcAddsNothing() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, null));

    verify(menu, never()).createMenuEntry(anyInt());
  }

  @Test
  public void turningTheSettingOffHidesTheEntryOnTheNextMenu() {
    NPC hans = speaker("Hans");
    enabled = false;
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, hans));
    verify(menu, never()).createMenuEntry(anyInt());

    enabled = true;
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, hans));
    verify(menu).createMenuEntry(-1);
  }

  @Test
  public void choosingSetVoiceOpensThatNpcOnTheUiThreadUnderItsProfileId() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, speaker("Hans")));

    clickCreatedEntry();
    assertTrue("the panel is only touched on the UI thread", opened.isEmpty());
    drainUi();

    assertEquals(1, opened.size());
    assertEquals(PROFILE_ID + ":Hans", opened.get(0));
  }

  @Test
  public void anNpcWithNoResolvableIdAddsNothing() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, npc(HANS, "Hans")));

    verify(menu, never()).createMenuEntry(anyInt());
  }

  @Test
  public void anNpcThatNeverSpeaksAddsNothing() {
    NPC demon = npc(415, "Abyssal demon");
    profileIds.put(demon, 415);

    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, demon));

    verify(menu, never()).createMenuEntry(anyInt());
  }

  @Test
  public void anNpcIsJudgedByItsProfileIdNotItsWorldId() {
    NPC shifted = npc(999, "Hans");
    profileIds.put(shifted, PROFILE_ID);
    speakers.add(PROFILE_ID);

    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, shifted));

    verify(menu).createMenuEntry(-1);
  }

  @Test
  public void aTaggedNameOpensUnderItsPlainName() {
    setVoiceMenu.onMenuEntryAdded(
        added(MenuAction.EXAMINE_NPC, speaker("<col=ffff00>Hans</col> ")));

    clickCreatedEntry();
    drainUi();

    assertEquals(PROFILE_ID + ":Hans", opened.get(0));
  }

  @Test
  public void anNpcWithNoNameOpensNothing() {
    setVoiceMenu.onMenuEntryAdded(added(MenuAction.EXAMINE_NPC, speaker(null)));

    clickCreatedEntry();
    drainUi();

    assertTrue(opened.isEmpty());
  }
}

package com.grahambartley.runelite.voiced.dialogue;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig.SpokenLanguage;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

public class VoicedDialogueConfigTest {

  private static final int MAX_DESCRIPTION_CHARS = 120;

  private static final int DISCLOSURE_CHARS = 200;

  @Test
  public void theProviderTooltipStatesTheCeilingAndTheUncappedAlternative() throws Exception {
    String description =
        VoicedDialogueConfig.class
            .getMethod("ttsProvider")
            .getAnnotation(ConfigItem.class)
            .description();

    assertTrue(
        "a player choosing in the panel is told the fast provider's ceiling: " + description,
        description.contains("caps fresh lines a day"));
    assertTrue(
        "and that the other one has none: " + description,
        description.contains("OpenRouter has no daily cap"));
    assertTrue(
        "and that the provider bills them, which docs/hub-compliance-checklist.md records as a"
            + " verified disclosure: "
            + description,
        description.contains("bills the calls"));
  }

  @Test
  public void englishIsTheDefaultNoTranslationLanguage() {
    assertTrue("English is the no-translation default", SpokenLanguage.ENGLISH.isEnglish());
    for (SpokenLanguage language : SpokenLanguage.values()) {
      assertEquals(
          "English is the only language treated as no-translation",
          language == SpokenLanguage.ENGLISH,
          language.isEnglish());
    }
  }

  @Test
  public void everyLanguageCarriesAName() {
    for (SpokenLanguage language : SpokenLanguage.values()) {
      assertFalse(
          "a language name is fed to the prompt, so it is never blank", language.label().isEmpty());
    }
  }

  @Test
  public void theDropdownIsDeAliasedSoEachLanguageAppearsOnce() {
    Set<String> labels = new HashSet<>();
    for (SpokenLanguage language : SpokenLanguage.values()) {
      assertTrue(
          "a duplicate name means an alias slipped in: " + language.label(),
          labels.add(language.label()));
    }
  }

  @Test
  public void toStringShowsTheDisplayName() {
    assertEquals("English", SpokenLanguage.ENGLISH.toString());
    assertEquals("Spanish", SpokenLanguage.SPANISH.toString());
  }

  @Test
  public void regionalVariantsShortenTheDropdownTextButKeepTheFullTranslationName() {
    assertEquals("Portuguese (BR)", SpokenLanguage.BRAZILIAN_PORTUGUESE.toString());
    assertEquals("Brazilian Portuguese", SpokenLanguage.BRAZILIAN_PORTUGUESE.label());
    assertEquals("Spanish (LatAm)", SpokenLanguage.LATIN_AMERICAN_SPANISH.toString());
    assertEquals("Latin American Spanish", SpokenLanguage.LATIN_AMERICAN_SPANISH.label());
  }

  @Test
  public void noSettingDescriptionRunsLongerThanATooltipComfortablyShows() {
    List<String> tooLong = new ArrayList<>();
    for (Method method : VoicedDialogueConfig.class.getMethods()) {
      ConfigItem item = method.getAnnotation(ConfigItem.class);
      if (item == null) {
        continue;
      }
      int limit =
          VoicedDialogueConfig.PROVIDER_KEY.equals(item.keyName())
              ? DISCLOSURE_CHARS
              : MAX_DESCRIPTION_CHARS;
      if (item.description().length() > limit) {
        tooLong.add(item.name() + " (" + item.description().length() + " > " + limit + ")");
      }
    }
    assertTrue("descriptions longer than a tooltip shows: " + tooLong, tooLong.isEmpty());
  }

  @Test
  public void everySettingCarriesANameAndADescription() {
    for (Method method : VoicedDialogueConfig.class.getMethods()) {
      ConfigItem item = method.getAnnotation(ConfigItem.class);
      if (item == null) {
        continue;
      }
      assertFalse("a setting with no name: " + method.getName(), item.name().trim().isEmpty());
      assertFalse(
          "a setting with no description: " + item.name(), item.description().trim().isEmpty());
    }
  }

  @Test
  public void profileSteeringKeysKeepTheirStoredNames() throws Exception {
    assertEquals(
        "playerAccent",
        VoicedDialogueConfig.class
            .getMethod("playerAccent")
            .getAnnotation(ConfigItem.class)
            .keyName());
    assertEquals(
