@RunWith(JUnitParamsRunner.class)
public class CaveEchoPolicyTest {

  private Object[] undergroundPointCases() {
    return new Object[] {
      new Object[] {new WorldPoint(3200, Constants.OVERWORLD_MAX_Y - 1, 0), false},
      new Object[] {new WorldPoint(3200, Constants.OVERWORLD_MAX_Y, 0), true},
      new Object[] {new WorldPoint(3200, 9000, 0), true},
    };
  }

  @Test
  @Parameters(method = "undergroundPointCases")
  public void undergroundPointGatesOnTheOverworldCeiling(WorldPoint point, boolean expected) {
    assertEquals(expected, CaveEchoPolicy.isUndergroundPoint(point));
  }

  @Test
  public void prifddinasIsCorrectedBackToSurfaceByTheMirror() {
    WorldPoint inPrifddinasBand = new WorldPoint(3256, 6055, 0);
    assertTrue(
        "the raw point is in the underground band",
        inPrifddinasBand.getY() >= Constants.OVERWORLD_MAX_Y);
    assertFalse(
        "Prifddinas must read as surface after the mirror correction",
        CaveEchoPolicy.isUndergroundPoint(inPrifddinasBand));
  }

  @Test
  public void playerOwnedHouseIsCarvedOutDespiteSittingInTheBand() {
    for (WorldPoint inPoh :
        new WorldPoint[] {new WorldPoint(1960, 7045, 0), new WorldPoint(1944, 7107, 0)}) {
      assertTrue(
          "the POH point is in a carved-out region",
          CaveEchoPolicy.POH_REGION_IDS.contains(inPoh.getRegionID()));
      assertTrue(
          "the raw point is in the underground band", inPoh.getY() >= Constants.OVERWORLD_MAX_Y);
      assertFalse(
          "the player-owned house must read as surface", CaveEchoPolicy.isUndergroundPoint(inPoh));
    }
  }

  @Test
  public void isUndergroundReadsTheLivePlayerLocation() {
    Client client = mock(Client.class);
    VoicedDialogueConfig config = mock(VoicedDialogueConfig.class);
    CaveEchoPolicy policy = new CaveEchoPolicy(client, config);

    when(client.getLocalPlayer()).thenReturn(null);
    assertFalse("no local player reads as surface", policy.isUnderground());

    Player player = mock(Player.class);
    when(client.getLocalPlayer()).thenReturn(player);
    when(client.isInInstancedRegion()).thenReturn(false);

    when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 9000, 0));
    assertTrue("a deep cave reads as underground", policy.isUnderground());

    when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
    assertFalse("an overworld tile reads as surface", policy.isUnderground());
  }

  private Object[] shouldEchoCases() {
    return new Object[] {
      new Object[] {true, 9000, true},
      new Object[] {false, 9000, false},
      new Object[] {true, 3200, false},
    };
  }

  @Test
  @Parameters(method = "shouldEchoCases")
  public void shouldEchoGatesOnToggleAndLocation(
      boolean caveEchoEnabled, int worldY, boolean expected) {
    Client client = mock(Client.class);
    VoicedDialogueConfig config = mock(VoicedDialogueConfig.class);
    Player player = mock(Player.class);
    when(client.getLocalPlayer()).thenReturn(player);
    when(client.isInInstancedRegion()).thenReturn(false);
    when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, worldY, 0));
    when(config.cloudCaveEcho()).thenReturn(caveEchoEnabled);

    assertEquals(expected, new CaveEchoPolicy(client, config).shouldEcho());
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CaveEchoTest {

  private static int delaySamples(int rate) {
    return Math.max(1, Math.round(CaveEcho.DELAY_MS * rate / 1000f));
  }

  @Test
  public void impulseDecaysAcrossSuccessiveTaps() {
    int rate = 24_000;
    int d = delaySamples(rate);
    float[] in = new float[] {1f};
    Pcm out = CaveEcho.apply(new Pcm(in, rate));
    float[] s = out.getSamples();

    float firstTap = Math.abs(s[d]);
    float secondTap = Math.abs(s[2 * d]);
    assertTrue("first echo tap should be audible", firstTap > 0f);
    assertTrue("echo should decay: second tap quieter than first", secondTap < firstTap);
  }

  @Test
  public void silenceInSilenceOut() {
    Pcm out = CaveEcho.apply(new Pcm(new float[256], 24_000));
    for (float v : out.getSamples()) {
      assertEquals(0f, v, 0f);
    }
  }

  @Test
  public void outputLengthIsInputPlusTail() {
    int rate = 24_000;
    int d = delaySamples(rate);
    int hops = (int) Math.ceil(Math.log(CaveEcho.TAIL_FLOOR) / Math.log(CaveEcho.FEEDBACK));
    int tail = Math.min(hops * d, CaveEcho.MAX_TAIL_MS * rate / 1000);
    float[] in = new float[100];
    Pcm out = CaveEcho.apply(new Pcm(in, rate));
    assertEquals(in.length + tail, out.getSamples().length);
  }

  @Test
  public void everyOutputSampleIsWithinUnitRange() {
    float[] in = new float[2048];
    for (int i = 0; i < in.length; i++) {
      in[i] = i % 2 == 0 ? 1f : -1f;
    }
    Pcm out = CaveEcho.apply(new Pcm(in, 24_000));
    for (float v : out.getSamples()) {
      assertTrue("sample out of range: " + v, v >= -1f && v <= 1f);
    }
  }

  @Test
  public void inputArrayIsNotMutated() {
    float[] in = new float[] {0.5f, -0.5f, 0.25f};
    float[] copy = in.clone();
    CaveEcho.apply(new Pcm(in, 24_000));
    assertEquals(copy.length, in.length);
    for (int i = 0; i < in.length; i++) {
      assertEquals(copy[i], in[i], 0f);
    }
  }

  @Test
  public void delayScalesWithSampleRate() {
    for (int rate : new int[] {24_000, 48_000}) {
      int d = delaySamples(rate);
      float[] s = CaveEcho.apply(new Pcm(new float[] {1f}, rate)).getSamples();
      assertTrue("a tap should land at the rate-scaled delay for " + rate, Math.abs(s[d]) > 0f);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static com.grahambartley.runelite.voiced.dialogue.audio.TestPcm.peak;
import static com.grahambartley.runelite.voiced.dialogue.audio.TestPcm.rms;
import static com.grahambartley.runelite.voiced.dialogue.audio.TestPcm.sine;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class LoudnessLevellerTest {

  private static final int RATE = 24_000;
  private static final int ONE_SECOND = RATE;
  private static final float FULL_VOLUME_RMS = (float) Math.pow(10, -18.0 / 20);
  private static final float CEILING = (float) Math.pow(10, -1.0 / 20);
  private static final float SINE_CREST = (float) Math.sqrt(2);
  private static final float DB_TOLERANCE = 0.1f;

  private static float db(float amplitude) {
    return (float) (20 * Math.log10(amplitude));
  }

  private static float amplitudeForRms(float rms) {
    return rms * SINE_CREST;
  }

  private static float[] played(float[] samples, int volumePercent) {
    float gain = LoudnessLeveller.measure(samples, RATE).gainAt(volumePercent);
    float[] out = new float[samples.length];
    for (int i = 0; i < samples.length; i++) {
      out[i] = samples[i] * gain;
    }
    return out;
  }

  @Test
  public void aQuietClipIsRaisedToTheFullVolumeLevel() {
    float[] quiet = sine(amplitudeForRms(FULL_VOLUME_RMS / 3), ONE_SECOND);

    assertEquals(db(FULL_VOLUME_RMS), db(rms(played(quiet, 100))), DB_TOLERANCE);
  }

  @Test
  public void aLoudClipIsLoweredToTheFullVolumeLevel() {
    float[] loud = sine(amplitudeForRms(FULL_VOLUME_RMS * 3), ONE_SECOND);

    assertEquals(db(FULL_VOLUME_RMS), db(rms(played(loud, 100))), DB_TOLERANCE);
  }

  @Test
  public void aClipAlreadyAtTheLevelIsUntouchedAtFullVolume() {
    float[] atLevel = sine(amplitudeForRms(FULL_VOLUME_RMS), ONE_SECOND);

    assertEquals(1f, LoudnessLeveller.measure(atLevel, RATE).gainAt(100), 1e-3f);
  }

  @Test
  public void theVolumeSetsTheLevelEveryClipLandsOn() {
    float[] quiet = sine(amplitudeForRms(FULL_VOLUME_RMS / 3), ONE_SECOND);
    float[] loud = sine(amplitudeForRms(FULL_VOLUME_RMS * 3), ONE_SECOND);
    float expected = db(FULL_VOLUME_RMS * 0.5f);

    assertEquals(expected, db(rms(played(quiet, 50))), DB_TOLERANCE);
    assertEquals(expected, db(rms(played(loud, 50))), DB_TOLERANCE);
  }

  @Test
  public void zeroVolumeMutes() {
    float[] speech = sine(0.2f, ONE_SECOND);

    assertEquals(0f, LoudnessLeveller.measure(speech, RATE).gainAt(0), 0f);
  }

  @Test
  public void volumeOutsideTheRangeIsClamped() {
    LoudnessLeveller leveller =
        LoudnessLeveller.measure(sine(amplitudeForRms(FULL_VOLUME_RMS), ONE_SECOND), RATE);

    assertEquals(leveller.gainAt(100), leveller.gainAt(250), 0f);
    assertEquals(0f, leveller.gainAt(-5), 0f);
  }

  @Test
  public void silenceIsLeftAlone() {
    LoudnessLeveller leveller = LoudnessLeveller.measure(new float[ONE_SECOND], RATE);

    assertEquals(1f, leveller.gainAt(100), 0f);
    assertEquals(0.2f, leveller.gainAt(20), 1e-6f);
  }

  @Test
  public void noiseBelowTheSilenceGateIsNotBoosted() {
    assertEquals(1f, LoudnessLeveller.measure(sine(1e-4f, ONE_SECOND), RATE).gainAt(100), 0f);
  }

  @Test
  public void pausesBetweenWordsDoNotCountTowardsTheLevel() {
    float[] speechWithPause = new float[ONE_SECOND * 2];
    float[] speech = sine(amplitudeForRms(FULL_VOLUME_RMS), ONE_SECOND);
    System.arraycopy(speech, 0, speechWithPause, 0, ONE_SECOND);

    assertEquals(1f, LoudnessLeveller.measure(speechWithPause, RATE).gainAt(100), 1e-3f);
  }

  @Test
  public void theBoostIsCappedSoAWhisperIsNotBlownUp() {
    float[] whisper = sine(amplitudeForRms(FULL_VOLUME_RMS / 10), ONE_SECOND);

    assertEquals(12f, db(LoudnessLeveller.measure(whisper, RATE).gainAt(100)), DB_TOLERANCE);
  }

  @Test
  public void aSpikyClipIsLimitedByItsPeakAtFullVolume() {
    float[] spiky = sine(amplitudeForRms(FULL_VOLUME_RMS / 3), ONE_SECOND);
    spiky[100] = 0.5f;

    float[] out = played(spiky, 100);

    assertEquals(CEILING, peak(out), 1e-4f);
    assertTrue(rms(out) < FULL_VOLUME_RMS);
  }

  @Test
  public void aSpikyClipReachesTheLevelAtEverydayVolume() {
    float[] spiky = sine(amplitudeForRms(FULL_VOLUME_RMS / 3), ONE_SECOND);
    spiky[100] = 0.5f;

    assertEquals(db(FULL_VOLUME_RMS * 0.2f), db(rms(played(spiky, 20))), DB_TOLERANCE);
  }

  @Test
  public void noPlayedSampleExceedsTheCeiling() {
    float[] clipped = sine(1f, ONE_SECOND);
    clipped[7] = 1.5f;
    clipped[8] = -1.5f;

    assertTrue(peak(played(clipped, 100)) <= CEILING + 1e-6f);
  }

  @Test
  public void aLouderLaterChunkLowersTheGain() {
    LoudnessLeveller leveller =
        LoudnessLeveller.measure(sine(amplitudeForRms(FULL_VOLUME_RMS / 3), ONE_SECOND), RATE);
    float before = leveller.gainAt(100);

    leveller.include(new float[] {0.5f, -0.5f});

    assertEquals(CEILING / 0.5f, leveller.gainAt(100), 1e-5f);
    assertTrue(leveller.gainAt(100) < before);
  }

  @Test
  public void aQuieterLaterChunkKeepsTheGain() {
    LoudnessLeveller leveller =
        LoudnessLeveller.measure(sine(amplitudeForRms(FULL_VOLUME_RMS), ONE_SECOND), RATE);
    float before = leveller.gainAt(100);

    leveller.include(new float[] {0.01f, -0.01f});

    assertEquals(before, leveller.gainAt(100), 0f);
  }

  @Test
  public void aClipShorterThanOneWindowIsStillMeasured() {
    assertTrue(LoudnessLeveller.measure(new float[] {0.5f, -0.5f, 0.5f}, RATE).gainAt(100) < 1f);
  }

  private static LoudnessLeveller streamedFor(float amplitude, double seconds) {
    LoudnessLeveller leveller = LoudnessLeveller.streaming(RATE);
    int chunk = RATE / 20;
    for (int i = 0; i < Math.round(seconds * 20); i++) {
      leveller.include(sine(amplitude, chunk));
    }
    return leveller;
  }

  @Test
  public void aStreamedLineStartsAtItsRawLevel() {
    assertEquals(1f, LoudnessLeveller.streaming(RATE).gainAt(100), 0f);
  }

  @Test
  public void aStreamedLineSlidesAtMostThreeDecibelsPerSecond() {
    float quiet = amplitudeForRms(FULL_VOLUME_RMS / 4);

    assertEquals(3f, db(streamedFor(quiet, 1).gainAt(100)), DB_TOLERANCE);
    assertEquals(6f, db(streamedFor(quiet, 2).gainAt(100)), DB_TOLERANCE);
  }

  @Test
  public void aStreamedLineSettlesOnTheWholeLineLevel() {
    float[] line = sine(amplitudeForRms(FULL_VOLUME_RMS / 2), ONE_SECOND * 3);
    float whole = LoudnessLeveller.measure(line, RATE).gainAt(100);

    assertEquals(
        db(whole),
        db(streamedFor(amplitudeForRms(FULL_VOLUME_RMS / 2), 3).gainAt(100)),
        DB_TOLERANCE);
  }

  @Test
  public void aStreamedLineLocksAfterThreeSecondsOfSpeech() {
    float quiet = amplitudeForRms(FULL_VOLUME_RMS / 10);
    LoudnessLeveller leveller = streamedFor(quiet, 3);
    float locked = leveller.gainAt(100);

    leveller.include(sine(quiet, ONE_SECOND * 2));

    assertEquals(9f, db(locked), DB_TOLERANCE);
    assertEquals(locked, leveller.gainAt(100), 0f);
  }

  @Test
  public void silenceNeitherMovesNorLocksAStreamedLine() {
    LoudnessLeveller leveller = LoudnessLeveller.streaming(RATE);
    leveller.include(new float[ONE_SECOND * 5]);

    assertEquals(1f, leveller.gainAt(100), 0f);
    leveller.include(sine(amplitudeForRms(FULL_VOLUME_RMS / 4), ONE_SECOND));
    assertTrue(leveller.gainAt(100) > 1f);
  }

  @Test
  public void theVolumeScalesAStreamedLineThroughoutTheSlide() {
    float quiet = amplitudeForRms(FULL_VOLUME_RMS / 4);
    for (double seconds : new double[] {0.1, 1, 2, 4}) {
      LoudnessLeveller leveller = streamedFor(quiet, seconds);
      assertEquals(leveller.gainAt(100) * 0.2f, leveller.gainAt(20), 1e-6f);
      assertEquals(0f, leveller.gainAt(0), 0f);
    }
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertEquals;

import javax.sound.sampled.AudioFormat;
import org.junit.Test;

public class PcmAudioTest {

  @Test
  public void producesTwoBytesPerSample() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {0f, 0f, 0f}, 0, 3, 1f);
    assertEquals(6, pcm.length);
  }

  @Test
  public void encodesSilenceAsZero() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {0f}, 0, 1, 1f);
    assertEquals(0, pcm[0]);
    assertEquals(0, pcm[1]);
  }

  @Test
  public void usesLittleEndianByteOrder() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {1f}, 0, 1, 1f);
    assertEquals((byte) 0xFF, pcm[0]);
    assertEquals((byte) 0x7F, pcm[1]);
  }

  @Test
  public void clampsValuesAboveOne() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {2f}, 0, 1, 1f);
    assertEquals((byte) 0xFF, pcm[0]);
    assertEquals((byte) 0x7F, pcm[1]);
  }

  @Test
  public void clampsValuesBelowNegativeOne() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {-5f}, 0, 1, 1f);
    assertEquals((byte) 0x01, pcm[0]);
    assertEquals((byte) 0x80, pcm[1]);
  }

  @Test
  public void formatIsMono16BitSignedLittleEndian() {
    AudioFormat format = PcmAudio.format(24_000);
    assertEquals(24_000f, format.getSampleRate(), 0.0f);
    assertEquals(16, format.getSampleSizeInBits());
    assertEquals(1, format.getChannels());
    assertEquals(AudioFormat.Encoding.PCM_SIGNED, format.getEncoding());
    assertEquals(false, format.isBigEndian());
  }

  @Test
  public void appliesTheGainBeforeConverting() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {0.25f}, 0, 1, 2f);
    assertEquals(16384, (pcm[0] & 0xff) | (pcm[1] << 8));
  }

  @Test
  public void clampsSamplesTheGainPushesPastFullScale() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {0.75f}, 0, 1, 2f);
    assertEquals((byte) 0xFF, pcm[0]);
    assertEquals((byte) 0x7F, pcm[1]);
  }

  @Test
  public void convertsOnlyTheRequestedRange() {
    byte[] pcm = PcmAudio.toPcm16LE(new float[] {1f, 0.5f, 1f}, 1, 2, 1f);
    assertEquals(2, pcm.length);
    assertEquals(16384, (pcm[0] & 0xff) | (pcm[1] << 8));
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;

public class PcmCompletenessTest {

  private static final int RATE = 24_000;

  private static Pcm clip(int speechSamples, int trailingSilenceSamples) {
    float[] s = new float[speechSamples + trailingSilenceSamples];
    Arrays.fill(s, 0, speechSamples, 0.5f);
    return new Pcm(s, RATE);
  }

  @Test
  public void aLineThatReleasesIntoTrailingSilenceIsComplete() {
    assertFalse(PcmCompleteness.isTruncated(clip(48_000, 4_800), 1.0));
  }

  @Test
  public void aLineThatEndsMidSignalIsTruncated() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 0), 1.0));
  }

  @Test
  public void aLineWithTooLittleTrailingSilenceIsTruncated() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 960), 1.0));
  }

  @Test
  public void aClipTooShortToJudgeIsLeftAlone() {
    assertFalse(PcmCompleteness.isTruncated(clip(2_400, 0), 1.0));
  }

  @Test
  public void emptyAudioIsNotFlagged() {
    assertFalse(PcmCompleteness.isTruncated(new Pcm(new float[0], RATE), 1.0));
  }

  @Test
  public void nonPositiveRateIsNotFlagged() {
    assertFalse(PcmCompleteness.isTruncated(new Pcm(new float[48_000], 0), 1.0));
  }

  @Test
  public void aFastLineIsNotFlaggedWhenItsTrailingSilenceScalesWithPace() {
    assertTrue(
        "short trailing silence is a cut at default pace",
        PcmCompleteness.isTruncated(clip(48_000, 1_500), 1.0));
    assertFalse(
        "the same buffer is complete once the window is scaled for 2x pace",
        PcmCompleteness.isTruncated(clip(48_000, 1_500), 2.0));
  }

  @Test
  public void aSlowLineRequiresProportionallyMoreTrailingSilence() {
    assertFalse(
        "200 ms of quiet is a clean ending at default pace",
        PcmCompleteness.isTruncated(clip(48_000, 4_800), 1.0));
    assertTrue(
        "the same buffer is short of the pace-scaled window at 0.5x",
        PcmCompleteness.isTruncated(clip(48_000, 4_800), 0.5));
  }

  @Test
  public void aNonPositiveSpeedRatioFallsBackToDefaultPace() {
    assertTrue(PcmCompleteness.isTruncated(clip(48_000, 1_500), 0.0));
    assertFalse(PcmCompleteness.isTruncated(clip(48_000, 4_800), -1.0));
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class RawPcmDecoderTest {

  @Test
  public void decodesSampleCountAndCarriesGivenRate() {
    short[] samples = {0, 16384, -16384, 32767, -32768};
    Pcm pcm = RawPcmDecoder.decode(TestPcm.raw(samples), 24_000);
    assertEquals("the caller-provided rate is carried through", 24_000, pcm.getSampleRate());
    assertEquals("one float per 16-bit sample", samples.length, pcm.getSamples().length);
  }

  @Test
  public void converts16BitToFloatRange() {
    short[] samples = {0, 16384, -16384, -32768};
    float[] f = RawPcmDecoder.decode(TestPcm.raw(samples), 24_000).getSamples();
    assertEquals(0f, f[0], 1e-6);
    assertEquals(0.5f, f[1], 1e-3);
    assertEquals(-0.5f, f[2], 1e-3);
    assertEquals(-1.0f, f[3], 1e-6);
    for (float v : f) {
      assertTrue("samples stay within [-1, 1]", v >= -1f && v <= 1f);
    }
  }

  @Test
  public void usesWhateverRateTheCallerPasses() {
    Pcm pcm = RawPcmDecoder.decode(TestPcm.raw(new short[] {1, 2, 3}), 48_000);
    assertEquals("the decoder does not coerce the rate", 48_000, pcm.getSampleRate());
  }

  @Test
  public void rejectsOddByteCount() {
    assertNull(
        "an odd byte count is not whole 16-bit samples",
        RawPcmDecoder.decode(new byte[] {1, 2, 3}, 24_000));
  }

  private Object[] rejectedInputs() {
    return new Object[] {
      new Object[] {null, 24_000},
      new Object[] {new byte[] {1}, 24_000},
      new Object[] {TestPcm.raw(new short[] {1}), 0},
    };
  }

  @Test
  @Parameters(method = "rejectedInputs")
  public void rejectsNullEmptyOrBadRate(byte[] data, int rate) {
    assertNull(RawPcmDecoder.decode(data, rate));
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static com.grahambartley.runelite.voiced.dialogue.audio.TestPcm.sine;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.timeout;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.SourceDataLine;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class StreamingAudioPlayerTest {

  private static final int LOW_RATE = 1_000;
  private static final int CHUNK = 20;
  private static final float QUIET = 0.02f;
  private static final int UNLEVELLED_PEAK = Math.round(QUIET * 32767f);

  private static List<Integer> writtenPeaks(SourceDataLine line, int writes) {
    ArgumentCaptor<byte[]> pcm = ArgumentCaptor.forClass(byte[].class);
    verify(line, timeout(2_000).times(writes)).write(pcm.capture(), anyInt(), anyInt());
    List<Integer> peaks = new ArrayList<>();
    for (byte[] written : pcm.getAllValues()) {
      peaks.add(TestPcm.peak16(written));
    }
    return peaks;
  }

  private static SourceDataLine lineThatAcceptsEverything() {
    SourceDataLine line = mock(SourceDataLine.class);
    when(line.write(any(byte[].class), anyInt(), anyInt())).thenAnswer(inv -> inv.getArgument(2));
    return line;
  }

  @Test
  public void streamsAllPcmThenDrainsAndClosesLine() throws Exception {
    SourceDataLine line = lineThatAcceptsEverything();
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);

    player.stream(new float[] {0f, 0f, 0f}, 24_000, 100);

    ArgumentCaptor<AudioFormat> format = ArgumentCaptor.forClass(AudioFormat.class);
    verify(line).open(format.capture());
    assertEquals(24_000f, format.getValue().getSampleRate(), 0f);
    assertEquals(16, format.getValue().getSampleSizeInBits());
    assertEquals(1, format.getValue().getChannels());
    verify(line).start();
    verify(line).write(any(byte[].class), eq(0), eq(6));
    verify(line).drain();
    verify(line).close();
  }

  @Test
  public void stopMidStreamHaltsFurtherWritesAndSkipsDrain() {
    SourceDataLine line = mock(SourceDataLine.class);
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);
    when(line.write(any(byte[].class), anyInt(), anyInt()))
        .thenAnswer(
            inv -> {
              player.stop();
              return inv.getArgument(2);
            });

    player.stream(new float[5_000], 24_000, 100);

    verify(line, times(1)).write(any(byte[].class), anyInt(), anyInt());
    verify(line, never()).drain();
  }

  @Test
  public void streamedChunksOpenTheLineOnceThenDrainAndClose() throws Exception {
    SourceDataLine line = lineThatAcceptsEverything();
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);

    AudioOutput.AudioStream stream = player.beginStream(100);
    stream.write(new float[] {0f, 0f, 0f}, LOW_RATE);
    stream.write(new float[] {0f, 0f}, LOW_RATE);
    stream.end();

    ArgumentCaptor<AudioFormat> format = ArgumentCaptor.forClass(AudioFormat.class);
    verify(line, timeout(2_000)).open(format.capture());
    assertEquals(LOW_RATE, format.getValue().getSampleRate(), 0f);
    verify(line, timeout(2_000)).start();
    verify(line, timeout(2_000).times(2)).write(any(byte[].class), anyInt(), anyInt());
    verify(line, timeout(2_000)).drain();
    verify(line, timeout(2_000)).close();
  }

  @Test
  public void anEmptyLeadingChunkDoesNotOpenTheLine() {
    StreamingAudioPlayer.LineFactory factory = mock(StreamingAudioPlayer.LineFactory.class);
    StreamingAudioPlayer player = new StreamingAudioPlayer(factory);

    AudioOutput.AudioStream stream = player.beginStream(100);
    stream.write(new float[0], 24_000);
    stream.write(null, 24_000);

    verifyNoInteractions(factory);
  }

  private static SourceDataLine lineSignalingWrites(CountDownLatch wrote) {
    SourceDataLine line = mock(SourceDataLine.class);
    when(line.write(any(byte[].class), anyInt(), anyInt()))
        .thenAnswer(
            inv -> {
              wrote.countDown();
              return inv.getArgument(2);
            });
    return line;
  }

  @Test
  public void stopMidStreamDropsRemainingChunksSkipsDrainAndReleases() throws Exception {
    CountDownLatch wrote = new CountDownLatch(1);
    SourceDataLine line = lineSignalingWrites(wrote);
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);

    AudioOutput.AudioStream stream = player.beginStream(100);
    stream.write(new float[] {0f, 0f, 0f}, LOW_RATE);
    assertTrue("the first chunk reached the line", wrote.await(2, TimeUnit.SECONDS));
    player.stop();
    stream.write(new float[] {0f, 0f}, LOW_RATE);
    stream.end();

    verify(line, timeout(2_000)).close();
    verify(line, never()).drain();
    verify(line, times(1)).write(any(byte[].class), anyInt(), anyInt());
  }

  @Test
  public void aNewerLineSupersedesAnInProgressStream() throws Exception {
    CountDownLatch wrote = new CountDownLatch(1);
    SourceDataLine line = lineSignalingWrites(wrote);
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);

    AudioOutput.AudioStream first = player.beginStream(100);
    first.write(new float[] {0f, 0f}, LOW_RATE);
    assertTrue(wrote.await(2, TimeUnit.SECONDS));
    player.beginStream(100);
    first.write(new float[] {0f, 0f}, LOW_RATE);
    first.end();

    verify(line, timeout(2_000)).close();
    verify(line, never()).drain();
    verify(line, times(1)).write(any(byte[].class), anyInt(), anyInt());
  }

  @Test
  public void emptySamplesNeverTouchTheAudioLine() {
    StreamingAudioPlayer.LineFactory factory = mock(StreamingAudioPlayer.LineFactory.class);
    StreamingAudioPlayer player = new StreamingAudioPlayer(factory);

    player.stream(new float[0], 24_000, 100);
    player.stream(null, 24_000, 100);

    verifyNoInteractions(factory);
  }

  @Test
  public void theVolumeScalesWhatIsWritten() {
    SourceDataLine full = lineThatAcceptsEverything();
    SourceDataLine half = lineThatAcceptsEverything();

    new StreamingAudioPlayer(format -> full).stream(sine(QUIET, 480), 24_000, 100);
    new StreamingAudioPlayer(format -> half).stream(sine(QUIET, 480), 24_000, 50);

    assertEquals(writtenPeaks(full, 1).get(0) / 2.0, writtenPeaks(half, 1).get(0), 2);
  }

  @Test
  public void zeroVolumeWritesSilence() {
    SourceDataLine line = lineThatAcceptsEverything();

    new StreamingAudioPlayer(format -> line).stream(sine(QUIET, 480), 24_000, 0);

    assertEquals(0, (int) writtenPeaks(line, 1).get(0));
  }

  @Test
  public void aVolumeChangeReachesTheRestOfAPlayingLine() {
    SourceDataLine line = mock(SourceDataLine.class);
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);
    when(line.write(any(byte[].class), anyInt(), anyInt()))
        .thenAnswer(
            inv -> {
              player.setVolume(0);
              return inv.getArgument(2);
            });

    player.stream(sine(QUIET, 5_000), 24_000, 100);

    List<Integer> peaks = writtenPeaks(line, 3);
    assertTrue(peaks.get(0) > 0);
    assertEquals(0, (int) peaks.get(1));
    assertEquals(0, (int) peaks.get(2));
  }

  @Test
  public void theLineGainControlIsNeverTouched() {
    SourceDataLine line = lineThatAcceptsEverything();

    new StreamingAudioPlayer(format -> line).stream(sine(QUIET, 480), 24_000, 50);

    verify(line, never()).getControl(any());
    verify(line).drain();
  }

  @Test
  public void aWholeClipIsLevelledBeforeItPlays() {
    SourceDataLine line = lineThatAcceptsEverything();
    StreamingAudioPlayer player = new StreamingAudioPlayer(format -> line);

    player.stream(sine(QUIET, 480), 24_000, 100);

    assertTrue(writtenPeaks(line, 1).get(0) > UNLEVELLED_PEAK * 2);
  }

  private static AudioOutput.AudioStream streamOf(SourceDataLine line, int volume) {
    return new StreamingAudioPlayer(format -> line).beginStream(volume);
  }

  private static void writeQuietChunks(AudioOutput.AudioStream stream, int count) {
    for (int i = 0; i < count; i++) {
      stream.write(sine(QUIET, CHUNK), LOW_RATE);
    }
  }

  @Test
  public void aStreamedLineStartsAtItsRawLevelWithoutWaiting() {
    SourceDataLine line = lineThatAcceptsEverything();
    AudioOutput.AudioStream stream = streamOf(line, 100);

    stream.write(sine(QUIET, CHUNK), LOW_RATE);

    assertEquals(UNLEVELLED_PEAK, writtenPeaks(line, 1).get(0), UNLEVELLED_PEAK * 0.02);
    stream.end();
  }

  @Test
  public void aStreamedLineSlidesGentlyTowardsTheLevel() {
    SourceDataLine line = lineThatAcceptsEverything();
    AudioOutput.AudioStream stream = streamOf(line, 100);
    int oneSecondOfChunks = LOW_RATE / CHUNK;

    writeQuietChunks(stream, oneSecondOfChunks);
    stream.end();

    List<Integer> peaks = writtenPeaks(line, oneSecondOfChunks);
    double risenDb = 20 * Math.log10(peaks.get(peaks.size() - 1) / (double) peaks.get(0));
    assertEquals(3.0, risenDb, 0.3);
  }

  @Test
  public void theVolumeHoldsThroughoutTheSlide() {
    SourceDataLine full = lineThatAcceptsEverything();
    SourceDataLine fifth = lineThatAcceptsEverything();
    AudioOutput.AudioStream fullStream = streamOf(full, 100);
    AudioOutput.AudioStream fifthStream = streamOf(fifth, 20);
    int chunks = 2 * LOW_RATE / CHUNK;

    for (int i = 0; i < chunks; i++) {
      float[] chunk = sine(QUIET, CHUNK);
      fullStream.write(chunk, LOW_RATE);
      fifthStream.write(chunk, LOW_RATE);
    }
    fullStream.end();
    fifthStream.end();

    List<Integer> fullPeaks = writtenPeaks(full, chunks);
    List<Integer> fifthPeaks = writtenPeaks(fifth, chunks);
    for (int i = 0; i < chunks; i++) {
      assertEquals(fullPeaks.get(i) * 0.2, fifthPeaks.get(i), 1.5);
    }
  }

  @Test
  public void aStreamedLineThatSwellsIsLoweredRatherThanClipped() {
    SourceDataLine line = lineThatAcceptsEverything();
    AudioOutput.AudioStream stream = streamOf(line, 100);

    writeQuietChunks(stream, 3 * LOW_RATE / CHUNK);
    stream.write(sine(QUIET * 40, CHUNK), LOW_RATE);
    stream.end();

    List<Integer> peaks = writtenPeaks(line, 3 * LOW_RATE / CHUNK + 1);
    int ceiling = Math.round((float) Math.pow(10, -1.0 / 20) * 32767f);
    assertTrue(peaks.get(peaks.size() - 1) <= ceiling + 1);
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class StreamingPcmDecoderTest {

  private static float[] decodeInChunks(byte[] raw, int... chunkSizes) {
    StreamingPcmDecoder dec = new StreamingPcmDecoder();
    List<Float> all = new ArrayList<>();
    int off = 0;
    for (int size : chunkSizes) {
      int len = Math.min(size, raw.length - off);
      byte[] chunk = new byte[len];
      System.arraycopy(raw, off, chunk, 0, len);
      for (float f : dec.decode(chunk, len)) {
        all.add(f);
      }
      off += len;
    }
    float[] out = new float[all.size()];
    for (int i = 0; i < out.length; i++) {
      out[i] = all.get(i);
    }
    return out;
  }

  @Test
  public void reassemblesSamplesSplitAcrossChunkBoundaries() {
    short[] samples = {0, 16384, -16384, 32767, -32768, 1000, -1000, 12345};
    byte[] raw = TestPcm.raw(samples);
    float[] streamed = decodeInChunks(raw, 1, 3, 2, 5, 5);
    float[] whole = RawPcmDecoder.decode(raw, 24_000).getSamples();
    assertArrayEquals("streamed decode matches whole-buffer decode", whole, streamed, 1e-6f);
  }

  @Test
  public void handlesEverySampleStraddlingTwoChunks() {
    short[] samples = new short[64];
    for (int i = 0; i < samples.length; i++) {
      samples[i] = (short) (i * 500 - 16000);
    }
    byte[] raw = TestPcm.raw(samples);
    int[] oneByteEach = new int[raw.length];
    Arrays.fill(oneByteEach, 1);
    float[] streamed = decodeInChunks(raw, oneByteEach);
    float[] whole = RawPcmDecoder.decode(raw, 24_000).getSamples();
    assertArrayEquals(whole, streamed, 1e-6f);
  }

  @Test
  public void aWholeNumberOfSamplesLeavesNoPendingByte() {
    StreamingPcmDecoder dec = new StreamingPcmDecoder();
    byte[] raw = TestPcm.raw(new short[] {1, 2, 3});
    dec.decode(raw, raw.length);
    assertFalse("an even byte count is a whole number of samples", dec.hasPendingByte());
  }

  @Test
  public void anOddTrailingByteIsHeldAndReportedAsPending() {
    StreamingPcmDecoder dec = new StreamingPcmDecoder();
    byte[] whole = TestPcm.raw(new short[] {1, 2});
    byte[] withOdd = Arrays.copyOf(whole, whole.length + 1);
    withOdd[whole.length] = 0x7f;
    float[] out = dec.decode(withOdd, withOdd.length);
    assertEquals("only the whole samples are emitted", 2, out.length);
    assertTrue("the dangling byte is held pending (a truncated stream)", dec.hasPendingByte());
  }

  @Test
  public void emptyOrNullChunksEmitNothingAndKeepState() {
    StreamingPcmDecoder dec = new StreamingPcmDecoder();
    assertEquals(0, dec.decode(new byte[0], 0).length);
    assertEquals(0, dec.decode(null, 5).length);
    assertFalse(dec.hasPendingByte());
    dec.decode(new byte[] {0x10}, 1);
    assertTrue(dec.hasPendingByte());
    assertEquals("an empty chunk emits nothing", 0, dec.decode(new byte[0], 0).length);
    assertTrue("and does not drop the pending byte", dec.hasPendingByte());
  }
}

package com.grahambartley.runelite.voiced.dialogue.audio;

import java.io.ByteArrayOutputStream;

public final class TestPcm {

  private static final int SINE_PERIOD = 20;

  private TestPcm() {}

  public static byte[] raw(short[] samples) {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    for (short s : samples) {
      out.write(s & 0xff);
      out.write((s >> 8) & 0xff);
    }
    return out.toByteArray();
  }

  public static float[] sine(float amplitude, int samples) {
    float[] out = new float[samples];
    for (int i = 0; i < samples; i++) {
      out[i] = (float) (amplitude * Math.sin(2 * Math.PI * i / SINE_PERIOD));
    }
    return out;
  }

  public static float rms(float[] samples) {
    double energy = 0;
    for (float s : samples) {
      energy += (double) s * s;
    }
    return (float) Math.sqrt(energy / samples.length);
  }

  public static float peak(float[] samples) {
    float peak = 0f;
    for (float s : samples) {
      peak = Math.max(peak, Math.abs(s));
    }
    return peak;
  }

  public static int peak16(byte[] pcm) {
    int peak = 0;
    for (int i = 0; i + 1 < pcm.length; i += 2) {
      short s = (short) ((pcm[i] & 0xff) | (pcm[i + 1] << 8));
      peak = Math.max(peak, Math.abs(s));
    }
    return peak;
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileTime;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class DiskAudioCacheTest {

  private static final long MTIME_BASE = System.currentTimeMillis() - TimeUnit.HOURS.toMillis(1);

  @Rule public TemporaryFolder tmp = new TemporaryFolder();

  private Path cacheDir() {
    return tmp.getRoot().toPath().resolve("cache");
  }

  private static Pcm pcm(int sampleRate, float... samples) {
    return new Pcm(samples, sampleRate);
  }

  @Test
  public void missWhenNothingStored() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    assertNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello"));
  }

  @Test
  public void aLinesFileNameIsTheDocumentedHashAndNeverChangesAcrossReleases() {
    new DiskAudioCache(cacheDir())
        .put(
            "cloud-speech",
            "en-gb-tutor-9",
            Emotion.NEUTRAL,
            "What can I do yer for?",
            pcm(24_000, 0.1f));

    assertTrue(
        Files.exists(
            cacheDir()
                .resolve("f0135745b1888237ffd10143f3c367b164a3bc62a4216486b639cd10af97c85e.tdc")));
  }

  @Test
  public void roundTripsPcmAndPreservesSampleRate() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    Pcm stored = pcm(48_000, 0.5f, -0.25f, 1.0f, -1.0f, 0.0f);
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello", stored);

    Pcm read = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Hello");
    assertNotNull(read);
    assertEquals("sample rate must survive disk round-trip", 48_000, read.getSampleRate());
    assertArrayEquals(stored.getSamples(), read.getSamples(), 0.0f);
  }

  @Test
  public void survivesAcrossFreshCacheInstance() {
    Pcm stored = pcm(24_000, 0.1f, -0.1f);
    new DiskAudioCache(cacheDir())
        .put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Persist me", stored);

    Pcm read =
        new DiskAudioCache(cacheDir())
            .get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Persist me");
    assertNotNull("a fresh session should still find the line on disk", read);
    assertArrayEquals(stored.getSamples(), read.getSamples(), 0.0f);
  }

  @Test
  public void differentEmotionDoesNotCollide() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Halt", pcm(24_000, 0.1f));
    cache.put("cloud-openrouter", "npc:HUMAN:MALE", Emotion.ANGRY, "Halt", pcm(24_000, 0.9f));

    Pcm neutral = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Halt");
    Pcm angry = cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.ANGRY, "Halt");
    assertArrayEquals(new float[] {0.1f}, neutral.getSamples(), 0.0f);
    assertArrayEquals(new float[] {0.9f}, angry.getSamples(), 0.0f);
  }

  @Test
  public void differentBackendDoesNotCollide() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings", pcm(24_000, 0.2f));
    cache.put("other-backend", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings", pcm(24_000, 0.8f));

    assertArrayEquals(
        new float[] {0.2f},
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings").getSamples(),
        0.0f);
    assertArrayEquals(
        new float[] {0.8f},
        cache.get("other-backend", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Greetings").getSamples(),
        0.0f);
  }

  @Test
  public void corruptFileIsTreatedAsMissAndDeleted() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom", pcm(24_000, 0.3f, 0.4f));

    Path entry = onlyEntry(cacheDir());
    Files.write(entry, "not a valid cache file".getBytes(StandardCharsets.UTF_8));

    assertNull(
        "a corrupt file must read as a miss, not crash",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom"));
    assertTrue("the corrupt file should be deleted on miss", Files.notExists(entry));

    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom", pcm(24_000, 0.3f, 0.4f));
    assertNotNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Boom"));
  }

  @Test
  public void truncatedFileIsTreatedAsMiss() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter",
        "npc:HUMAN:MALE",
        Emotion.NEUTRAL,
        "Cut",
        pcm(24_000, 0.3f, 0.4f, 0.5f));

    Path entry = onlyEntry(cacheDir());
    byte[] full = Files.readAllBytes(entry);
    Files.write(entry, java.util.Arrays.copyOf(full, full.length - 4));

    assertNull(cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Cut"));
  }

  @Test
  public void evictionKeepsUsageBoundedAndDropsOldest() throws Exception {
    long cap = 600;
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap);

    float[] samples = new float[26];
    for (int i = 0; i < 12; i++) {
      putStamped(cache, "npc:HUMAN:MALE", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertTrue("total cache size must stay under the cap", dirSize(cacheDir()) <= cap);
    assertNull(
        "oldest line should be evicted",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "newest line should remain",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void unlimitedCapNeverEvicts() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), DiskAudioCache.UNLIMITED);

    float[] samples = new float[26];
    for (int i = 0; i < 12; i++) {
      cache.put(
          "cloud-openrouter",
          "npc:HUMAN:MALE",
          Emotion.NEUTRAL,
          "line-" + i,
          new Pcm(samples, 24_000));
    }

    assertNotNull(
        "the oldest line survives under an unlimited cache",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the newest line survives too",
        cache.get("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void readDoesNotRescueAnEntryFromFifoEviction() throws Exception {
    long cap = 600;
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap);
    float[] samples = new float[26];

    putStamped(cache, "v", "first", new Pcm(samples, 24_000), 0);
    assertNotNull(
        "the oldest entry is present before the cache fills",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "first"));

    for (int i = 0; i < 5; i++) {
      putStamped(cache, "v", "fill-" + i, new Pcm(samples, 24_000), i + 1);
    }

    assertTrue("total cache size must stay under the cap", dirSize(cacheDir()) <= cap);
    assertNull(
        "the oldest entry is evicted FIFO even though it was read",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "first"));
    assertNotNull(
        "the newest entry survives", cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "fill-4"));
  }

  @Test
  public void readFailureDoesNotThrowWhenDirIsUnreadable() {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    assertNull(cache.get("x", "y", Emotion.NEUTRAL, "z"));
    cache.put("x", "y", Emotion.NEUTRAL, "z", new Pcm(new float[] {0f}, 24_000));
  }

  @Test
  public void storedBytesAreLittleEndianFloat32AfterTheHeader() throws IOException {
    DiskAudioCache cache = new DiskAudioCache(cacheDir());
    cache.put(
        "cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Bytes", pcm(24_000, 0.5f, -0.25f));

    byte[] stored = Files.readAllBytes(onlyEntry(cacheDir()));
    assertEquals("header(16) + 2 float32 samples", 16 + 2 * 4, stored.length);
    ByteBuffer buf = ByteBuffer.wrap(stored).order(ByteOrder.LITTLE_ENDIAN);
    assertEquals("magic \"TDC1\"", 0x54_44_43_31, buf.getInt());
    assertEquals("sample rate", 24_000, buf.getInt());
    assertEquals("sample count", 2, buf.getInt());
    assertEquals("reserved word", 0, buf.getInt());
    assertEquals(0.5f, buf.getFloat(), 0f);
    assertEquals(-0.25f, buf.getFloat(), 0f);
  }

  @Test
  public void loweringTheCapEvictsDownToItOnTheNextWrite() throws Exception {
    AtomicLong cap = new AtomicLong(DiskAudioCache.UNLIMITED);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 6; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }
    long grownTo = dirSize(cacheDir());
    assertTrue("the uncapped cache should hold every line", grownTo > 600);

    cap.set(600);
    putStamped(cache, "v", "after-the-change", new Pcm(samples, 24_000), 6);

    assertTrue("the lowered cap is enforced by the next write", dirSize(cacheDir()) <= 600);
    assertNull(
        "the oldest line goes first under the lowered cap",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the line that triggered the eviction survives it",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "after-the-change"));
  }

  @Test
  public void raisingTheCapEvictsNothing() throws Exception {
    AtomicLong cap = new AtomicLong(600);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 4; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    cap.set(64L * 1024 * 1024);
    for (int i = 4; i < 10; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertTrue(
        "the directory should now sit well past the cap it started with",
        dirSize(cacheDir()) > 600);
    for (int i = 0; i < 10; i++) {
      assertNotNull(
          "every line survives once the cap is raised above the directory size",
          cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-" + i));
    }
  }

  @Test
  public void switchingTheCapToUnlimitedStopsEviction() throws Exception {
    AtomicLong cap = new AtomicLong(600);
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), cap::get);
    float[] samples = new float[26];

    for (int i = 0; i < 8; i++) {
      putStamped(cache, "v", "capped-" + i, new Pcm(samples, 24_000), i);
    }
    assertTrue("the finite cap is enforced while it is set", dirSize(cacheDir()) <= 600);

    cap.set(DiskAudioCache.UNLIMITED);
    for (int i = 0; i < 8; i++) {
      putStamped(cache, "v", "uncapped-" + i, new Pcm(samples, 24_000), 8 + i);
    }

    assertTrue("nothing is evicted once the cap is lifted", dirSize(cacheDir()) > 600);
    for (int i = 0; i < 8; i++) {
      assertNotNull(
          "every line written after the cap is lifted survives",
          cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "uncapped-" + i));
    }
  }

  @Test
  public void aClipLargerThanTheCapIsNotKeptByTheWriteThatStoredIt() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), () -> 64L);

    cache.put(
        "cloud-openrouter", "v", Emotion.NEUTRAL, "oversized", new Pcm(new float[64], 24_000));

    assertNull(
        "a clip that alone exceeds the cap is evicted by its own write",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "oversized"));
  }

  @Test
  public void anUnlimitedSupplierNeverEvicts() throws Exception {
    DiskAudioCache cache = new DiskAudioCache(cacheDir(), () -> DiskAudioCache.UNLIMITED);
    float[] samples = new float[26];

    for (int i = 0; i < 12; i++) {
      putStamped(cache, "v", "line-" + i, new Pcm(samples, 24_000), i);
    }

    assertNotNull(
        "the oldest line survives an unlimited supplier",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-0"));
    assertNotNull(
        "the newest line survives too",
        cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "line-11"));
  }

  @Test
  public void theCapIsReadOncePerWriteSoOnePassEnforcesOneLimit() {
    AtomicInteger reads = new AtomicInteger();
    DiskAudioCache cache =
        new DiskAudioCache(
            cacheDir(),
            () -> {
              reads.incrementAndGet();
              return 600L;
            });

    cache.put("cloud-openrouter", "v", Emotion.NEUTRAL, "first", pcm(24_000, new float[26]));
    assertEquals("one write reads the cap once", 1, reads.get());

    cache.put("cloud-openrouter", "v", Emotion.NEUTRAL, "second", pcm(24_000, new float[26]));
    assertEquals("a second write reads it once more", 2, reads.get());
  }

  @Test
  public void aReadNeverConsultsTheCap() {
    AtomicInteger reads = new AtomicInteger();
    DiskAudioCache cache =
        new DiskAudioCache(
            cacheDir(),
            () -> {
              reads.incrementAndGet();
              return 600L;
            });

    assertNull(cache.get("cloud-openrouter", "v", Emotion.NEUTRAL, "absent"));
    assertEquals("a lookup has nothing to evict, so it never reads the cap", 0, reads.get());
  }

  private void putStamped(DiskAudioCache cache, String voiceKey, String text, Pcm pcm, int order)
      throws IOException {
    Set<Path> before = entries(cacheDir());
    cache.put("cloud-openrouter", voiceKey, Emotion.NEUTRAL, text, pcm);
    for (Path p : entries(cacheDir())) {
      if (!before.contains(p)) {
        Files.setLastModifiedTime(p, FileTime.fromMillis(MTIME_BASE + order * 1_000L));
      }
    }
  }

  private static Set<Path> entries(Path dir) throws IOException {
    Set<Path> paths = new HashSet<>();
    if (!Files.isDirectory(dir)) {
      return paths;
    }
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        paths.add(p);
      }
    }
    return paths;
  }

  private static Path onlyEntry(Path dir) throws IOException {
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        return p;
      }
    }
    throw new IllegalStateException("no cache entry found in " + dir);
  }

  private static long dirSize(Path dir) throws IOException {
    long total = 0;
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, "*.tdc")) {
      for (Path p : stream) {
        total += Files.size(p);
      }
    }
    return total;
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class LruCacheTest {

  @Test
  public void evictsLeastRecentlyUsedBeyondCapacity() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("b", 2);
    cache.put("c", 3);

    assertEquals(2, cache.size());
    assertFalse("oldest entry should be evicted", cache.containsKey("a"));
    assertTrue(cache.containsKey("b"));
    assertTrue(cache.containsKey("c"));
  }

  @Test
  public void readingAnEntryMarksItMostRecentlyUsed() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("b", 2);

    assertEquals(Integer.valueOf(1), cache.get("a"));
    cache.put("c", 3);

    assertTrue(cache.containsKey("a"));
    assertFalse("untouched entry should be evicted", cache.containsKey("b"));
    assertTrue(cache.containsKey("c"));
  }

  @Test
  public void putReplacesExistingValueWithoutGrowing() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    cache.put("a", 1);
    cache.put("a", 2);

    assertEquals(1, cache.size());
    assertEquals(Integer.valueOf(2), cache.get("a"));
  }

  @Test
  public void missingKeyReturnsNull() {
    LruCache<String, Integer> cache = new LruCache<>(2);
    assertNull(cache.get("nope"));
  }

  @Test(expected = IllegalArgumentException.class)
  public void rejectsNonPositiveCapacity() {
    new LruCache<String, Integer>(0);
  }
}

package com.grahambartley.runelite.voiced.dialogue.cache;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.audio.Pcm;
import com.grahambartley.runelite.voiced.dialogue.cache.TieredSynthesisCache.CacheKey;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class TieredSynthesisCacheTest {

  @Rule public TemporaryFolder tmp = new TemporaryFolder();

  private static final CacheKey KEY =
      new CacheKey("cloud-openrouter", "npc:HUMAN:MALE", Emotion.NEUTRAL, "Echo");

  private static final class CountingDiskCache extends DiskAudioCache {
    final AtomicInteger gets = new AtomicInteger();

    CountingDiskCache(Path dir) {
      super(dir);
    }

    @Override
    public Pcm get(String namespace, String voiceKey, Emotion emotion, String text) {
      gets.incrementAndGet();
      return super.get(namespace, voiceKey, emotion, text);
    }
  }

  private Path cacheDir() {
    return tmp.getRoot().toPath().resolve("cache");
  }

  private static Pcm pcm(float sample) {
    return new Pcm(new float[] {sample}, 24_000);
  }

  private static Pcm synthOnce(TieredSynthesisCache cache, CacheKey key, Pcm result) {
    return cache.withInFlight(key, () -> result, () -> {});
  }

  @Test
  public void anUnknownKeyMissesBothTiers() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    assertNull(cache.lookup(KEY));
    assertNull(cache.memoryHit(KEY));
  }

  @Test
  public void aSynthIsWrittenThroughToBothTiers() {
    DiskAudioCache disk = new DiskAudioCache(cacheDir());
    Pcm synthed = pcm(0.5f);
    synthOnce(new TieredSynthesisCache(8, disk), KEY, synthed);

    TieredSynthesisCache nextSession = new TieredSynthesisCache(8, new DiskAudioCache(cacheDir()));
    Pcm read = nextSession.lookup(KEY);
    assertNotNull("the line survives into a fresh session", read);
    assertEquals(0.5f, read.getSamples()[0], 0f);
  }

  @Test
  public void aDiskHitIsPromotedIntoMemory() {
    synthOnce(new TieredSynthesisCache(8, new DiskAudioCache(cacheDir())), KEY, pcm(0.5f));

    CountingDiskCache disk = new CountingDiskCache(cacheDir());
    TieredSynthesisCache cache = new TieredSynthesisCache(8, disk);

    assertNotNull("the first lookup falls through to disk", cache.lookup(KEY));
    assertEquals("which cost exactly one disk read", 1, disk.gets.get());
    assertNotNull("the promoted entry is now in the memory tier", cache.memoryHit(KEY));

    assertNotNull(cache.lookup(KEY));
    assertEquals("the replay never touches disk again", 1, disk.gets.get());
  }

  @Test
  public void memoryHitNeverReadsTheDiskTier() {
    synthOnce(new TieredSynthesisCache(8, new DiskAudioCache(cacheDir())), KEY, pcm(0.5f));

    CountingDiskCache disk = new CountingDiskCache(cacheDir());
    assertNull(new TieredSynthesisCache(8, disk).memoryHit(KEY));
    assertEquals("the game-thread-safe lookup must not reach the filesystem", 0, disk.gets.get());
  }

  @Test
  public void aFailedSynthIsNotCached() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, new DiskAudioCache(cacheDir()));

    assertNull(cache.withInFlight(KEY, () -> null, () -> {}));
    assertNull("nothing was written through", cache.lookup(KEY));
  }

  @Test
  public void aCacheWithNoDiskTierStillServesFromMemory() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    Pcm synthed = pcm(0.25f);

    assertSame(synthed, synthOnce(cache, KEY, synthed));
    assertSame(synthed, cache.lookup(KEY));
  }

  @Test
  public void concurrentIdenticalSynthsIssueExactlyOneBackendCall() throws Exception {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);
    CountDownLatch entered = new CountDownLatch(1);
    CountDownLatch release = new CountDownLatch(1);
    AtomicInteger calls = new AtomicInteger();
    AtomicBoolean waiterWasDeduped = new AtomicBoolean();
    Pcm canned = pcm(0.2f);

    Supplier<Pcm> slowSynth =
        () -> {
          calls.incrementAndGet();
          entered.countDown();
          try {
            release.await();
          } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
          }
          return canned;
        };

    AtomicReference<Pcm> first = new AtomicReference<>();
    AtomicReference<Pcm> second = new AtomicReference<>();
    AtomicBoolean ownerWasDeduped = new AtomicBoolean();
    Thread owner =
        new Thread(
            () -> first.set(cache.withInFlight(KEY, slowSynth, () -> ownerWasDeduped.set(true))));
    owner.start();
    assertTrue("owner reached the synth", entered.await(2, TimeUnit.SECONDS));

    Thread waiter =
        new Thread(
            () -> second.set(cache.withInFlight(KEY, slowSynth, () -> waiterWasDeduped.set(true))));
    waiter.start();
    while (waiter.getState() != Thread.State.WAITING) {
      Thread.onSpinWait();
    }
    release.countDown();
    owner.join(2_000);
    waiter.join(2_000);

    assertEquals("two simultaneous identical requests issue exactly one synth", 1, calls.get());
    assertNotNull("the owner produced audio", first.get());
    assertSame("the waiter reuses the owner's audio", first.get(), second.get());
    assertFalse("the owner ran the synth itself", ownerWasDeduped.get());
    assertTrue("the waiter was told it reused an in-flight synth", waiterWasDeduped.get());
  }

  @Test
  public void aKeyIsSynthesizableAgainOnceTheFirstSynthFinishes() {
    TieredSynthesisCache cache = new TieredSynthesisCache(8, null);

    try {
      cache.withInFlight(
          KEY,
          () -> {
            throw new IllegalStateException("backend blew up");
          },
          () -> {});
    } catch (IllegalStateException expected) {
    }

    Pcm retry = pcm(0.9f);
    assertSame("a retry after a failed synth is not blocked", retry, synthOnce(cache, KEY, retry));
    assertSame("and its result is cached", retry, cache.lookup(KEY));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.function.IntSupplier;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.OverheadTextChanged;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class AmbientChatterWatcherTest {

  private static final WorldPoint PLAYER_TILE = new WorldPoint(3200, 3200, 0);

  private final Client client = mock(Client.class);
  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);

  private boolean enabled = true;
  private boolean conversationOnScreen = false;
  private int volume = 100;

  private final AmbientChatterWatcher watcher =
      new AmbientChatterWatcher(
          client,
          new DialogueTextCleaner(new ProfanityFilter()),
          dispatcher,
          () -> enabled,
          () -> conversationOnScreen,
          () -> volume);

  @Before
  public void setUp() {
    Player local = mock(Player.class);
    when(local.getWorldLocation()).thenReturn(PLAYER_TILE);
    when(client.getLocalPlayer()).thenReturn(local);
  }

  @Test
  public void aNearbyNpcsOverheadLineIsSpokenInItsOwnVoice() {
    NPC hans = npc(3);

    watcher.onOverheadTextChanged(overhead(hans, "<col=ff0000>Lovely day!"));

    verify(dispatcher).speakAmbient(eq("Lovely day!"), eq(hans), any(IntSupplier.class));
  }

  @Test
  public void everyNpcInAChatteringCrowdIsVoiced() {
    for (int tilesAway = 1; tilesAway <= 12; tilesAway++) {
      watcher.onOverheadTextChanged(overhead(npc(tilesAway), "Line " + tilesAway));
    }

    verify(dispatcher, times(12)).speakAmbient(anyString(), any(NPC.class), any(IntSupplier.class));
  }

  @Test
  public void oneNpcRepeatingItselfIsVoicedEveryTime() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    watcher.onOverheadTextChanged(overhead(crier, "Come one, come all!"));

    verify(dispatcher, times(2)).speakAmbient(eq("Hear ye!"), eq(crier), any(IntSupplier.class));
    verify(dispatcher).speakAmbient(eq("Come one, come all!"), eq(crier), any(IntSupplier.class));
  }

  @Test
  public void anotherPlayersOverheadTextIsNeverSpoken() {
    Player other = mock(Player.class);
    when(other.getWorldLocation()).thenReturn(PLAYER_TILE);

    watcher.onOverheadTextChanged(overhead(other, "Selling whips"));

    verifyNothingSpoken();
  }

  @Test
  public void anNpcBeyondTheRenderedAreaIsIgnored() {
    watcher.onOverheadTextChanged(overhead(npc(AmbientEarshot.EARSHOT_TILES + 1), "Too far away"));

    verifyNothingSpoken();
  }

  @Test
  public void anNpcExactlyAtTheEdgeOfEarshotIsSpoken() {
    watcher.onOverheadTextChanged(overhead(npc(AmbientEarshot.EARSHOT_TILES), "Just in range"));

    verify(dispatcher).speakAmbient(eq("Just in range"), any(NPC.class), any(IntSupplier.class));
  }

  @Test
  public void anNpcOnAnotherPlaneIsIgnored() {
    NPC upstairs = mock(NPC.class);
    when(upstairs.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 1));

    watcher.onOverheadTextChanged(overhead(upstairs, "Up here"));

    verifyNothingSpoken();
  }

  @Test
  public void nothingIsSpokenWhileAConversationIsOnScreen() {
    conversationOnScreen = true;

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void theToggleIsReadLiveSoTurningItOffSilencesTheNextLine() {
    enabled = false;

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void anOverheadLineArrivingWhileLoggedOutIsIgnored() {
    when(client.getLocalPlayer()).thenReturn(null);

    watcher.onOverheadTextChanged(overhead(npc(1), "Lovely day!"));

    verifyNothingSpoken();
  }

  @Test
  public void aLineThatCleansAwayToNothingIsNotSpoken() {
    watcher.onOverheadTextChanged(overhead(npc(1), "<col=ff0000>"));

    verifyNothingSpoken();
  }

  @Test
  public void aNullOverheadLineIsIgnored() {
    watcher.onOverheadTextChanged(overhead(npc(1), null));

    verifyNothingSpoken();
  }

  private void verifyNothingSpoken() {
    verify(dispatcher, never()).speakAmbient(anyString(), any(NPC.class), any(IntSupplier.class));
  }

  private static NPC npc(int tilesAway) {
    NPC npc = mock(NPC.class);
    when(npc.getWorldLocation())
        .thenReturn(
            new WorldPoint(
                PLAYER_TILE.getX() + tilesAway, PLAYER_TILE.getY(), PLAYER_TILE.getPlane()));
    return npc;
  }

  private static OverheadTextChanged overhead(Actor actor, String text) {
    return new OverheadTextChanged(actor, text);
  }

  @Test
  public void aQuackOrABaaIsLeftUnvoiced() {
    watcher.onOverheadTextChanged(overhead(npc(2), "Baa baa"));
    watcher.onOverheadTextChanged(overhead(npc(2), "Quack!"));
    watcher.onOverheadTextChanged(overhead(npc(2), "Moooo"));

    verifyNothingSpoken();
  }

  @Test
  public void aSentenceThatMerelyMentionsANoiseIsStillVoiced() {
    NPC farmer = npc(2);

    watcher.onOverheadTextChanged(overhead(farmer, "Baa, said the sheep"));

    verify(dispatcher).speakAmbient(eq("Baa, said the sheep"), eq(farmer), any(IntSupplier.class));
  }

  @Test
  public void theVolumeHandedOverFadesWithTheSpeakersDistance() {
    volume = 100;
    NPC crier = npc(4);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));

    assertEquals(
        "the supplier reports the fade for the current distance",
        AmbientEarshot.volumeAt(100, 4),
        capturedVolume().getAsInt());
  }

  @Test
  public void theVolumeHandedOverFollowsTheSpeakerAsTheyWalkOff() {
    volume = 100;
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    int near = live.getAsInt();
    moveTo(crier, 12);

    assertTrue("walking away makes the line quieter", live.getAsInt() < near);
  }

  @Test
  public void aSpeakerLeavingEarshotAsksForTheLineToBeCut() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    moveTo(crier, AmbientEarshot.EARSHOT_TILES + 1);

    assertEquals(AmbientEarshot.OUT_OF_EARSHOT, live.getAsInt());
  }

  @Test
  public void aLineInFlightWhenThePlayerLogsOutAsksToBeCut() {
    NPC crier = npc(2);

    watcher.onOverheadTextChanged(overhead(crier, "Hear ye!"));
    IntSupplier live = capturedVolume();
    when(client.getLocalPlayer()).thenReturn(null);

    assertEquals(AmbientEarshot.OUT_OF_EARSHOT, live.getAsInt());
  }

  private IntSupplier capturedVolume() {
    ArgumentCaptor<IntSupplier> captor = ArgumentCaptor.forClass(IntSupplier.class);
    verify(dispatcher).speakAmbient(anyString(), any(NPC.class), captor.capture());
    return captor.getValue();
  }

  private static void moveTo(NPC npc, int tilesAway) {
    when(npc.getWorldLocation())
        .thenReturn(
            new WorldPoint(
                PLAYER_TILE.getX() + tilesAway, PLAYER_TILE.getY(), PLAYER_TILE.getPlane()));
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

