    when(client.getWidget(InterfaceID.ChatLeft.NAME)).thenReturn(nameWidget);
    when(nameWidget.isHidden()).thenReturn(false);
    when(nameWidget.getText()).thenReturn(" Hans ");
    assertEquals("Hans", reader.currentNpcName());
  }

  @Test
  public void fallsBackToTheInteractingNpcWhenNameWidgetAbsent() {
    when(client.getWidget(InterfaceID.ChatLeft.NAME)).thenReturn(null);
    Player local = mock(Player.class);
    Actor interacting = mock(Actor.class);
    when(client.getLocalPlayer()).thenReturn(local);
    when(local.getInteracting()).thenReturn(interacting);
    when(interacting.getName()).thenReturn("Guard");
    assertEquals("Guard", reader.currentNpcName());
  }

  @Test
  public void lastResortIsUnknownNpc() {
    when(client.getWidget(InterfaceID.ChatLeft.NAME)).thenReturn(null);
    when(client.getLocalPlayer()).thenReturn(null);
    assertEquals("Unknown NPC", reader.currentNpcName());
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import java.util.ArrayDeque;
import java.util.Deque;
import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class ExamineSpeakerTest {

  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);
  private final Deque<Runnable> deferred = new ArrayDeque<>();

  private boolean enabled = true;
  private boolean dialogueOpen = false;

  private final ExamineSpeaker speaker =
      new ExamineSpeaker(
          new DialogueTextCleaner(new ProfanityFilter()),
          dispatcher,
          () -> enabled,
          () -> dialogueOpen,
          deferred::add);

  private void tick() {
    while (!deferred.isEmpty()) {
      deferred.poll().run();
    }
  }

  private static ChatMessage message(ChatMessageType type, String text) {
    ChatMessage event = new ChatMessage();
    event.setType(type);
    event.setMessage(text);
    event.setMessageNode(mock(MessageNode.class));
    return event;
  }

  private void stampAfterPublishing(ChatMessageType type, String text) {
    ChatMessage event = message(type, text);
    speaker.onChatMessage(event);
    when(event.getMessageNode().getRuneLiteFormatMessage()).thenReturn(text);
  }

  private Object[] examineTypes() {
    return new Object[] {
      ChatMessageType.ITEM_EXAMINE, ChatMessageType.NPC_EXAMINE, ChatMessageType.OBJECT_EXAMINE
    };
  }

  @Test
  @Parameters(method = "examineTypes")
  public void everyExamineTypeIsVoicedThroughTheNarrator(ChatMessageType type) {
    speaker.onChatMessage(message(type, "It's a bucket of milk."));
    tick();

    verify(dispatcher).speakNarration("It's a bucket of milk.");
  }

  private Object[] nonExamineTypes() {
    return new Object[] {
      ChatMessageType.GAMEMESSAGE,
      ChatMessageType.PUBLICCHAT,
      ChatMessageType.MESBOX,
      ChatMessageType.DIALOG,
      ChatMessageType.NPC_SAY,
      ChatMessageType.SPAM,
      ChatMessageType.PRIVATECHAT,
      ChatMessageType.CLAN_CHAT,
      ChatMessageType.FRIENDSCHAT,
      ChatMessageType.WELCOME,
      ChatMessageType.CONSOLE,
      ChatMessageType.BROADCAST,
      ChatMessageType.TRADE,
      ChatMessageType.ENGINE,
      ChatMessageType.UNKNOWN
    };
  }

  @Test
  @Parameters(method = "nonExamineTypes")
  public void noOtherChatTypeIsEverVoiced(ChatMessageType type) {
    speaker.onChatMessage(message(type, "You feel something weird."));
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void aPluginsPriceLookupCannotTalkOverTheExamineTextItFollows() {
    speaker.onChatMessage(
        message(ChatMessageType.ITEM_EXAMINE, "4 doses of Prayer restore potion."));
    stampAfterPublishing(ChatMessageType.ITEM_EXAMINE, "Price of Prayer potion(4): 9,500 coins");
    tick();

    verify(dispatcher, times(1)).speakNarration("4 doses of Prayer restore potion.");
    verifyNoMoreInteractions(dispatcher);
  }

  @Test
  public void aLineMarkedOnlyAfterPublishingIsStillRecognisedAsAPluginsOwn() {
    stampAfterPublishing(ChatMessageType.NPC_EXAMINE, "Some plugin's annotation.");
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void decidingBeforeTheTickWouldVoiceAPluginsLine() {
    SynthesisDispatcher undeferredDispatcher = mock(SynthesisDispatcher.class);
    ExamineSpeaker undeferred =
        new ExamineSpeaker(
            new DialogueTextCleaner(new ProfanityFilter()),
            undeferredDispatcher,
            () -> true,
            () -> false,
            Runnable::run);

    ChatMessage event = message(ChatMessageType.ITEM_EXAMINE, "Price of something: 1 coin");
    undeferred.onChatMessage(event);
    when(event.getMessageNode().getRuneLiteFormatMessage())
        .thenReturn("Price of something: 1 coin");

    verify(undeferredDispatcher).speakNarration("Price of something: 1 coin");
  }

  @Test
  public void aNodelessEventIsTreatedAsGameAuthored() {
    ChatMessage event = new ChatMessage();
    event.setType(ChatMessageType.OBJECT_EXAMINE);
    event.setMessage("A beautiful old oak.");

    speaker.onChatMessage(event);
    tick();

    verify(dispatcher).speakNarration("A beautiful old oak.");
  }

  @Test
  public void switchedOffNothingIsVoicedAndNothingIsEvenQueued() {
    enabled = false;

    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "It's a bucket of milk."));

    assertTrue("an ignored examine does not queue work for the next tick", deferred.isEmpty());
    tick();
    verifyNoInteractions(dispatcher);
  }

  @Test
  public void switchingItBackOnTakesEffectOnTheNextExamine() {
    enabled = false;
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "It's a bucket of milk."));
    enabled = true;
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "It's a bucket of milk."));
    tick();

    verify(dispatcher, times(1)).speakNarration("It's a bucket of milk.");
  }

  @Test
  public void anOpenDialogueKeepsTheAudioChannel() {
    dialogueOpen = true;

    speaker.onChatMessage(message(ChatMessageType.NPC_EXAMINE, "A gruff dwarf."));
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void aDialogueOpeningDuringTheDeferralStillWins() {
    speaker.onChatMessage(message(ChatMessageType.NPC_EXAMINE, "A gruff dwarf."));
    dialogueOpen = true;
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void examineResumesOnceTheDialogueCloses() {
    dialogueOpen = true;
    speaker.onChatMessage(message(ChatMessageType.NPC_EXAMINE, "A gruff dwarf."));
    tick();
    dialogueOpen = false;
    speaker.onChatMessage(message(ChatMessageType.NPC_EXAMINE, "A gruff dwarf."));
    tick();

    verify(dispatcher, times(1)).speakNarration("A gruff dwarf.");
  }

  @Test
  public void markupIsStrippedBeforeVoicing() {
    speaker.onChatMessage(
        message(ChatMessageType.OBJECT_EXAMINE, "<col=ffffff>A gnarled old tree.</col>"));
    tick();

    verify(dispatcher).speakNarration("A gnarled old tree.");
  }

  @Test
  public void textThatCleansAwayToNothingIsNotVoiced() {
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, ""));
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "   "));
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "<col=ffffff></col>"));
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void aNullMessageIsIgnoredRatherThanThrowing() {
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, null));
    tick();

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void examiningTheSameThingTwiceVoicesItBothTimes() {
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "It's a bucket of milk."));
    tick();
    speaker.onChatMessage(message(ChatMessageType.ITEM_EXAMINE, "It's a bucket of milk."));
    tick();

    verify(dispatcher, times(2)).speakNarration("It's a bucket of milk.");
  }
}

package com.grahambartley.runelite.voiced.dialogue.capture;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.grahambartley.runelite.voiced.dialogue.profile.ProfanityFilter;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisDispatcher;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

public class NarrationWatcherTest {

  private final Client client = mock(Client.class);
  private final SynthesisDispatcher dispatcher = mock(SynthesisDispatcher.class);

  private boolean enabled = true;

  private final NarrationWatcher watcher =
      new NarrationWatcher(
          client, new DialogueTextCleaner(new ProfanityFilter()), dispatcher, () -> enabled);

  private Widget visibleWidget(String text) {
    Widget widget = mock(Widget.class);
    when(widget.isHidden()).thenReturn(false);
    when(widget.getText()).thenReturn(text);
    return widget;
  }

  private void showing(int widgetId, String text) {
    Widget box = visibleWidget(text);
    when(client.getWidget(widgetId)).thenReturn(box);
  }

  @Test
  public void anItemBoxIsNarratedOnceThenDeduped() {
    showing(InterfaceID.Objectbox.TEXT, "You find a key.");

    assertTrue("an open box reports the narration open", watcher.tick());
    watcher.tick();

    verify(dispatcher, times(1)).speakNarration("You find a key.");
  }

  @Test
  public void everyNarrationBoxKindIsNarrated() {
    showing(InterfaceID.Objectbox.TEXT, "You find a key.");
    showing(InterfaceID.ObjectboxDouble.TEXT, "You combine the halves.");
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    watcher.tick();

    verify(dispatcher).speakNarration("You find a key.");
    verify(dispatcher).speakNarration("You combine the halves.");
    verify(dispatcher).speakNarration("The door creaks open.");
  }

  @Test
  public void eachBoxIsDedupedAgainstItsOwnLastLineOnly() {
    Widget objectbox = mock(Widget.class);
    when(objectbox.isHidden()).thenReturn(false);
    when(objectbox.getText()).thenReturn("You feel a chill.");
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(objectbox);
    Widget messagebox = visibleWidget("You feel a chill.");
    when(client.getWidget(InterfaceID.Messagebox.TEXT)).thenReturn(null, messagebox);

    watcher.tick();
    watcher.tick();

    verify(dispatcher, times(2)).speakNarration("You feel a chill.");
  }

  @Test
  public void advancingAnItemBoxToItsNextLineNarratesTheNewLine() {
    Widget box = mock(Widget.class);
    when(box.isHidden()).thenReturn(false);
    when(box.getText()).thenReturn("You find a key.", "You find a rusty sword.");
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(box);

    watcher.tick();
    watcher.tick();

    verify(dispatcher).speakNarration("You find a key.");
    verify(dispatcher).speakNarration("You find a rusty sword.");
  }

  @Test
  public void reopeningABoxAfterAResetNarratesItAgain() {
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    watcher.tick();
    watcher.reset();
    watcher.tick();

    verify(dispatcher, times(2)).speakNarration("The door creaks open.");
  }

  @Test
  public void aHiddenOrAbsentBoxIsNeitherNarratedNorCountedAsOpen() {
    Widget hidden = mock(Widget.class);
    when(hidden.isHidden()).thenReturn(true);
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(hidden);

    assertFalse("nothing on screen means nothing open", watcher.tick());

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void anEmptyBoxIsNotNarrated() {
    showing(InterfaceID.Messagebox.TEXT, "");

    assertTrue("the box is still on screen", watcher.tick());

    verifyNoInteractions(dispatcher);
  }

  @Test
  public void markupIsStrippedBeforeNarrating() {
    showing(InterfaceID.Messagebox.TEXT, "<col=ffffff>The door creaks open.</col>");

    watcher.tick();

    verify(dispatcher).speakNarration("The door creaks open.");
  }

  @Test
  public void switchedOffItNarratesNothingAndReportsClosed() {
    enabled = false;
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    assertFalse("an ignored box must not hold the dialogue open", watcher.tick());

    verify(dispatcher, never()).speakNarration("The door creaks open.");
  }

  @Test
  public void switchingItBackOnResumesNarrationWithoutARestart() {
    enabled = false;
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    watcher.tick();
    enabled = true;
    watcher.tick();

    verify(dispatcher, times(1)).speakNarration("The door creaks open.");
  }

  @Test
  public void everyNarrationBoxKindCountsAsOnScreen() {
    assertFalse("no box is showing yet", watcher.isOnScreen());

    for (int widgetId :
        new int[] {
          InterfaceID.Objectbox.TEXT, InterfaceID.ObjectboxDouble.TEXT, InterfaceID.Messagebox.TEXT
        }) {
      Client freshClient = mock(Client.class);
      NarrationWatcher fresh =
          new NarrationWatcher(
              freshClient, new DialogueTextCleaner(new ProfanityFilter()), dispatcher, () -> true);
      Widget box = visibleWidget("Something happens.");
      when(freshClient.getWidget(widgetId)).thenReturn(box);

      assertTrue("widget " + widgetId + " should read as on screen", fresh.isOnScreen());
    }
  }

  @Test
  public void aHiddenNarrationBoxIsNotOnScreen() {
    Widget hidden = mock(Widget.class);
    when(hidden.isHidden()).thenReturn(true);
    when(client.getWidget(InterfaceID.Objectbox.TEXT)).thenReturn(hidden);

    assertFalse(watcher.isOnScreen());
  }

  @Test
  public void aBoxHoldsTheScreenEvenWhenNarrationVoicingIsOff() {
    enabled = false;
    showing(InterfaceID.Messagebox.TEXT, "The door creaks open.");

    assertFalse("an unvoiced box is never narrated", watcher.tick());
    assertTrue("but it is still on screen", watcher.isOnScreen());
    verifyNoInteractions(dispatcher);
  }
}

