package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.CategoryRule;
import com.grahambartley.runelite.voiced.dialogue.profile.NpcProfileLayers.Layer;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import org.junit.Test;

public class NpcProfileParserTest {

  private static NpcProfileLayers parse(String json) {
    return NpcProfileParser.parse(new JsonParser().parse(json).getAsJsonObject());
  }

  private static NpcProfileLayers parseWithSymbols(String symbolsJson) {
    return NpcProfileParser.parse(
        new JsonParser().parse("{}").getAsJsonObject(),
        new JsonParser().parse(symbolsJson).getAsJsonObject());
  }

  private static final String COMPLETE_DEFAULT =
      "\"default\":{\"name\":\"D\",\"accent\":\"A\",\"style\":\"S\",\"pace\":\"P\"}";

  @Test
  public void parsesTheCompleteDefault() {
    NpcProfileLayers layers = parse("{" + COMPLETE_DEFAULT + "}");
    assertEquals("D", layers.defaultProfile().name());
    assertEquals("A", layers.defaultProfile().accent());
    assertEquals("S", layers.defaultProfile().style());
    assertEquals("P", layers.defaultProfile().pace());
  }

  @Test
  public void anIncompleteDefaultFallsBackToTheBuiltInOne() {
    NpcProfileLayers layers = parse("{\"default\":{\"name\":\"D\"}}");
    assertEquals(NpcProfileLayers.BUILTIN_DEFAULT, layers.defaultProfile());
  }

  @Test
  public void aMissingDefaultFallsBackToTheBuiltInOne() {
    assertEquals(NpcProfileLayers.BUILTIN_DEFAULT, parse("{}").defaultProfile());
  }

  @Test
  public void layerMapsAreKeyedLowerCaseAndSkipComments() {
    NpcProfileLayers layers =
        parse(
            "{\"byRace\":{\"Troll\":{\"accent\":\"Brixton.\"},\"_comment\":{\"accent\":\"x\"}},"
                + "\"byEthnicity\":{\"Kharidian\":{\"accent\":\"Middle Eastern.\"}}}");

    assertEquals("Brixton.", layers.byRace().get("troll").accent());
    assertNull("a comment key is not a layer", layers.byRace().get("_comment"));
    assertEquals("Middle Eastern.", layers.byEthnicity().get("kharidian").accent());
  }

  @Test
  public void sparseLayersLeaveUnsetFieldsNullSoTheyInherit() {
    NpcProfileLayers layers = parse("{\"player\":{\"style\":\"Brave hero.\"}}");
    assertEquals("Brave hero.", layers.playerLayer().style());
    assertNull(layers.playerLayer().name());
    assertNull(layers.playerLayer().accent());
    assertNull(layers.playerLayer().pace());
  }

  @Test
  public void anEmptyStringFieldIsTreatedAsAbsent() {
    NpcProfileLayers layers = parse("{\"player\":{\"accent\":\"\"}}");
    assertNull(layers.playerLayer().accent());
  }

  @Test
  public void categoriesKeepDeclarationOrderAndLowerCasedKeywords() {
    NpcProfileLayers layers =
        parse(
            "{\"byCategory\":["
                + "{\"id\":\"vampyre\",\"keywords\":[\"Vampyre\"],\"accent\":\"Transylvanian.\"},"
                + "{\"id\":\"child\",\"keywords\":[\"Child\"],\"lifeStage\":\"child\"}]}");

    assertEquals(2, layers.byCategory().size());
    CategoryRule vampyre = layers.byCategory().get(0);
    assertEquals("vampyre", vampyre.id());
    assertEquals("vampyre", vampyre.keywords().get(0));
    assertEquals("Transylvanian.", vampyre.layer().accent());
    assertTrue("the child marker rides on the rule", layers.byCategory().get(1).child());
  }

  @Test
  public void categoriesWithoutKeywordsAreSkippedAndAnIdIsOptional() {
    NpcProfileLayers layers =
        parse(
            "{\"byCategory\":[{\"accent\":\"orphan\"},\"not an object\","
                + "{\"keywords\":[\"imp\"],\"style\":\"Squeaky.\"}]}");

    assertEquals(1, layers.byCategory().size());
    assertEquals("category", layers.byCategory().get(0).id());
  }

  @Test
  public void byIdSkipsCommentsAndNonNumericKeys() {
    NpcProfileLayers layers =
        parse(
            "{\"byId\":{\"_comment\":\"x\",\"nope\":{\"name\":\"N\"},\"100\":{\"name\":\"Vanstrom\"}}}");

    assertEquals(1, layers.byId().size());
    assertEquals("Vanstrom", layers.byId().get(100).name());
  }

  @Test
  public void theBundledResourceParses() {
    assertNotNull(NpcProfileParser.loadResource("/npc-voices.json"));
  }

  @Test
  public void aMissingResourceIsAnAbsentSection() {
    assertNull(NpcProfileParser.loadResource("/no-such-resource.json"));
  }

  @Test
  public void aResourceWithoutAProfilesSectionIsAbsent() {
    assertNull(NpcProfileParser.loadResource("/expression-emotions.json"));
  }

  @Test
  public void anEmptySectionParsesToEmptyLayers() {
    NpcProfileLayers layers = parse("{}");
    assertTrue(layers.byRace().isEmpty());
    assertTrue(layers.byEthnicity().isEmpty());
    assertTrue(layers.byCategory().isEmpty());
    assertTrue(layers.byId().isEmpty());
    assertNull(layers.playerLayer());
  }

  @Test
  public void symbolsAreKeyedByNumericId() {
    NpcProfileLayers layers =
        parseWithSymbols("{\"11911\":\"FAI_VARROCK_GUARD02\",\"11914\":\"FAI_VARROCK_GUARD02_F\"}");

    assertEquals(2, layers.symbols().size());
    assertEquals("FAI_VARROCK_GUARD02", layers.symbols().get(11911));
    assertEquals("FAI_VARROCK_GUARD02_F", layers.symbols().get(11914));
  }

  @Test
  public void symbolsSkipCommentsNonNumericKeysAndNonStringValues() {
    NpcProfileLayers layers =
        parseWithSymbols(
            "{\"_comment\":\"x\",\"nope\":\"GUARD\",\"1\":{\"a\":\"b\"},\"2\":[\"GUARD\"],"
                + "\"3\":null,\"4\":\"\",\"6\":123,\"7\":true,\"5\":\"HANS\"}");

    assertEquals(1, layers.symbols().size());
    assertEquals("HANS", layers.symbols().get(5));
  }

  @Test
  public void aMissingSymbolsSectionParsesToNoSymbols() {
    assertTrue(parse("{}").symbols().isEmpty());
  }

  @Test
  public void theBundledResourceCarriesSymbolsForIdsSharingAName() {
    NpcProfileLayers layers = NpcProfileParser.loadResource("/npc-voices.json");

    assertEquals("FAI_VARROCK_GUARD02", layers.symbols().get(11911));
    assertEquals("FAI_VARROCK_GUARD02_F", layers.symbols().get(11914));
    assertEquals("FAI_FALADOR_GUARD1", layers.symbols().get(3269));
    assertEquals("FAI_FALADOR_GUARD1_F", layers.symbols().get(11943));
  }

  @Test
  public void theBundledResourceGroupsNamesIgnoringCase() {
    NpcProfileLayers layers = NpcProfileParser.loadResource("/npc-voices.json");

    assertEquals("Gem merchant", layers.byId().get(8723).name());
    assertEquals("Gem Merchant", layers.byId().get(13336).name());
    assertNotNull(layers.symbols().get(8723));
    assertNotNull(layers.symbols().get(13336));
  }

  @Test
  public void theBundledResourceCarriesNoSymbolForAUniqueName() {
    NpcProfileLayers layers = NpcProfileParser.loadResource("/npc-voices.json");

    assertEquals("Hans", layers.byId().get(3105).name());
    assertNull(layers.symbols().get(3105));
  }

  @Test
  public void everyBundledSymbolBelongsToAnIdWhoseNameAnotherIdShares() {
    NpcProfileLayers layers = NpcProfileParser.loadResource("/npc-voices.json");
    Map<String, Integer> idsPerName = new HashMap<>();
    for (Layer layer : layers.byId().values()) {
      idsPerName.merge(layer.name().toLowerCase(Locale.ROOT), 1, Integer::sum);
    }

    for (Integer npcId : layers.symbols().keySet()) {
      Layer layer = layers.byId().get(npcId);
      assertNotNull("symbol id " + npcId + " has a byId profile", layer);
      assertTrue(
          "symbol id " + npcId + " shares its name " + layer.name(),
          idsPerName.get(layer.name().toLowerCase(Locale.ROOT)) > 1);
    }
  }

  @Test
  public void aLayerCarriesItsAge() {
    NpcProfileLayers layers = parse("{\"byId\":{\"3480\":{\"name\":\"Dr Harlow\",\"age\":65}}}");
    assertEquals(Integer.valueOf(65), layers.byId().get(3480).age());
  }

  @Test
  public void aLayerWithoutAnAgeHasNone() {
    NpcProfileLayers layers = parse("{\"byId\":{\"1\":{\"name\":\"Hans\"}}}");
    assertNull(layers.byId().get(1).age());
  }

  @Test
  public void anAgeOutsideTheHumanRangeOrNotANumberIsIgnored() {
    NpcProfileLayers layers =
        parse(
            "{\"byId\":{\"1\":{\"age\":0},\"2\":{\"age\":121},\"3\":{\"age\":\"old\"},"
                + "\"4\":{\"age\":1},\"5\":{\"age\":120}}}");
    assertNull(layers.byId().get(1).age());
    assertNull(layers.byId().get(2).age());
    assertNull(layers.byId().get(3).age());
    assertEquals(Integer.valueOf(1), layers.byId().get(4).age());
    assertEquals(Integer.valueOf(120), layers.byId().get(5).age());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Test;

public class NpcProfileTableTest {

  private static final String JSON =
      "{"
          + "\"default\":{\"name\":\"Default\",\"accent\":\"British RP.\",\"style\":\"Plain.\",\"pace\":\"Steady.\"},"
          + "\"player\":{\"name\":\"Adventurer\",\"style\":\"Brave hero.\"},"
          + "\"narrator\":{\"name\":\"Narrator\",\"style\":\"Measured storyteller.\"},"
          + "\"byRace\":{"
          + "\"Human\":{\"name\":\"Human\",\"accent\":\"British.\",\"style\":\"Ordinary.\"},"
          + "\"Troll\":{\"name\":\"Troll\",\"accent\":\"Brixton.\",\"style\":\"Big and dim.\"}},"
          + "\"byEthnicity\":{\"kharidian\":{\"accent\":\"Middle Eastern.\"}},"
          + "\"byCategory\":["
          + "{\"id\":\"vampyre\",\"keywords\":[\"vampyre\",\"vyre\"],\"name\":\"Vampyre\",\"accent\":\"Transylvanian.\",\"style\":\"Predatory.\"},"
          + "{\"id\":\"imp\",\"keywords\":[\"imp\"],\"name\":\"Imp\",\"style\":\"Squeaky.\"},"
          + "{\"id\":\"child\",\"keywords\":[\"child\",\"urchin\"],\"lifeStage\":\"child\","
          + "\"style\":\"Bright and young.\"}"
          + "],"
          + "\"byId\":{\"_comment\":\"x\",\"100\":{\"name\":\"Vanstrom\",\"style\":\"An ancient vampyre lord.\"}}"
          + "}";

  private static NpcProfileTable.Resolution resolve(
      NpcProfileTable table, Integer npcId, String npcName, String race, String ethnicity) {
    return table.resolveNpc(npcId, table.matchName(npcName), race, ethnicity, false, null);
  }

  private static boolean isChild(NpcProfileTable table, String npcName) {
    return table.matchName(npcName).child();
  }

  private static NpcProfileTable table() {
    JsonObject profiles = new JsonParser().parse(JSON).getAsJsonObject();
    return NpcProfileTable.fromProfilesJson(profiles);
  }

  @Test
  public void noMatchingLayerFallsBackToTheCompleteDefault() {
    CharacterProfile p = resolve(table(), null, "Random Bloke", null, null).profile();
    assertEquals("Default", p.name());
    assertEquals("British RP.", p.accent());
    assertEquals("Plain.", p.style());
    assertEquals("Steady.", p.pace());
  }

  @Test
  public void raceLayerOverridesDefaultAndInheritsUnsetFields() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Mountain Troll", "Troll", null);
    assertEquals("race:Troll", r.source());
    assertEquals("Troll", r.profile().name());
    assertEquals("Brixton.", r.profile().accent());
    assertEquals("Big and dim.", r.profile().style());
    assertEquals("pace falls through to the default", "Steady.", r.profile().pace());
  }

  @Test
  public void ethnicityAccentTintsPlainFolkOverTheRaceAccent() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Desert Trader", "Human", "kharidian");
    assertEquals("race:Human+ethnicity:kharidian", r.source());
    assertEquals(
        "the ethnicity accent wins for plain folk", "Middle Eastern.", r.profile().accent());
    assertEquals(
        "style stays the race style (ethnicity is accent-only)", "Ordinary.", r.profile().style());
  }

  @Test
  public void ethnicityIsSkippedForDistinctiveRaces() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Desert Troll", "Troll", "kharidian");
    assertEquals("ethnicity is not applied to a distinctive race", "race:Troll", r.source());
    assertEquals("Brixton.", r.profile().accent());
  }

  @Test
  public void aKeywordCategoryStillBeatsTheEthnicityAccent() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Feral Vampyre", "Human", "kharidian");
    assertEquals("race:Human+ethnicity:kharidian+keyword:vampyre", r.source());
    assertEquals("Transylvanian.", r.profile().accent());
  }

  @Test
  public void raceAndCategoryCombineStyleWhileTheCategoryAccentWins() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Vampyre Brute", "Troll", null);
    assertEquals("race:Troll+keyword:vampyre", r.source());
    assertEquals("the most specific name wins", "Vampyre", r.profile().name());
    assertEquals(
        "the category accent beats the race accent", "Transylvanian.", r.profile().accent());
    assertTrue("the race style is part of the blend", r.profile().style().contains("Big and dim."));
    assertTrue(
        "the category style is part of the blend", r.profile().style().contains("Predatory."));
  }

  @Test
  public void stackedStylesWithoutFullStopsAreSeparatedAsSentences() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"D\",\"accent\":\"British accent\","
                    + "\"style\":\"Plain\",\"pace\":\"Steady pace\"},"
                    + "\"byRace\":{\"Gnome\":{\"style\":\"Chatty and clever\"}},"
                    + "\"byId\":{\"7\":{\"style\":\"Regal and gracious!\"}}}")
            .getAsJsonObject();
    NpcProfileTable table = NpcProfileTable.fromProfilesJson(profiles);

    assertEquals(
        "Chatty and clever. Regal and gracious!",
        resolve(table, 7, "King", "Gnome", null).profile().style());
  }

  private static NpcProfileTable regionTable() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"D\",\"accent\":\"Southern\",\"voiceRegion\":\"SOUTHERN\","
                    + "\"style\":\"Plain\",\"pace\":\"Steady\"},"
                    + "\"byRace\":{\"Dwarf\":{\"accent\":\"Glasgow\",\"voiceRegion\":\"SCOTTISH\","
                    + "\"accentDetail\":\"Gruff Glaswegian.\"},"
                    + "\"Human\":{\"style\":\"An ordinary citizen.\"}},"
                    + "\"byEthnicity\":{\"tirannwn\":{\"accent\":\"Welsh\"},"
                    + "\"wilderness\":{\"accent\":\"Harsh\",\"style\":\"A hardened outlaw.\","
                    + "\"replaceStyle\":true}},"
                    + "\"byId\":{\"9\":{\"style\":\"Gruff\"},\"12\":{\"style\":\"A witch.\"},"
                    + "\"13\":{\"accent\":\"Plain\"}}}")
            .getAsJsonObject();
    return NpcProfileTable.fromProfilesJson(profiles);
  }

  @Test
  public void aChildMarkedByTheTableTakesTheChildLayerWithoutAChildName() {
    NpcProfileTable table = table();
    NpcProfileTable.Resolution named =
        table.resolveNpc(null, table.matchName("Shilop"), "Human", null, true, null);
    assertTrue(named.source().contains("lifeStage:child"));
    assertTrue(named.profile().style().contains("Bright and young."));
  }

  @Test
  public void aChildNamedAsOneTakesTheChildLayerOnce() {
    NpcProfileTable table = table();
    NpcProfileTable.Resolution keyword =
        table.resolveNpc(null, table.matchName("Street urchin"), "Human", null, true, null);
    assertTrue(keyword.source().contains("keyword:child"));
    assertFalse(keyword.source().contains("lifeStage:child"));
  }

  @Test
  public void theMostSpecificPitchWins() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"D\",\"accent\":\"A\",\"style\":\"S\",\"pace\":\"P\"},"
                    + "\"byRace\":{\"Goblin\":{\"pitch\":\"High\"}},"
                    + "\"byId\":{\"3\":{\"pitch\":\"Very high\"}}}")
            .getAsJsonObject();
    NpcProfileTable table = NpcProfileTable.fromProfilesJson(profiles);
    assertEquals("High", resolve(table, null, "Goblin", "Goblin", null).profile().pitch());
    assertEquals("Very high", resolve(table, 3, "Goblin", "Goblin", null).profile().pitch());
    assertEquals(null, resolve(table, null, "Man", "Human", null).profile().pitch());
  }

  @Test
  public void theVoiceRegionComesFromTheLayerThatSetTheWinningAccent() {
    assertEquals(
        "SCOTTISH", resolve(regionTable(), 9, "Dwarf", "Dwarf", null).profile().voiceRegion());
  }

  @Test
  public void anAccentWithNoRegionClearsTheRegionItOverrides() {
    CharacterProfile welsh = resolve(regionTable(), null, "Elf", "Human", "tirannwn").profile();
    assertEquals("Welsh", welsh.accent());
    assertEquals(null, welsh.voiceRegion());
  }

  @Test
  public void theAccentDetailComesFromTheLayerThatSetTheWinningAccent() {
    assertEquals(
        "Gruff Glaswegian.",
        resolve(regionTable(), 9, "Dwarf", "Dwarf", null).profile().accentDetail());
  }

  @Test
  public void anAccentWithoutDetailClearsTheDetailItOverrides() {
    assertEquals(null, resolve(regionTable(), 13, "Dwarf", "Dwarf", null).profile().accentDetail());
  }

  @Test
  public void aReplacingStyleDropsTheLessSpecificStylesAndKeepsTheMoreSpecificOnes() {
    CharacterProfile outlaw =
        resolve(regionTable(), 12, "Krystilia", "Human", "wilderness").profile();
    assertEquals("A hardened outlaw. A witch.", outlaw.style());
    assertEquals(
        "An ordinary citizen.",
        resolve(regionTable(), null, "Man", "Human", null).profile().style());
  }

  @Test
  public void anNpcWithNoAccentLayerKeepsTheDefaultRegion() {
    assertEquals(
        "SOUTHERN", resolve(regionTable(), null, "Man", "Human", null).profile().voiceRegion());
  }

  @Test
  public void multipleCategoriesAllCombine() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Imp Vampyre", null, null);
    assertEquals(
        "both categories appear in declaration order", "keyword:vampyre+keyword:imp", r.source());
    assertTrue(r.profile().style().contains("Predatory."));
    assertTrue(r.profile().style().contains("Squeaky."));
    assertEquals("the last category to set a name wins", "Imp", r.profile().name());
  }

  @Test
  public void perIdOverrideAddsOnTopAndWinsSingleValuedFields() {
    NpcProfileTable.Resolution r = resolve(table(), 100, "Vampyre Vanstrom", "Undead", null);
    assertEquals("every match contributes", "keyword:vampyre+id:100", r.source());
    assertEquals("the bespoke name wins", "Vanstrom", r.profile().name());
    assertTrue(
        "the category style is still in the blend", r.profile().style().contains("Predatory."));
    assertTrue(
        "the bespoke style is added on top",
        r.profile().style().contains("An ancient vampyre lord."));
    assertEquals(
        "accent the id entry did not set inherits from the matched keyword layer",
        "Transylvanian.",
        r.profile().accent());
  }

  @Test
  public void raceMatchingIsCaseInsensitive() {
    assertEquals("Troll", resolve(table(), null, "x", "TROLL", null).profile().name());
    assertEquals("Troll", resolve(table(), null, "x", "troll", null).profile().name());
  }

  @Test
  public void keywordMatchingRespectsWordBoundaries() {
    assertEquals(
        "'imp' must not match inside 'important'",
        "Default",
        resolve(table(), null, "Important Person", null, null).profile().name());
    assertEquals(
        "'imp' matches the whole word",
        "Imp",
        resolve(table(), null, "Imp", null, null).profile().name());
  }

  @Test
  public void wordContainsIsBoundedOnBothSides() {
    assertTrue(NpcProfileTable.wordContains("feral vampyre", "vampyre"));
    assertTrue(NpcProfileTable.wordContains("tztok-jad", "jad"));
    assertFalse(NpcProfileTable.wordContains("important", "imp"));
    assertFalse(NpcProfileTable.wordContains("shrimp", "imp"));
  }

  @Test
  public void playerProfileLayersOverDefaultThenConfigOverridesNonBlankFields() {
    NpcProfileTable t = table();

    CharacterProfile base = t.resolvePlayer(null, null, null);
    assertEquals("Adventurer", base.name());
    assertEquals("the player style comes from the player layer", "Brave hero.", base.style());
    assertEquals("accent inherits from the default", "British RP.", base.accent());

    CharacterProfile overridden = t.resolvePlayer("Pirate drawl.", "   ", "");
    assertEquals("a non-blank accent overrides", "Pirate drawl.", overridden.accent());
    assertEquals("a blank style inherits", "Brave hero.", overridden.style());
    assertEquals("a blank pace inherits", "Steady.", overridden.pace());
  }

  @Test
  public void narratorProfileLayersOverDefaultAndTakesNoConfiguredFields() {
    CharacterProfile narrator = table().resolveNarrator();

    assertEquals("Narrator", narrator.name());
    assertEquals(
        "the narrator style comes from the narrator layer",
        "Measured storyteller.",
        narrator.style());
    assertEquals("accent inherits from the default", "British RP.", narrator.accent());
    assertEquals("pace inherits from the default", "Steady.", narrator.pace());
  }

  @Test
  public void narratorProfileIsIdenticalEveryCallSoItsCacheKeyHolds() {
    NpcProfileTable t = table();
    assertEquals(t.resolveNarrator().cacheKey(), t.resolveNarrator().cacheKey());
  }

  @Test
  public void aTableWithNoNarratorLayerStillResolvesTheDefault() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"Default\",\"accent\":\"British RP.\","
                    + "\"style\":\"Plain.\",\"pace\":\"Steady.\"}}")
            .getAsJsonObject();

    CharacterProfile narrator = NpcProfileTable.fromProfilesJson(profiles).resolveNarrator();

    assertEquals("Default", narrator.name());
    assertEquals("Plain.", narrator.style());
  }

  @Test
  public void childAgeCategoryMarksMatchingNamesAsChildren() {
    NpcProfileTable t = table();
    assertTrue("'Child' matches the child category", isChild(t, "Child"));
    assertTrue("'Street urchin' matches the child category", isChild(t, "Street urchin"));
    assertFalse("an adult name is not a child", isChild(t, "Random Bloke"));
    assertFalse("a non-child category match is not a child", isChild(t, "Imp"));
    assertFalse("a null name is not a child", isChild(t, null));
  }

  @Test
  public void childCategoryStyleLayersOverTheRaceStyle() {
    NpcProfileTable.Resolution r = resolve(table(), null, "Troll child", "Troll", null);
    assertEquals("race:Troll+keyword:child", r.source());
    assertEquals("Big and dim. Bright and young.", r.profile().style());
    assertEquals(
        "the child category leaves the accent to the race", "Brixton.", r.profile().accent());
  }

  private static NpcProfileTable.Resolution resolveWith(
      NpcProfileTable table, Integer npcId, String race, NpcVoiceOverride override) {
    return table.resolveNpc(npcId, table.matchName("Npc"), race, null, false, override);
  }

  @Test
  public void aNullOverrideResolvesExactlyAsTheBundledTable() {
    NpcProfileTable table = regionTable();
    assertEquals(resolve(table, 9, "Dwarf", "Dwarf", null), resolveWith(table, 9, "Dwarf", null));
  }

  @Test
  public void anOverrideFieldBeatsTheBundledByIdLayer() {
    NpcProfileTable.Resolution r =
        resolveWith(
            table(),
            100,
            "Human",
            new NpcVoiceOverride("Mine", null, "A cheerful baker", null, null));
    assertEquals("Mine", r.profile().name());
    assertEquals(
        "the override style replaces every bundled style",
        "A cheerful baker.",
        r.profile().style());
    assertEquals("race:Human+id:100+override", r.source());
  }

  @Test
  public void aPartialOverridePatchesOnlyTheFieldsItSets() {
    CharacterProfile bundled = resolve(table(), 100, "Npc", "Human", null).profile();
    CharacterProfile patched =
        resolveWith(table(), 100, "Human", new NpcVoiceOverride(null, null, null, "Brisk.", null))
            .profile();
    assertEquals("Brisk.", patched.pace());
    assertEquals(bundled.name(), patched.name());
    assertEquals(bundled.accent(), patched.accent());
    assertEquals(bundled.style(), patched.style());
  }

  @Test
  public void anAccentOverrideDropsTheBundledAccentDetailButKeepsTheVoicePool() {
    CharacterProfile p =
        resolveWith(
                regionTable(), 9, "Dwarf", new NpcVoiceOverride(null, "Cockney", null, null, null))
            .profile();
    assertEquals("Cockney", p.accent());
    assertEquals(null, p.accentDetail());
    assertEquals("SCOTTISH", p.voiceRegion());
  }

  @Test
  public void anAccentOverrideMarksTheProfileAsAccentOverridden() {
    CharacterProfile p =
        resolveWith(
                regionTable(), 9, "Dwarf", new NpcVoiceOverride(null, "Cockney", null, null, null))
            .profile();
    assertTrue(p.accentOverridden());
  }

  @Test
  public void anOverrideWithoutAnAccentLeavesTheAccentBundled() {
    CharacterProfile p =
        resolveWith(
                regionTable(), 9, "Dwarf", new NpcVoiceOverride(null, null, "Gruff.", null, null))
            .profile();
    assertFalse(p.accentOverridden());
    assertFalse(resolveWith(regionTable(), 9, "Dwarf", null).profile().accentOverridden());
  }

  @Test
  public void aVoiceTypeOnlyOverrideLeavesTheProfileAndItsSourceUntouched() {
    NpcProfileTable table = regionTable();
    assertEquals(
        resolve(table, 9, "Dwarf", "Dwarf", null),
        resolveWith(
            table, 9, "Dwarf", new NpcVoiceOverride(null, null, null, null, VoiceType.TYPE_B)));
  }

  @Test
  public void anOverrideAppliesToAnNpcWithNoBundledByIdEntry() {
    NpcProfileTable.Resolution r =
        resolveWith(table(), 555, "Troll", new NpcVoiceOverride(null, "Geordie", null, null, null));
    assertEquals("Geordie", r.profile().accent());
    assertEquals("Troll", r.profile().name());
    assertEquals("race:Troll+override", r.source());
  }

  @Test
  public void anOverrideChangesTheProfileCacheKey() {
    NpcProfileTable table = table();
    assertFalse(
        resolve(table, 100, "Npc", "Human", null)
            .profile()
            .cacheKey()
            .equals(
                resolveWith(
                        table, 100, "Human", new NpcVoiceOverride(null, null, null, "Slow.", null))
                    .profile()
                    .cacheKey()));
  }

  @Test
  public void theBundledCatalogNamesByIdNpcsAndNothingElse() {
    NpcProfileTable table = new NpcProfileTable();
    table.initialize();
    NpcVoiceCatalog catalog = table.buildCatalog();

    assertEquals("Hans", catalog.nameOf(3105));
    assertNull(catalog.nameOf(-1));
  }

  @Test
  public void onlyAnNpcWithItsOwnByIdEntryHasABespokeProfile() {
    NpcProfileTable table = table();

    assertTrue(table.hasBespokeProfile(100));
    assertFalse(table.hasBespokeProfile(101));
  }

  @Test
  public void anUnloadedTableHasNoBespokeProfiles() {
    assertFalse(new NpcProfileTable().hasBespokeProfile(100));
  }

  @Test
  public void theMostSpecificAgeWins() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"D\",\"accent\":\"A\",\"style\":\"S\",\"pace\":\"P\"},"
                    + "\"byRace\":{\"Wizard\":{\"age\":60}},"
                    + "\"byId\":{\"3\":{\"age\":80}}}")
            .getAsJsonObject();
    NpcProfileTable table = NpcProfileTable.fromProfilesJson(profiles);
    assertEquals(
        Integer.valueOf(60), resolve(table, null, "Wizard", "Wizard", null).profile().age());
    assertEquals(Integer.valueOf(80), resolve(table, 3, "Wizard", "Wizard", null).profile().age());
    assertNull(resolve(table, null, "Man", "Human", null).profile().age());
  }

  @Test
  public void anOverrideKeepsTheBundledAge() {
    JsonObject profiles =
        new JsonParser()
            .parse(
                "{\"default\":{\"name\":\"D\",\"accent\":\"A\",\"style\":\"S\",\"pace\":\"P\"},"
                    + "\"byId\":{\"3\":{\"age\":65}}}")
            .getAsJsonObject();
    NpcProfileTable table = NpcProfileTable.fromProfilesJson(profiles);
    NpcVoiceOverride override =
        new NpcVoiceOverride(null, null, "A cheerful young lad", null, null);
    assertEquals(Integer.valueOf(65), resolveWith(table, 3, "Human", override).profile().age());
  }
}

package com.grahambartley.runelite.voiced.dialogue.profile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Answers;

public class NpcProfilesResourceTest {

  private NpcProfileTable table;

  private NpcProfileTable.Resolution resolve(
      Integer npcId, String npcName, String race, String ethnicity) {
    return table.resolveNpc(npcId, table.matchName(npcName), race, ethnicity, false, null);
  }

  private boolean isChild(String npcName) {
    return table.matchName(npcName).child();
  }

  @Before
  public void setUp() {
    table = new NpcProfileTable();
    table.initialize();
  }

  @Test
  public void theBundledProfilesSectionLoads() {
    assertTrue("the bundled profiles section loaded", table.isLoaded());
  }

  @Test
  public void everyRaceBucketResolvesToItsOwnLayer() {
    for (String race :
        new String[] {
          "Human",
          "Elf",
          "Dwarf",
          "Goblin",
          "Monkey",
          "Gorilla",
          "Troll",
          "Undead",
          "Demon",
          "Wizard",
          "Tortugan",
          "Icyene",
          "Arceuus",
          "Aranei",
          "Dog",
          "Crab",
          "Penguin"
        }) {
      assertEquals(
          "race " + race + " resolves to its own bucket",
          "race:" + race,
          resolve(null, "someone", race, null).source());
    }
  }

  @Test
  public void everythingDefaultsToABritishAccent() {
    CharacterProfile p = resolve(null, "A Nameless Stranger", null, null).profile();
    assertTrue("the default accent is British", p.accent().contains("British"));
  }

  @Test
  public void statedSpecialAccentsHold() {
    assertTrue(
        "trolls sound South London / Brixton",
        resolve(null, "Mountain Troll", "Troll", null).profile().accent().contains("Brixton"));
    assertTrue(
        "dwarves sound Scottish",
        resolve(null, "Dwarf Miner", "Dwarf", null).profile().accent().contains("Scottish"));
    assertTrue(
        "gnomes sound country Irish",
        resolve(null, "Gnome Child", "Gnome", null).profile().accent().contains("Irish"));
    assertTrue(
        "leprechauns sound Irish",
        resolve(null, "Tool Leprechaun", "Human", null).profile().accent().contains("Irish"));
    assertTrue(
        "vampyres sound Transylvanian / Dracula-esque",
        resolve(null, "Feral Vampyre", "Undead", null)
            .profile()
            .accent()
            .contains("Transylvanian"));
    assertTrue(
        "gorillas sound deep, not chattery island monkey",
        resolve(null, "Gorilla", "Gorilla", null).profile().accent().contains("deep"));
    assertTrue(
        "tortugans sound Bajan / Barbados",
        resolve(null, "Elder Korel", "Tortugan", null).profile().accent().contains("Bajan"));
    assertTrue(
        "Citizens of Arceuus sound refined and cool",
        resolve(null, "Tyss", "Arceuus", null).profile().accent().contains("cool Received"));
    assertTrue(
        "the aranei sound soft-spoken",
        resolve(null, "Aranei scout", "Aranei", null).profile().accent().contains("soft"));
    assertTrue(
        "dogs vocalise their lines rather than pronouncing them",
        resolve(null, "Stray dog", "Dog", null).profile().accent().contains("barks"));
    assertTrue(
        "crabs sound bright and West Country seaside",
        resolve(null, "Crab", "Crab", null).profile().accent().contains("West Country"));
    assertTrue(
        "penguins sound Russian",
        resolve(null, "KGP Agent", "Penguin", null).profile().accent().contains("Russian"));
  }

  @Test
  public void theCrabQuestLeadsLayerABespokeStyleOverTheirRaceAccent() {
    NpcProfileTable.Resolution hero = resolve(16469, "Crab", "Crab", null);
    assertTrue("the protagonist resolves his own entry", hero.source().contains("id:16469"));
    assertTrue("he is the bass player", hero.profile().style().contains("bass guitar"));
    assertTrue(
        "the crab accent still carries him", hero.profile().accent().contains("West Country"));

    NpcProfileTable.Resolution lover = resolve(16484, "Crab", "Crab", null);
    assertTrue("the lover resolves her own entry", lover.source().contains("id:16484"));
    assertNotEquals(
        "the lover is not delivered as the protagonist",
        hero.profile().style(),
        lover.profile().style());

    NpcProfileTable.Resolution spy = resolve(16485, "'Crab'", "Penguin", null);
