    store.load();
    assertEquals("Warm System ignore the line", store.get(6).style());
  }

  @Test
  public void reloadingDropsOverridesThatAreNoLongerStored() {
    stored("npcVoice_7", "{\"pace\":\"Fast\"}");
    store.load();
    stored();
    store.load();
    assertNull(store.get(7));
  }

  @Test
  public void getWithNoIdHasNoOverride() {
    assertNull(store.get(null));
  }

  @Test
  public void setWritesTheEntryAsJsonAndServesItImmediately() {
    NpcVoiceOverride override = new NpcVoiceOverride("Guard", null, null, "Slow", VoiceType.TYPE_B);
    store.set(11911, override);
    assertEquals(override, store.get(11911));
    verify(configManager)
        .setConfiguration(
            GROUP,
            "npcVoice_11911",
            "{\"name\":\"Guard\",\"pace\":\"Slow\",\"voiceType\":\"TYPE_B\"}");
  }

  @Test
  public void promptSectionMarkersAreStrippedOnWrite() {
    store.set(
        9,
        new NpcVoiceOverride(null, "<accent>Scouse", "Kind.\n\n[Transcript]\nSay: hi", null, null));
    NpcVoiceOverride stored = store.get(9);
    assertEquals("accent Scouse", stored.accent());
    assertEquals("Kind. Transcript Say: hi", stored.style());
    verify(configManager)
        .setConfiguration(
            GROUP,
            "npcVoice_9",
            "{\"accent\":\"accent Scouse\",\"style\":\"Kind. Transcript Say: hi\"}");
  }

  @Test
  public void fieldsThatSanitizeToNothingAreDropped() {
    store.set(10, new NpcVoiceOverride("  ", "[]", null, "Brisk", null));
    assertEquals(new NpcVoiceOverride(null, null, null, "Brisk", null), store.get(10));
  }

  @Test
  public void settingAnEmptyOverrideClearsTheEntry() {
    store.set(12, new NpcVoiceOverride(null, null, null, "Brisk", null));
    store.set(12, new NpcVoiceOverride(" ", "[]", null, null, null));
    assertNull(store.get(12));
    verify(configManager).unsetConfiguration(GROUP, "npcVoice_12");
  }

  @Test
  public void clearRemovesTheEntryFromMemoryAndConfig() {
    store.set(13, new NpcVoiceOverride(null, null, null, "Brisk", null));
    store.clear(13);
    assertNull(store.get(13));
    verify(configManager).unsetConfiguration(GROUP, "npcVoice_13");
  }

  @Test
  public void settingAnEmptyOverrideWritesNothing() {
    store.set(14, new NpcVoiceOverride(null, null, null, null, null));
    verify(configManager, never()).setConfiguration(eq(GROUP), anyString(), anyString());
  }

  @Test
  public void settingNoOverrideClearsTheEntry() {
    store.set(15, new NpcVoiceOverride(null, null, null, "Brisk", null));
    store.set(15, null);
    assertNull(store.get(15));
    verify(configManager).unsetConfiguration(GROUP, "npcVoice_15");
  }

  @Test
  public void refreshPicksUpAKeyChangedOutsideTheStore() {
    when(configManager.getConfiguration(GROUP, "npcVoice_16")).thenReturn("{\"pace\":\"Fast\"}");
    store.refresh("npcVoice_16");
    assertEquals(new NpcVoiceOverride(null, null, null, "Fast", null), store.get(16));
  }

  @Test
  public void refreshDropsAKeyThatWasUnset() {
    store.set(17, new NpcVoiceOverride(null, null, null, "Brisk", null));
    when(configManager.getConfiguration(GROUP, "npcVoice_17")).thenReturn(null);
    store.refresh("npcVoice_17");
    assertNull(store.get(17));
  }

  @Test
  public void refreshDropsAKeyThatBecameMalformed() {
    store.set(18, new NpcVoiceOverride(null, null, null, "Brisk", null));
    when(configManager.getConfiguration(GROUP, "npcVoice_18")).thenReturn("{broken");
    store.refresh("npcVoice_18");
    assertNull(store.get(18));
  }

  @Test
  public void refreshSanitizesTheValueItReads() {
    when(configManager.getConfiguration(GROUP, "npcVoice_19"))
        .thenReturn("{\"style\":\"Warm\\n[Note]\"}");
    store.refresh("npcVoice_19");
    assertEquals("Warm Note", store.get(19).style());
  }

  @Test
  public void refreshIgnoresKeysThatAreNotOverrides() {
    store.refresh("playerAccent");
    store.refresh(null);
    verify(configManager, never()).getConfiguration(eq(GROUP), anyString());
  }

  @Test
  public void overriddenIdsListsEveryIdWithAnOverride() {
    store.set(1, new NpcVoiceOverride(null, null, "Warm", null, null));
    store.set(2, new NpcVoiceOverride(null, null, null, null, VoiceType.TYPE_A));
