  }

  @Test
  public void guardVariantsResolveToTheGenderTheirCacheSymbolNames() {
    assertEquals("Female", analyze(11914, null).getGender());
    assertEquals("Female", analyze(11943, null).getGender());
    assertEquals("Male", analyze(11911, null).getGender());
    assertEquals("Male", analyze(3269, null).getGender());
  }

  @Test
  public void everyIdWhoseCacheSymbolNamesAGenderResolvesToIt() throws IllegalAccessException {
    List<String> mismatches = new ArrayList<>();
    int checked = 0;
    for (Field field : NpcID.class.getFields()) {
      if (field.getType() != int.class || !Modifier.isStatic(field.getModifiers())) {
        continue;
      }
      String symbolGender = symbolGender(field.getName());
      int npcId = field.getInt(null);
      if (symbolGender == null || !analyzer.isVoiced(npcId)) {
        continue;
      }
      checked++;
      String resolved = analyze(npcId, null).getGender();
      if (!symbolGender.equals(resolved)) {
        mismatches.add(npcId + " " + field.getName() + " resolves " + resolved);
      }
    }
    assertTrue("expected many gendered symbols in the table, checked " + checked, checked > 500);
    assertTrue("ids resolving against their symbol: " + mismatches, mismatches.isEmpty());
  }

  private static String symbolGender(String symbol) {
    Set<String> tokens = new HashSet<>(Arrays.asList(symbol.split("_")));
    boolean female = tokens.contains("F") || tokens.contains("FEMALE");
    boolean male = tokens.contains("M") || tokens.contains("MALE");
    if (female == male) {
      return null;
    }
    return female ? "Female" : "Male";
  }

  private void assertAttributes(int npcId, String expectedRace, String expectedGender) {
    NpcAttributes attributes = analyze(npcId, null);
    assertNotNull("expected a table entry for id " + npcId, attributes);
    assertEquals("race for id " + npcId, expectedRace, attributes.getRace());
    assertEquals("gender for id " + npcId, expectedGender, attributes.getGender());
  }

  @Test
  public void theProfileIdMatchesTheIdTheAttributesCarry() {
    int[][] cases = {{3105, 3105}, {999_000_001, 3105}, {999_000_001, 999_000_002}};
    for (int[] ids : cases) {
      NPC npc = npc(ids[0], ids[1], "Hans");
      assertEquals(analyzer.analyzeNPC(npc).getNpcId(), analyzer.profileIdOf(npc));
    }
  }

  @Test
  public void aTransformedNpcKnownOnlyByItsBaseIdUsesTheBaseId() {
    assertEquals(3105, analyzer.profileIdOf(npc(999_000_001, 3105, "Hans")));
  }

  @Test
  public void anUnknownNpcUsesItsActiveId() {
    assertEquals(999_000_001, analyzer.profileIdOf(npc(999_000_001, 999_000_002, "Nobody")));
  }

  @Test
  public void anNpcWithoutACompositionUsesItsActiveId() {
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(3105);
    when(npc.getComposition()).thenReturn(null);

    assertEquals(3105, analyzer.profileIdOf(npc));
  }

  private NpcAttributes analyze(int npcId, String npcName) {
    return analyze(npcId, npcId, npcName);
  }

  private NpcAttributes analyze(int activeId, int baseId, String npcName) {
    return analyzer.analyzeNPC(npc(activeId, baseId, npcName));
  }

  private static NPC npc(int activeId, int baseId, String npcName) {
    NPCComposition composition = mock(NPCComposition.class);
    when(composition.getId()).thenReturn(baseId);
    when(composition.getName()).thenReturn(npcName);
    NPC npc = mock(NPC.class);
    when(npc.getId()).thenReturn(activeId);
    when(npc.getComposition()).thenReturn(composition);
    return npc;
  }
}

