package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import junitparams.JUnitParamsRunner;
import junitparams.Parameters;
import org.junit.Test;
import org.junit.runner.RunWith;

@RunWith(JUnitParamsRunner.class)
public class CloudBackendSupportTest {

  private static final RetryTuning INSTANT =
      new RetryTuning(Duration.ofSeconds(1), Duration.ofSeconds(1), Duration.ofSeconds(1), 0, 0);

  private static CloudBackendSupport support(int pace) {
    VoicedDialogueConfig config =
        new VoicedDialogueConfig() {
          @Override
          public int speakingPace() {
            return pace;
          }
        };
    return new CloudBackendSupport(config, VoicedDialogueConfig.TtsProvider.OPENROUTER, 2, INSTANT);
  }

  @Test
  public void warnOnceSurfacesEachFailureNoticeExactlyOnce() {
    CloudBackendSupport support = support(100);
    List<String> notices = new ArrayList<>();
    support.setNotice(notices::add);

    support.warnOnce("first failure");
    support.warnOnce("first failure");
    support.warnOnce("second failure");

    assertEquals(
        "a repeated failure says its piece once, a different one is not silenced by it",
        Arrays.asList("first failure", "second failure"),
        notices);
  }

  @Test
  public void missingKeyNoticeIsNotOnceGuarded() {
    CloudBackendSupport support = support(100);
    List<String> notices = new ArrayList<>();
    support.setNotice(notices::add);

    support.noticeMissingKey("no key");
    support.noticeMissingKey("no key");
    support.warnOnce("real failure");

    assertEquals(
        "the missing-key notice repeats and leaves the once-guard for a real failure",
        Arrays.asList("no key", "no key", "real failure"),
        notices);
  }

  @Test
  public void nullNoticeHookIsSafe() {
    CloudBackendSupport support = support(100);
    support.setNotice(null);
    support.warnOnce("dropped");
    support.noticeMissingKey("dropped");
  }

  @Test
  @Parameters(method = "speedPercentCases")
  public void speedPercentClampsToTheSupportedRange(int configured, int expected) {
    assertEquals(expected, support(configured).speedPercent());
  }

  private Object[] speedPercentCases() {
    return new Object[] {
      new Object[] {100, 100},
      new Object[] {50, 50},
      new Object[] {200, 200},
      new Object[] {10, 50},
      new Object[] {999, 200},
    };
  }

  @Test
  public void backoffWithZeroBudgetsReturnsImmediately() {
    long start = System.nanoTime();
    support(100).backoffBeforeNetworkRetry(1);
    assertTrue(
        "a zero base and jitter must not park the worker", CloudHttp.elapsedMs(start) < 1_000);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import org.junit.Test;

public class CloudCacheKeyBuilderTest {

  private static final VoiceSpec MAN = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE);

  private static String build(
      String voice, int speedPercent, CharacterProfile profile, String languageToken) {
    return CloudCacheKeyBuilder.build(voice, MAN, speedPercent, profile, languageToken);
  }

  @Test
  public void baseKeyIsVoiceSpeakerAndProfileWithNoOptionalFragments() {
    assertEquals(
        "every speaker resolves to a profile, so the profile fragment is part of the base key",
        "v|aMALE|p" + TestFixtures.TROLL_PROFILE.cacheKey(),
        build("v", 100, TestFixtures.TROLL_PROFILE, null));
  }

  @Test
  public void speedFragmentOnlyWhenNonDefault() {
    assertFalse(build("v", 100, TestFixtures.TROLL_PROFILE, null).contains("|s"));
    assertTrue(build("v", 150, TestFixtures.TROLL_PROFILE, null).contains("|s150"));
  }

  @Test
  public void twoProfilesNeverShareAKey() {
    assertNotEquals(
        build("v", 100, TestFixtures.TROLL_PROFILE, null),
        build("v", 100, TestFixtures.NARRATOR_PROFILE, null));
  }

  @Test
  public void aChildAndAnAdultOnTheSameVoiceNeverShareAKey() {
    VoiceSpec boy = VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE, 1, true);
    assertNotEquals(
        CloudCacheKeyBuilder.build("Puck", MAN, 100, TestFixtures.TROLL_PROFILE, null),
        CloudCacheKeyBuilder.build("Puck", boy, 100, TestFixtures.TROLL_PROFILE, null));
  }

  @Test
  public void theSpeakerTokenIsBuiltFromEnumNamesOnly() {
    assertEquals("MALE", CloudCacheKeyBuilder.speakerToken(MAN));
    assertEquals("MALE", CloudCacheKeyBuilder.speakerToken(VoiceSpec.player(NpcGender.MALE)));
    assertEquals(
        "CHILD_FEMALE",
        CloudCacheKeyBuilder.speakerToken(
            VoiceSpec.npc(NpcRace.GOBLIN, NpcGender.FEMALE, 3, true)));
    assertEquals("NARRATOR", CloudCacheKeyBuilder.speakerToken(VoiceSpec.NARRATOR));
  }

  @Test
  public void theRaceIsNotPartOfTheKey() {
    assertEquals(
        build("v", 100, TestFixtures.TROLL_PROFILE, null),
        CloudCacheKeyBuilder.build(
            "v",
            VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE),
            100,
            TestFixtures.TROLL_PROFILE,
            null));
  }

  @Test
  public void languageFragmentOnlyWhenThereIsALanguageToken() {
    assertTrue(build("v", 100, TestFixtures.TROLL_PROFILE, "FRENCH").endsWith("|lFRENCH"));
    assertFalse(build("v", 100, TestFixtures.TROLL_PROFILE, null).contains("|l"));
  }

  @Test
  public void theModelIsNotPartOfTheKey() {
    assertFalse(build("v", 100, TestFixtures.TROLL_PROFILE, null).contains("gemini"));
  }

  @Test
  public void fragmentsAreAppendedInVoiceSpeakerSpeedProfileLanguageOrder() {
    assertEquals(
        "v|aMALE|s150|p" + TestFixtures.TROLL_PROFILE.cacheKey() + "|lFRENCH+PIRATE",
        build("v", 150, TestFixtures.TROLL_PROFILE, "FRENCH+PIRATE"));
  }

  @Test
  public void theKeyForAFixedLineNeverChangesAcrossReleases() {
    CharacterProfile bartender =
        new CharacterProfile(
            "Bartender",
            "Strong London English accent, British English pronunciation",
            "Plain, friendly publican",
            "Steady and conversational.");
    assertEquals(
        "changing this key re-bills every cached line for every user",
        "en-gb-tutor-9|aMALE|p18cbc67f87f11541",
        build("en-gb-tutor-9", 100, bartender, null));
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import okhttp3.MediaType;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

public class CloudHttpTest {

  @Test
  public void isRejectedRequestCoversClientErrorsExceptRateLimits() {
    assertTrue(CloudHttp.isRejectedRequest(400));
    assertTrue(CloudHttp.isRejectedRequest(404));
    assertTrue(CloudHttp.isRejectedRequest(499));
    assertFalse(CloudHttp.isRejectedRequest(CloudHttp.HTTP_TOO_MANY_REQUESTS));
    assertFalse(CloudHttp.isRejectedRequest(399));
    assertFalse(CloudHttp.isRejectedRequest(500));
  }

  @Test
  public void isNonBlankRequiresANonWhitespaceCharacter() {
    assertFalse(CloudHttp.isNonBlank(null));
    assertFalse(CloudHttp.isNonBlank(""));
    assertFalse(CloudHttp.isNonBlank("   "));
    assertTrue(CloudHttp.isNonBlank("key"));
    assertTrue(CloudHttp.isNonBlank("  key  "));
  }

  @Test
  public void headerOrEmptyNeverReturnsNull() {
    Response response = response().newBuilder().header("Content-Type", "audio/pcm").build();
    assertEquals("audio/pcm", CloudHttp.headerOrEmpty(response, "Content-Type"));
    assertEquals("", CloudHttp.headerOrEmpty(response, "X-Missing"));
  }

  @Test
  public void errorBodyReadsTheBytesAndTreatsAMissingBodyAsEmpty() {
    Response withBody =
        response()
            .newBuilder()
            .body(ResponseBody.create(MediaType.parse("text/plain"), "quota exceeded"))
            .build();
    assertArrayEquals("quota exceeded".getBytes(), CloudHttp.errorBody(withBody));
    assertArrayEquals(new byte[0], CloudHttp.errorBody(response()));
  }

  @Test
  public void bodySnippetFlattensControlCharactersAndMarksTruncation() {
    assertEquals("line one line two", CloudHttp.bodySnippet("line one\n\nline two".getBytes()));

    assertTrue(
        "an over-long body is marked as truncated",
        CloudHttp.bodySnippet(filler(4_000)).endsWith("..."));
  }

  @Test
  public void bodySnippetKeepsAWholeQuotaFailureBody() {
    assertFalse(
        "the field naming the cause must survive the log",
        CloudHttp.bodySnippet(filler(1_500)).endsWith("..."));
  }

  @Test
  public void retryAfterIsReadOnlyWhenItNamesAUsableWait() {
    assertEquals(30_000, CloudHttp.retryAfterMillis(withRetryAfter("30")));
    assertEquals(
        "whitespace is not a malformation",
        5_000,
        CloudHttp.retryAfterMillis(withRetryAfter(" 5 ")));
    assertEquals("no header means the caller decides", 0, CloudHttp.retryAfterMillis(response()));
    assertEquals(
        "an HTTP-date is not read against a client clock",
        0,
        CloudHttp.retryAfterMillis(withRetryAfter("Wed, 21 Oct 2026 07:28:00 GMT")));
    assertEquals(0, CloudHttp.retryAfterMillis(withRetryAfter("soon")));
    assertEquals(
        "a wait already over is no wait", 0, CloudHttp.retryAfterMillis(withRetryAfter("0")));
    assertEquals(0, CloudHttp.retryAfterMillis(withRetryAfter("-30")));
    assertEquals(
        "an unrepresentable wait is unusable",
        0,
        CloudHttp.retryAfterMillis(withRetryAfter(String.valueOf(Long.MAX_VALUE))));
  }

  private static Response withRetryAfter(String value) {
    return response().newBuilder().header("Retry-After", value).build();
  }

  private static byte[] filler(int length) {
    byte[] bytes = new byte[length];
    Arrays.fill(bytes, (byte) 'a');
    return bytes;
  }

  private static Response response() {
    return new Response.Builder()
        .request(new Request.Builder().url("http://localhost/").build())
        .protocol(Protocol.HTTP_1_1)
        .code(200)
        .message("OK")
        .build();
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech;

import static com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp.HTTP_TOO_MANY_REQUESTS;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.CharacterProfile;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiTtsModel;
import com.grahambartley.runelite.voiced.dialogue.speech.model.GeminiVoiceMap;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class CloudSpeechExecutorTest {

  private MockWebServer server;
  private OkHttpClient client;

  private long bodyStatedWaitMillis;

  private CloudSpeechExecutor.SpokenLine spoken;

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new OkHttpClient();
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  @Test
  public void aRetryAfterHeaderAloneClosesTheBackend() {
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection().setHeader("Retry-After", "60"));

    assertNull(executor.synthesize(request()));

    assertTrue(executor.isThrottled());
    server.enqueue(rejection());
    assertNull("the header alone states a wait", executor.synthesize(request()));
    assertEquals("nothing follows a wait the provider stated", 1, server.getRequestCount());
  }

  @Test
  public void aBodyHintAloneClosesTheBackend() {
    bodyStatedWaitMillis = 60_000;
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection());

    assertNull(executor.synthesize(request()));

    server.enqueue(rejection());
    assertNull(executor.synthesize(request()));
    assertEquals(1, server.getRequestCount());
  }

  @Test
  public void aRejectionStatingNothingLeavesTheNextLineFree() {
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection());
    server.enqueue(rejection());

    assertNull(executor.synthesize(request()));

    assertTrue("speculation still stands down", executor.isThrottled());
    assertNull(executor.synthesize(request()));
    assertEquals("a guessed window never silences a user line", 2, server.getRequestCount());
  }

  @Test
  public void aHeaderAndABodyHintAreTakenAtWhicheverReachesFurther() {
    bodyStatedWaitMillis = 1;
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection().setHeader("Retry-After", "60"));

    assertNull(executor.synthesize(request()));

    server.enqueue(rejection());
    assertNull("the header outreaches the body hint here", executor.synthesize(request()));
    assertEquals(1, server.getRequestCount());
  }

  @Test
  public void aStatedWaitReadOffTheStreamedPathClosesTheBackendToo() {
    bodyStatedWaitMillis = 60_000;
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection());

    assertNull(executor.synthesizeStreaming(request(), (samples, rate) -> {}));

    server.enqueue(rejection());
    assertNull(
        "a wait stated to the stream still closes the backend", executor.synthesize(request()));
    assertEquals(1, server.getRequestCount());
  }

  @Test
  public void aClearedRateLimitLetsTheBackendSendAgain() {
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection().setHeader("Retry-After", "60"));
    assertNull(executor.synthesize(request()));

    executor.clearRateLimit();

    assertFalse(executor.isThrottled());
    server.enqueue(rejection());
    assertNull(executor.synthesize(request()));
    assertEquals("the line reaches the provider again", 2, server.getRequestCount());
  }

  @Test
  public void theSpokenLineCarriesOnlyTheTextWhileTheProfileRidesInTheStyle() {
    CloudSpeechExecutor executor = executor();
    server.enqueue(rejection());

    executor.synthesize(request());

    assertEquals("Hello", spoken.input);
    assertEquals(TestFixtures.TROLL_STYLE, spoken.style);
  }

  @Test
  public void theStyleNamesTheSpokenLanguageFromTheSettings() {
    MutableTestConfig config = new MutableTestConfig();
    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    server.enqueue(rejection());

    executor(config).synthesize(request());

    assertTrue(spoken.style.startsWith("Speaking French. A man's voice. Audio profile: Troll"));
  }

  @Test
  public void untranslatedTextIsStyledAsEnglishWhateverTheSpokenLanguage() {
    MutableTestConfig config = new MutableTestConfig();
    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    server.enqueue(rejection());

    executor(config)
        .synthesize(
            new SynthesisRequest(
                "Hello",
                VoiceSpec.player(NpcGender.MALE),
                Emotion.NEUTRAL,
                TestFixtures.TROLL_PROFILE,
                true,
                true));

    assertEquals("Hello", spoken.input);
    assertTrue(spoken.style.startsWith("Speaking English. "));
  }

  @Test
  public void aNonDefaultSpeedIsADirectionInTheStyle() {
    MutableTestConfig config = new MutableTestConfig();
    config.speedPercent = 80;
    server.enqueue(rejection());

    executor(config).synthesize(request());

    assertEquals(TestFixtures.TROLL_STYLE + " Speaking at 80% of normal speed.", spoken.style);
  }

  @Test
  public void theDefaultSpeedNeverAddsASpeedDirection() {
    server.enqueue(rejection());

    executor().synthesize(request());

    assertEquals(TestFixtures.TROLL_STYLE, spoken.style);
  }

  @Test
  public void cacheVariantFoldsInVoiceButNotModelSoRendersNeverCollide() {
    CloudSpeechExecutor executor = executor();

    SynthesisRequest humanMale = line(false, false);
    SynthesisRequest elfFemale =
        new SynthesisRequest(
            "a",
            VoiceSpec.npc(NpcRace.ELF, NpcGender.FEMALE),
            Emotion.NEUTRAL,
            TestFixtures.TROLL_PROFILE,
            false,
            false);

    String variant = executor.cacheVariant(humanMale);
    assertFalse(
        "the variant leaves the model out so a model swap keeps every cached clip",
        variant.contains("gemini"));
    assertTrue(
        "the variant carries the resolved Gemini voice",
        variant.contains(new GeminiVoiceMap().voiceFor(humanMale.voice(), null)));
    assertNotEquals(
        "two specs that map to different voices never share a variant",
        executor.cacheVariant(humanMale),
        executor.cacheVariant(elfFemale));
  }

  @Test
  public void cacheVariantFoldsInProfileSoDifferentProfilesNeverCollide() {
    CloudSpeechExecutor executor = executor();
    VoiceSpec voice = VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE);
    SynthesisRequest withProfile =
        new SynthesisRequest("a", voice, Emotion.NEUTRAL, TestFixtures.TROLL_PROFILE, false, false);
    SynthesisRequest otherProfile =
        new SynthesisRequest(
            "a",
            voice,
            Emotion.NEUTRAL,
            new CharacterProfile("Goblin", "East London.", "Mischievous.", "Quick."),
            false,
            false);

    assertTrue(
        "every line carries a profile, so every variant carries its fragment",
        executor.cacheVariant(withProfile).contains("|p"));
    assertTrue(
        "the fragment is the profile content key, which is what keeps cached audio addressable",
        executor.cacheVariant(withProfile).endsWith("|p" + TestFixtures.TROLL_PROFILE.cacheKey()));
    assertNotEquals(
        "two different profiles never share a variant",
        executor.cacheVariant(withProfile),
        executor.cacheVariant(otherProfile));
  }

  @Test
  public void cacheVariantChangesWithSpeedSoStaleAudioIsNeverServed() {
    MutableTestConfig config = new MutableTestConfig();
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest line = line(false, false);

    String atDefaultPace = executor.cacheVariant(line);
    config.speedPercent = 150;
    assertNotEquals(
        "a non-default pace must re-key so cached normal-pace audio is not served",
        atDefaultPace,
        executor.cacheVariant(line));
  }

  @Test
  public void globalQuirkPartitionsTheCacheKey() {
    MutableTestConfig config = new MutableTestConfig();
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest line = line(false, false);

    String plain = executor.cacheVariant(line);
    assertFalse("plain English with no style adds no language fragment", plain.contains("|l"));

    config.npcQuirk = VoicedDialogueConfig.SpeakingStyle.GEN_Z;
    assertNotEquals(
        "a style must not collide with the unstyled line", plain, executor.cacheVariant(line));
  }

  @Test
  public void perSpeakerClassStylePartitionsTheCacheKey() {
    MutableTestConfig config = new MutableTestConfig();
    config.playerQuirk = VoicedDialogueConfig.SpeakingStyle.GEN_Z;
    config.npcQuirk = VoicedDialogueConfig.SpeakingStyle.PIRATE;
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest playerLine = line(false, true);
    SynthesisRequest npcLine = line(false, false);

    assertNotEquals(
        "a player-styled and an NPC-styled line of the same text get distinct cache keys",
        executor.cacheVariant(playerLine),
        executor.cacheVariant(npcLine));
  }

  @Test
  public void styleOnOneClassLeavesTheOtherClassUntranslated() {
    MutableTestConfig config = new MutableTestConfig();
    config.playerQuirk = VoicedDialogueConfig.SpeakingStyle.NONE;
    config.npcQuirk = VoicedDialogueConfig.SpeakingStyle.GEN_Z;
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest playerLine = line(false, true);
    SynthesisRequest npcLine = line(false, false);

    assertFalse(
        "the player line, player style None, carries no language fragment so it skips translation",
        executor.cacheVariant(playerLine).contains("|l"));
    assertTrue(
        "the NPC line, NPC style Gen Z, folds the styled language into its key",
        executor.cacheVariant(npcLine).contains("|l"));
  }

  @Test
  public void nonEnglishTargetFoldsLanguageIntoTheCacheVariant() {
    MutableTestConfig config = new MutableTestConfig();
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest line = line(false, false);

    String english = executor.cacheVariant(line);
    assertFalse("English (default) adds no language fragment", english.contains("|l"));

    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    String french = executor.cacheVariant(line);
    assertNotEquals(
        "the same line in another language must not share a cache key", english, french);
    assertTrue("the language is folded in", french.contains("|lFRENCH"));
  }

  @Test
  public void skipTranslationOmitsTheLanguageFragmentFromTheCacheVariant() {
    MutableTestConfig config = new MutableTestConfig();
    config.language = VoicedDialogueConfig.SpokenLanguage.FRENCH;
    CloudSpeechExecutor executor = executor(config);
    SynthesisRequest dialogue = line(false, false);
    SynthesisRequest publicChat = line(true, false);

    assertTrue(
        "a translated dialogue line still folds the language in",
        executor.cacheVariant(dialogue).contains("|lFRENCH"));
    assertFalse(
        "a skip-translation line keeps the plain pre-translation key",
        executor.cacheVariant(publicChat).contains("|l"));
    assertNotEquals(
        "so an untranslated public-chat clip never collides with a translated dialogue line of the"
            + " same text",
        executor.cacheVariant(dialogue),
        executor.cacheVariant(publicChat));
  }

  private CloudSpeechExecutor executor() {
    return executor(new MutableTestConfig());
  }

  private CloudSpeechExecutor executor(MutableTestConfig config) {
    CloudBackendSupport support =
        new CloudBackendSupport(
            config,
            VoicedDialogueConfig.TtsProvider.OPENROUTER,
            CloudSpeechExecutor.MAX_SPEECH_ATTEMPTS,
            RetryTuning.openRouter());
    return new CloudSpeechExecutor(
        config, support, new GeminiTtsModel(), "Test provider", new StubOps());
  }

  private MockResponse rejection() {
    return new MockResponse().setResponseCode(HTTP_TOO_MANY_REQUESTS).setBody("{}");
  }

  private static SynthesisRequest request() {
    return new SynthesisRequest(
        "Hello",
        VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE),
        Emotion.NEUTRAL,
        TestFixtures.TROLL_PROFILE,
        false,
        false);
  }

  private static SynthesisRequest line(boolean skipTranslation, boolean player) {
    return new SynthesisRequest(
        "a",
        VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE),
        Emotion.NEUTRAL,
        TestFixtures.TROLL_PROFILE,
        skipTranslation,
