package com.grahambartley.runelite.voiced.dialogue.speech.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class GeminiVoiceRegionsTest {

  private static final String JSON =
      "{\"SCOTTISH\":{\"playerKeywords\":[\"scottish\",\"glasgow\"],"
          + "\"MALE\":[\"gb-m-1\",\"gb-m-2\",\"gb-m-3\",\"gb-m-4\"],\"FEMALE\":[]},"
          + "\"IRISH\":{\"playerKeywords\":[\"irish\",\"dublin\"],"
          + "\"MALE\":[\"ie-m-1\",\"ie-m-2\"],\"FEMALE\":[\"ie-f-1\"]},"
          + "\"SOUTHERN_ENGLISH\":{\"playerKeywords\":[\"southern\",\"received pronunciation\"],"
          + "\"MALE\":[\"en-m-1\"],\"FEMALE\":[\"en-f-1\"]}}";

  private static GeminiVoiceRegions regions(String json) {
    return new GeminiVoiceRegions(new JsonParser().parse(json).getAsJsonObject());
  }

  private static final GeminiVoiceRegions REGIONS = regions(JSON);

  private static final GeminiVoiceRegions PINNED_IRISH =
      regions(
          JSON.replace(
              "\"FEMALE\":[\"ie-f-1\"]", "\"FEMALE\":[\"ie-f-1\"],\"PLAYER_MALE\":\"ie-m-2\""));

  @Test
  public void aPinnedPlayerVoiceWinsOverTheSeededPick() {
    assertNotEquals("ie-m-2", REGIONS.voiceFor("IRISH", NpcGender.MALE, 0));
    assertEquals("ie-m-2", PINNED_IRISH.playerVoiceFor("IRISH", NpcGender.MALE, 0));
    assertEquals("ie-f-1", PINNED_IRISH.playerVoiceFor("IRISH", NpcGender.FEMALE, 0));
  }

  @Test
  public void anUnpinnedPlayerTakesTheSeededPick() {
    assertEquals(
        REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, 0),
        REGIONS.playerVoiceFor("SCOTTISH", NpcGender.MALE, 0));
    assertNull(REGIONS.playerVoiceFor(null, NpcGender.MALE, 0));
  }

  @Test
  public void aPinnedPlayerVoiceLeavesNpcPicksAlone() {
    for (int seed = 0; seed < 50; seed++) {
      assertEquals(
          REGIONS.voiceFor("IRISH", NpcGender.MALE, seed),
          PINNED_IRISH.voiceFor("IRISH", NpcGender.MALE, seed));
    }
  }

  @Test
  public void anNpcAlwaysGetsTheSameVoice() {
    String first = REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, 4242);
    for (int i = 0; i < 20; i++) {
      assertEquals(first, REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, 4242));
      assertEquals(first, regions(JSON).voiceFor("SCOTTISH", NpcGender.MALE, 4242));
    }
  }

  @Test
  public void theVoiceComesFromThePoolForTheGender() {
    assertTrue(REGIONS.voiceFor("IRISH", NpcGender.MALE, 7).startsWith("ie-m-"));
    assertEquals("ie-f-1", REGIONS.voiceFor("IRISH", NpcGender.FEMALE, 7));
  }

  @Test
  public void differentNpcsSpreadAcrossThePool() {
    Set<String> voices = new HashSet<>();
    for (int seed = 0; seed < 200; seed++) {
      voices.add(REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, seed));
    }
    assertEquals(4, voices.size());
  }

  @Test
  public void addingAVoiceOnlyMovesTheNpcsThatNowPickIt() {
    GeminiVoiceRegions grown = regions(JSON.replace("\"gb-m-4\"]", "\"gb-m-4\",\"gb-m-5\"]"));
    for (int seed = 0; seed < 500; seed++) {
      String before = REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, seed);
      String after = grown.voiceFor("SCOTTISH", NpcGender.MALE, seed);
      assertTrue(after.equals(before) || after.equals("gb-m-5"));
    }
  }

  @Test
  public void anEmptyPoolForTheGenderHasNoVoice() {
    assertNull(REGIONS.voiceFor("SCOTTISH", NpcGender.FEMALE, 1));
  }

  @Test
  public void anUnknownOrMissingRegionHasNoVoice() {
    assertNull(REGIONS.voiceFor("WELSH", NpcGender.MALE, 1));
    assertNull(REGIONS.voiceFor(null, NpcGender.MALE, 1));
  }

  @Test
  public void theTypedAccentPicksTheFirstRegionWhoseKeywordItNames() {
    assertEquals(
        "IRISH",
        REGIONS.regionForAccent("Strong Dublin Irish accent, Irish English pronunciation"));
    assertEquals("SCOTTISH", REGIONS.regionForAccent("Glasgow, as heard in Scotland"));
    assertEquals("SCOTTISH", REGIONS.regionForAccent("Scottish by birth, southern by upbringing"));
  }

  @Test
  public void keywordsMatchWholeWordsCaseInsensitively() {
    assertEquals("SOUTHERN_ENGLISH", REGIONS.regionForAccent("Received Pronunciation"));
    assertNull(REGIONS.regionForAccent("Irishman-ish"));
  }

  @Test
  public void anAccentNamingNoRegionHasNone() {
    assertNull(REGIONS.regionForAccent("Strong Welsh accent, Welsh English pronunciation"));
    assertNull(REGIONS.regionForAccent(null));
  }

  @Test
  public void theBundledKeywordsSendNorthernIrishToIrishAndTheDefaultToSouthernEnglish() {
    GeminiVoiceRegions bundled = GeminiVoiceRegions.bundled();
    assertEquals(
        "IRISH",
        bundled.regionForAccent("Strong Northern Irish accent, Irish English pronunciation"));
    assertEquals(
        "SOUTHERN_ENGLISH",
        bundled.regionForAccent(
            "Strong friendly, down-to-earth southern English accent, British English pronunciation"));
    assertEquals(
        "NORSE",
        bundled.regionForAccent(
            "Strong Norse Scandinavian accent, Scandinavian-accented English pronunciation"));
    assertEquals(
        "INDIAN_ENGLISH",
        bundled.regionForAccent("Strong Indian accent, Indian English pronunciation"));
    assertEquals("INDIAN_ENGLISH", bundled.regionForAccent("Strong accent from south India"));
    assertEquals("INDIAN_ENGLISH", bundled.regionForAccent("Strong West Indian accent"));
    assertNull(bundled.regionForAccent("Strong Southern American accent"));
  }

  @Test
  public void theBundledTrollPoolHoldsOnlyTheTwoDeepestSouthernEnglishMen() {
    GeminiVoiceRegions bundled = GeminiVoiceRegions.bundled();
    Set<String> voiced = new HashSet<>();
    for (int seed = 0; seed < 200; seed++) {
      voiced.add(bundled.voiceFor("DEEP_SOUTHERN_ENGLISH", NpcGender.MALE, seed));
    }
    assertEquals(new HashSet<>(Arrays.asList("en-gb-advisor-8", "en-gb-assistant-2")), voiced);
  }

  @Test
  public void noChildSharesAVoiceWithTheTrolls() {
    GeminiVoiceRegions bundled = GeminiVoiceRegions.bundled();
    Set<String> trolls = new HashSet<>();
    for (int seed = 0; seed < 200; seed++) {
      trolls.add(bundled.voiceFor("DEEP_SOUTHERN_ENGLISH", NpcGender.MALE, seed));
    }
    for (String region : new String[] {"DEEP_SOUTHERN_ENGLISH", "SOUTHERN_ENGLISH"}) {
      for (int seed = 0; seed < 200; seed++) {
        String child = bundled.childVoiceFor(region, NpcGender.MALE, seed);
        assertNotNull(region, child);
        assertFalse(region, trolls.contains(child));
      }
    }
  }

  @Test
  public void theBundledIndianEnglishPoolsHoldOnlyIndianEnglishVoices() {
    GeminiVoiceRegions bundled = GeminiVoiceRegions.bundled();
    Set<String> readAsBritish =
        new HashSet<>(Arrays.asList("en-in-advisor-9", "en-in-assistant-10", "en-in-concierge-1"));
    for (NpcGender gender : new NpcGender[] {NpcGender.MALE, NpcGender.FEMALE}) {
      for (int seed = 0; seed < 200; seed++) {
        String adult = bundled.voiceFor("INDIAN_ENGLISH", gender, seed);
        String child = bundled.childVoiceFor("INDIAN_ENGLISH", gender, seed);
        assertTrue(adult, adult.startsWith("en-in-"));
        assertTrue(child, child.startsWith("en-in-"));
        assertFalse(adult, readAsBritish.contains(adult));
        assertFalse(child, readAsBritish.contains(child));
      }
    }
  }

  @Test
  public void anEmptyTableVoicesNothing() {
    GeminiVoiceRegions empty = new GeminiVoiceRegions(new JsonObject());
    assertNull(empty.voiceFor("IRISH", NpcGender.MALE, 1));
    assertNull(empty.regionForAccent("Irish"));
  }

  @Test
  public void theBundledTableCarriesNativeVoicesForEachGender() {
    GeminiVoiceRegions bundled = GeminiVoiceRegions.bundled();
    for (String region :
        new String[] {
          "IRISH", "SCOTTISH", "SOUTHERN_ENGLISH", "ITALIAN", "NORSE", "INDIAN_ENGLISH"
        }) {
      assertNotNull(region, bundled.voiceFor(region, NpcGender.MALE, 1));
      assertNotNull(region, bundled.voiceFor(region, NpcGender.FEMALE, 1));
    }
    assertFalse(bundled.voiceFor("IRISH", NpcGender.MALE, 1).isEmpty());
  }

  private static final GeminiVoiceRegions AGED =
      new GeminiVoiceRegions(
          new JsonParser()
              .parse(
                  "{\"SE\":{\"MALE\":[\"m25\",\"m28\",\"m32\",\"m35\",\"m46\",\"m49\",\"m55\","
                      + "\"m-unknown\"]}}")
              .getAsJsonObject(),
          null,
          ages());

  private static java.util.Map<String, Integer> ages() {
    java.util.Map<String, Integer> ages = new java.util.HashMap<>();
    ages.put("m25", 25);
    ages.put("m28", 28);
    ages.put("m32", 32);
    ages.put("m35", 35);
    ages.put("m46", 46);
    ages.put("m49", 49);
    ages.put("m55", 55);
    return ages;
  }

  @Test
  public void anOldNpcTakesTheOldestVoicesWhenNoneAreWithinTheWindow() {
    Set<String> voices = new HashSet<>();
    for (int seed = 0; seed < 200; seed++) {
      voices.add(AGED.voiceFor("SE", NpcGender.MALE, seed, 70));
    }
    assertEquals(new HashSet<>(Arrays.asList("m46", "m49", "m55")), voices);
  }

  private Set<String> voicesAt(int age) {
    Set<String> voices = new HashSet<>();
    for (int seed = 0; seed < 300; seed++) {
      voices.add(AGED.voiceFor("SE", NpcGender.MALE, seed, age));
    }
    return voices;
  }

  @Test
  public void anAgeTakesEveryVoiceWithinTheWindow() {
    assertEquals(new HashSet<>(Arrays.asList("m25", "m28", "m32", "m35")), voicesAt(30));
  }

  @Test
  public void aVoiceWithNoKnownAgeNeverMatchesAnAge() {
    for (int age = 1; age <= 120; age += 7) {
      assertFalse(voicesAt(age).contains("m-unknown"));
    }
  }

  @Test
  public void noAgeKeepsTheSeededPickFromTheWholePool() {
    for (int seed = 0; seed < 50; seed++) {
      assertEquals(
          AGED.voiceFor("SE", NpcGender.MALE, seed),
          AGED.voiceFor("SE", NpcGender.MALE, seed, null));
    }
  }

  @Test
  public void aPoolWithNoKnownAgesIgnoresTheAge() {
    for (int seed = 0; seed < 50; seed++) {
      assertEquals(
          REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, seed),
          REGIONS.voiceFor("SCOTTISH", NpcGender.MALE, seed, 70));
    }
  }

  @Test
  public void anAgedNpcStillKeepsOneVoiceForLife() {
    String first = AGED.voiceFor("SE", NpcGender.MALE, 3480, 65);
    for (int i = 0; i < 10; i++) {
      assertEquals(first, AGED.voiceFor("SE", NpcGender.MALE, 3480, 65));
    }
  }

  @Test
  public void bundledAgesAreReadFromTheRoot() {
    JsonObject root =
        new JsonParser()
            .parse("{\"voiceAges\":{\"a\":40,\"b\":61,\"c\":\"old\"}}")
            .getAsJsonObject();
    assertEquals(Integer.valueOf(61), GeminiVoiceRegions.ages(root).get("b"));
    assertFalse("a non-numeric age is skipped", GeminiVoiceRegions.ages(root).containsKey("c"));
    assertTrue(GeminiVoiceRegions.ages(new JsonObject()).isEmpty());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class OpenRouterCreditMeterTest {

  private static final double TOLERANCE = 1e-9;

  @Test
  public void spendIsTheRiseAboveTheSessionBaseline() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertEquals(0.1187, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }

  @Test
  public void spendIsUnknownUntilABaselineIsTaken() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();

    assertNull(
        "an unread balance must never be reported as a free session",
        meter.spentSince("sk-or-abc", 4.6187));
    assertFalse(meter.hasBaselineFor("sk-or-abc"));
  }

  @Test
  public void anUnreadableBaselineIsNotBanked() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", null);

    assertFalse("a failed read leaves the meter unarmed", meter.hasBaselineFor("sk-or-abc"));
    assertNull(meter.spentSince("sk-or-abc", 4.6187));
  }

  @Test
  public void aSecondBaselineForTheSameKeyNeverErasesSpendAlreadyMade() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);
    meter.recordBaseline("sk-or-abc", 4.6000);

    assertEquals(
        "a re-warm mid-session must not rebase and hide what was already spent",
        0.1187,
        meter.spentSince("sk-or-abc", 4.6187),
        TOLERANCE);
  }

  @Test
  public void aSwappedKeyIsMeasuredFromItsOwnBaseline() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertNull(
        "usage on a different key is a different running total, so it cannot be subtracted",
        meter.spentSince("sk-or-xyz", 90.0));

    meter.recordBaseline("sk-or-xyz", 90.0);
    assertEquals(0.25, meter.spentSince("sk-or-xyz", 90.25), TOLERANCE);
  }

  @Test
  public void aBalanceBelowTheBaselineClampsToZeroRatherThanGoingNegative() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertEquals(0.0, meter.spentSince("sk-or-abc", 4.0000), TOLERANCE);
  }

  @Test
  public void anUnreadableCurrentBalanceLeavesSpendUnknown() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);

    assertNull(meter.spentSince("sk-or-abc", null));
  }

  @Test
  public void resetStartsAFreshMeasurement() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("sk-or-abc", 4.5000);
    meter.reset();

    assertFalse(meter.hasBaselineFor("sk-or-abc"));
    meter.recordBaseline("sk-or-abc", 4.6187);
    assertEquals(0.0, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }

  @Test
  public void keysAreComparedIgnoringSurroundingWhitespace() {
    OpenRouterCreditMeter meter = new OpenRouterCreditMeter();
    meter.recordBaseline("  sk-or-abc  ", 4.5000);

    assertTrue(meter.hasBaselineFor("sk-or-abc"));
    assertEquals(0.1187, meter.spentSince("sk-or-abc", 4.6187), TOLERANCE);
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.enqueuePcm;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.keyedConfig;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.req;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.sentBody;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.shutDownQuietly;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.startedServer;
import static com.grahambartley.runelite.voiced.dialogue.speech.openrouter.OpenRouterRequests.style;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import com.google.gson.JsonObject;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.TestFixtures;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class OpenRouterProviderTest {

  private MockWebServer server;
  private OkHttpClient client;

  @Before
  public void setUp() throws Exception {
    server = startedServer();
    client = new OkHttpClient();
  }

  @After
  public void tearDown() {
    shutDownQuietly(server);
  }

  private OpenRouterTtsBackend backend(VoicedDialogueConfig config) {
    return OpenRouterRequests.backend(client, server, config);
  }

  @Test
  public void alwaysPinsThroughputSort() {
    JsonObject body = new JsonObject();
    OpenRouterProvider.apply(body);

    JsonObject provider = body.getAsJsonObject("provider");
    assertEquals(
        "every call routes to the fastest provider (the :nitro equivalent)",
        "throughput",
        provider.get("sort").getAsString());
    assertFalse("plain routing carries no provider options", provider.has("options"));
  }

  @Test
  public void speechMetadataMergesIntoTheThroughputProviderBlock() {
    JsonObject metadata = new JsonObject();
    metadata.addProperty("style", "Calm.");
    JsonObject body = new JsonObject();
    OpenRouterProvider.apply(body, metadata);

    JsonObject provider = body.getAsJsonObject("provider");
    assertEquals("throughput", provider.get("sort").getAsString());
    assertEquals(
        "Calm.",
        provider
            .getAsJsonObject("options")
            .getAsJsonObject("google-ai-studio")
            .getAsJsonObject("speech_metadata")
            .get("style")
            .getAsString());
  }

  @Test
  public void profileAndEmotionTravelInProviderOptionsNotInTheInput() throws Exception {
    enqueuePcm(server, (short) 1);

    backend(keyedConfig())
        .synthesize(
            new SynthesisRequest(
                "You no take candle!",
                VoiceSpec.npc(NpcRace.TROLL, NpcGender.MALE),
                Emotion.ANGRY,
                TestFixtures.TROLL_PROFILE,
                false,
                false));

    JsonObject body = sentBody(server);
    assertEquals("You no take candle!", body.get("input").getAsString());
    assertEquals(TestFixtures.TROLL_STYLE + " Sounding angry.", style(body));
    assertEquals(
        "the speech options merge into the throughput routing block",
        "throughput",
        body.getAsJsonObject("provider").get("sort").getAsString());
  }

  @Test
  public void everyRequestRoutesForThroughput() throws Exception {
    enqueuePcm(server, (short) 1);

    backend(keyedConfig()).synthesize(req());

    assertEquals(
        "every TTS call asks for the fastest provider",
        "throughput",
        sentBody(server).getAsJsonObject("provider").get("sort").getAsString());
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import static java.net.HttpURLConnection.HTTP_OK;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.audio.TestPcm;
import com.grahambartley.runelite.voiced.dialogue.profile.Emotion;
import com.grahambartley.runelite.voiced.dialogue.profile.VoiceSpec;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcGender;
import com.grahambartley.runelite.voiced.dialogue.speaker.NpcRace;
import com.grahambartley.runelite.voiced.dialogue.speech.MutableTestConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.RetryTuning;
import com.grahambartley.runelite.voiced.dialogue.speech.SynthesisRequest;
import com.grahambartley.runelite.voiced.dialogue.speech.TestFixtures;
import java.io.IOException;
import java.time.Duration;
import java.util.Arrays;
import java.util.List;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import okio.Buffer;

final class OpenRouterRequests {

  static final RetryTuning FAST_RETRY =
      new RetryTuning(Duration.ofMillis(500), Duration.ofMillis(200), Duration.ofSeconds(1), 10, 0);

  private static final String SPEECH_PATH = "/api/v1/audio/speech";

  private OpenRouterRequests() {}

  static MockWebServer startedServer() throws IOException {
    MockWebServer server = new MockWebServer();
    server.start();
    return server;
  }

  static void shutDownQuietly(MockWebServer server) {
    try {
      server.shutdown();
    } catch (Exception ignored) {
    }
  }

  static OpenRouterTtsBackend backend(
      OkHttpClient client, MockWebServer server, VoicedDialogueConfig config) {
    return new OpenRouterTtsBackend(client, config, new Gson(), server.url(SPEECH_PATH).toString());
  }

  static OpenRouterTtsBackend backend(
      OkHttpClient client, MockWebServer server, VoicedDialogueConfig config, RetryTuning tuning) {
    return new OpenRouterTtsBackend(
        client, config, new Gson(), server.url(SPEECH_PATH).toString(), tuning);
  }

  static MutableTestConfig keyedConfig() {
    MutableTestConfig config = new MutableTestConfig();
    config.openRouterKey = "sk-or-abc";
    return config;
  }

  static SynthesisRequest req() {
    return line("Hello & welcome");
  }

  static SynthesisRequest line(String text) {
    return line(text, Emotion.NEUTRAL, false, false);
  }

  static SynthesisRequest line(
      String text, Emotion emotion, boolean skipTranslation, boolean player) {
    return new SynthesisRequest(
        text,
        VoiceSpec.npc(NpcRace.HUMAN, NpcGender.MALE),
        emotion,
        TestFixtures.TROLL_PROFILE,
        skipTranslation,
        player);
  }

  static void enqueuePcm(MockWebServer server, short... samples) {
    server.enqueue(
        new MockResponse()
            .setResponseCode(HTTP_OK)
            .setBody(new Buffer().write(TestPcm.raw(samples))));
  }

  static void enqueueChat(MockWebServer server, String content) {
    server.enqueue(
        new MockResponse().setResponseCode(HTTP_OK).setBody(TestFixtures.chatResponse(content)));
  }

  static JsonObject body(RecordedRequest request) {
    return new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
  }

  static JsonObject sentBody(MockWebServer server) throws InterruptedException {
    return body(server.takeRequest());
  }

  static JsonObject bodyForEmotion(
      OpenRouterTtsBackend backend, MockWebServer server, Emotion emotion)
      throws InterruptedException {
    enqueuePcm(server, (short) 1);
    backend.synthesize(line("Hello & welcome", emotion, false, false));
    return sentBody(server);
  }

  static String style(JsonObject body) {
    return body.getAsJsonObject("provider")
        .getAsJsonObject("options")
        .getAsJsonObject("google-ai-studio")
        .getAsJsonObject("speech_metadata")
        .get("style")
        .getAsString();
  }

  static short[] truncatedAudio() {
    short[] s = new short[36_000];
    Arrays.fill(s, (short) 12_000);
    return s;
  }

  static short[] completeAudio() {
    short[] s = new short[40_800];
    Arrays.fill(s, 0, 36_000, (short) 12_000);
    return s;
  }

  static float[] concat(List<float[]> chunks) {
    int total = 0;
    for (float[] chunk : chunks) {
      total += chunk.length;
    }
    float[] out = new float[total];
    int pos = 0;
    for (float[] chunk : chunks) {
      System.arraycopy(chunk, 0, out, pos, chunk.length);
      pos += chunk.length;
    }
    return out;
  }
}

package com.grahambartley.runelite.voiced.dialogue.speech.openrouter;

import static com.grahambartley.runelite.voiced.dialogue.speech.CloudHttp.HTTP_TOO_MANY_REQUESTS;
import static java.net.HttpURLConnection.HTTP_OK;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grahambartley.runelite.voiced.dialogue.VoicedDialogueConfig;
import com.grahambartley.runelite.voiced.dialogue.speech.TestFixtures;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class OpenRouterTranslatorTest {

  private MockWebServer server;
  private OkHttpClient client;
  private final Gson gson = new Gson();
  private final VoicedDialogueConfig config = new VoicedDialogueConfig() {};

  @Before
  public void setUp() throws Exception {
    server = new MockWebServer();
    server.start();
    client = new OkHttpClient();
  }

  @After
  public void tearDown() throws Exception {
    server.shutdown();
  }

  private OpenRouterTranslator translator() {
    return new OpenRouterTranslator(
        client, config, gson, server.url("/api/v1/chat/completions").toString());
  }

  @Test
  public void translatesAndReturnsTrimmedContent() throws Exception {
    server.enqueue(
        new MockResponse()
            .setResponseCode(HTTP_OK)
            .setBody(TestFixtures.chatResponse("  Bonjour  ")));

    String result = translator().translate("Hello", "French", "sk-or-abc");

    assertEquals("Bonjour", result);

    RecordedRequest recorded = server.takeRequest();
    assertEquals("POST", recorded.getMethod());
    assertEquals("Bearer sk-or-abc", recorded.getHeader("Authorization"));
    assertEquals(
        "the OpenRouter app name is attributed",
        "RuneLite Voiced Dialogue",
        recorded.getHeader("X-Title"));
    JsonObject body = new JsonParser().parse(recorded.getBody().readUtf8()).getAsJsonObject();
    assertEquals("google/gemini-3.1-flash-lite", body.get("model").getAsString());
    assertEquals(
        "throughput routing applies to the translation hop too",
        "throughput",
        body.getAsJsonObject("provider").get("sort").getAsString());
    JsonArray messages = body.getAsJsonArray("messages");
    assertEquals("system prompt then user line", 2, messages.size());
    assertEquals("system", messages.get(0).getAsJsonObject().get("role").getAsString());
    assertEquals(
        "the per-line text is the user message, keeping the system prefix stable",
        "Hello",
        messages.get(1).getAsJsonObject().get("content").getAsString());
  }

  @Test
  public void nonSuccessReturnsNull() {
    server.enqueue(
        new MockResponse().setResponseCode(HTTP_TOO_MANY_REQUESTS).setBody("rate limited"));
    assertNull(translator().translate("Hello", "French", "sk-or-abc"));
  }

  @Test
